-- ─────────────────────────────────────────────────────────────
--  THE OLD WEBSITE'S NEWS — part 3 of 7: 74 articles kept as drafts (not live)
--  Generated by scripts/import-old-news.py from Rich's export of the old WordPress database.
--  Run the news files in order, after the other files in supabase/legacy/ (SQL Editor → paste → Run), each once.
--
--  All 528 old articles: 186 league and competition articles from 2019 on go live, with their real dates.
--  The other 342 wait in Admin → News as drafts (Rich, round 30): Professional Snooker, CueViews,
--  Snooker Memories, and the old archive — whose articles all carry the date 1 January 2014 on the old site
--  (their real dates were lost long ago). Tick "Published" on any of them to put it on the website.
--  The text keeps its paragraphs, the opening paragraph and the pull quote. Pictures are not brought across
--  (Rich is sorting them): real-data/legacy/news-pictures.csv says which article had which picture.
--  None is "featured", so the News page and the banner keep showing the newest articles.
--  Nothing already on the website is changed. All one transaction.
-- ─────────────────────────────────────────────────────────────
begin;

do $$ begin
  if exists (select 1 from articles where slug in ('82-break-for-local-legend', 'a-polished-performance', 'alex-higgins-the-best-break-ever', 'alexander-the-great-40-years-on', 'all-matches-finish-3-2-in-extraordinary-night')) then
    raise exception 'This part of the old news is already in: nothing to do.';
  end if;
end $$;

insert into categories (name, sort)
  select r.name, 100 + row_number() over (order by r.name) from (values
  ('Competitions'),
  ('Cue View'),
  ('League Meetings'),
  ('League News'),
  ('Match Reports'),
  ('Professional Snooker'),
  ('Snooker Memories')) r(name)
  where not exists (select 1 from categories c where lower(c.name) = lower(r.name));

create temp table _news (title text, slug text, category text, more_categories jsonb, excerpt text, lead text, quote_text text, body text, published_at date, is_published boolean, author text) on commit drop;
insert into _news values
  ('82-break for local legend', '82-break-for-local-legend', 'Match Reports', '[]'::jsonb, 'There is only one place to start this week in the St Blazey and District Snooker League and that is at Mevagissey.', null, '"With the Bugle ‘B’ and Tregonissey match not being played until Monday it have Bugle ‘A’ the chance to open up a big lead at the top which they duly took by whitewashing St Neot 5-0, with Andrew Best registering a 30 break."', 'There is only one place to start this week in the St Blazey and District Snooker League and that is at Mevagissey.

more heir ‘A’ team’s home match with St Blazey ‘A’ saw snooker legend Leighton Varcoe produce a stunning 82-break with the watching crowd reporting perfect cue-ball control and pitting speed throughout – well done Leighton. Sadly for Meva it was their only success as the Blazey boys continued their great start to the season. With the Bugle ‘B’ and Tregonissey match not being played until Monday it have Bugle ‘A’ the chance to open up a big lead at the top which they duly took by whitewashing St Neot 5-0, with Andrew Best registering a 30 break. Bethel ‘D’s woes continue with Lostwithiel ‘B’ going home with a 4-1 victory with the returning Jason Hill knocking in a 35-break and Bethel ‘A’ got a good 3-2 victory at Lostwithiel ‘A’ with Leon Collard defeating Darren Lock by a point which was all the more impressive as he needed two snookers with the colours up. Bethel ‘C’ went top of the Rees League pipping Mevagissey ‘D’ for whom James Tomlinson and Rob Blamey were victorious. St Stephen moved up to second after seeing off Bugle ‘C’ in a very-tight encounter with Mike Pascoe still unbeaten so far this season. Mevagissey ‘C’ found some form to overcome Bethe ‘B’ 3-2 as Joe and Matt Chesterfield and Charlie Prynn were their winners. Bodmin Sparks moved to within three points of the top as they returned from Lerryn with a 4-1 victory with Gordon Brimicombe registering for the basement boys.

FULL RESULTS

Victory League: Bethel ‘D’ 1 (M Knight) Lostwithiel ‘B’ 4 (J Daniell, L Flower, J Hill (34), A Parnell), Lostwithiel ‘A’ 2 (M Dunstan, D Northcott) Bethel ‘A’ 3 (M Powell, G Hawken, L Collard), Mevagissey ‘A’ 1 (L Varcoe (82)) St Blazey ‘A’ 4 (M Meares, S Dewings, L Rosevear, C Brown), St Neot 0 Bugle ‘A’ 5 (A Peers), A Best (30), G Spencer, P Sturthridge, I Powell). Rees Memorial League: St Stephen 3 (J Bennett, C Clark, A Harrison) Bugle ‘C’ 2 (M Pascoe, J Conroy), Bethel ‘C’ 3 (C Crockford, H Brett, S Jones) Mevagissey ‘D’ 2 (R Blamey, J Tomlinson), Lerryn 1 (G Brimicombe) Sparks 4 (R Bolt, S Bampton, C Stuthridge (33), M Williams), Mevagissey ‘C’ 3 (J Chesterfield, M Chesterfield, C Prynn) Bethel ‘B’ 2 (J Tamblyn, S Hicks). Top breaks of the week: L Varcoe 82, J Hill 34, A Best 30 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('A Polished performance', 'a-polished-performance', 'Professional Snooker', '[]'::jsonb, 'The true champions of our sport know how to win at all costs. Neil Robertson is fast-becoming one of snooker''s real winners.', null, '"He had his back to the wall but saw out the job. This ability to mix it up and win when it’s not going so well will be a valuable tool in the years ahead as he strives towards more titles."', 'The true champions of our sport know how to win at all costs. Neil Robertson is fast-becoming one of snooker''s real winners.

more At his best, the Aussie is a formidable force. He has been one of the best long-potters in the game since he first burst onto the professional circuit. It''s now an insult to regard him as just that. These days, he has the break-building skill, tactical nous and big-match mentality to lay claim to being one of the best all-rounders. He is quite the package combining the attributes of the modern-day player with some of the traditional ingredients of champions in past eras. And this is why many propose he could be - or become - one of the game''s greatest foreign imports. It is easy to understand on this basis why Robertson is held with such high esteem, but his capture of the Polish Open highlighted another of his developing strengths: his ability to win ugly. As he raced into a 3-0 lead against Jamie Burnett in this European PTC final in Gdynia it looked as if he would win with ease. But plagued by kicks and tormented by his own frustration, he struggled to see out the match. In the closing stages it looked all the more like we might be witnessing the most unlikeliest of comebacks Robertson managed to find something in a scrappy decider to squirm past the winning post, and that''s all that mattered. He had his back to the wall but saw out the job. This ability to mix it up and win when it''s not going so well will be a valuable tool in the years ahead as he strives towards more titles. The likes of John Higgins and Stephen Hendry have always found a way to win even when it''s not been easy and the ambitious Aussie will need to do exactly the same if he is to reach the level of these greats. This may not always earn universal praise, but it remains essential. Although not entirely polished, this Polish performance showed that Robertson is well on the way to acquiring all the skills he needs to achieve greatness. Victory here also showcases his fine consistency as he''s now won a ranking event in each of the last seven seasons. Well played Neil. You have many more titles to come. Article courtesy of OnCue Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('Alex Higgins - The best break ever?', 'alex-higgins-the-best-break-ever', 'Professional Snooker', '[]'::jsonb, 'His 16-15 semi-final win over Jimmy White provided the most often reprised item from the BBC''s snooker footage.', null, '"Trailing 0-59 in the penultimate frame, Higgins produced, like a gunfighter down to his last bullet"', 'His 16-15 semi-final win over Jimmy White provided the most often reprised item from the BBC''s snooker footage.

THE PRESSURE

Trailing 0-59 in the penultimate frame, Higgins produced, like a gunfighter down to his last bullet, a clearance of 69 to level the match and added the decider comfortably. This was the death or glory situation in which he revelled. His compulsive urge to live on life''s dangerous edge, stronger than any mere desire to win, was like an addiction to the thrill of gambling.

THE FINAL

Always at his most dangerous and most fascinating in a situation of peak emotional intensity, he accessed a similar seam of inspiration in the final when, from 15-15, he ran through a trio of frames to beat Ray Reardon 18-15.', '2014-01-01', false, 'Richard Pearson'),
  ('Alexander the great: 40 years on', 'alexander-the-great-40-years-on', 'Professional Snooker', '[]'::jsonb, 'Snooker''s emergence from folk sport to frontline television entertainment can be traced chiefly to two component parts: colour television and Alex Higgins. It was colour TV that gave the game its exposure; it was…', null, '"Do you know what really gets me?” he asked when his career was already in sharp decline. “I’ve never played my best in front of the TV cameras. People just don’t know how good I am"', 'Snooker''s emergence from folk sport to frontline television entertainment can be traced chiefly to two component parts: colour television and Alex Higgins. It was colour TV that gave the game its exposure; it was Higgins who became its first bona fide star.

more A hero to many, an anti-hero to many more, he created interest and headlines with his wayward life and intoxicating playing-style. He was the sort of figure every sport needs: a combustible cocktail of talent and temper, brilliance and self-destruction.

CROWD PULLER

40 years ago, Higgins won his first world title at the age of 22. The Crucible this was not. In the age before the professional circuit exploded on TV the World Championship passed by largely under the radar. When Clive Everton wrote to the sports editor of the Daily Telegraph to see if he wanted any coverage he received the sniffy reply: "only if it''s played in London." Pot Black on BBC2 had begun to make household names of the players but as a sport snooker still had a long way to go to earn acceptance. The 1972 World Championship was not played in London but Birmingham, at the Selly Park British Legion. The championship had ground on for the best part of a year before producing its two finalists: Higgins and John Spencer, thedefending champion. Trotting out the facts of the environment in which this historic match was played makes it look like something out of an episode of Life on Mars, but they are still true and a reminder that the circuit was not always cash rich, that the top players were not always so lucky.

EXCUSES EXCUSES

The unexpectedly large crowd were packed in on seats placed on stacked beer crates, or watched hanging from any available vantage point in a scene which would give modern day health and safety jobsworths a heart attack. With a miners’ strike and power cuts afflicting Britain, the conventional lighting gave out on the second evening, as did the heating. The players agreed to continue under much duller lighting provided by a mobile generator. The final was played over six days. On the fifth, Spencer got stuck in a lift in his hotel for 25 minutes due to a power cut. The session was delayed for ten minutes until he turned up. It was this session which turned the final Higgins''s way. The players had kept pace until he won all six frames played that evening. He won the match 37-31. The first prize was a mere £480. By the time Higgins won his second world title a decade later the sport had been transformed. His epic semi-final against Jimmy White and final victory over Ray Reardon were the talk of the nation. His tearful celebration with wife and baby daughter remain iconic sporting images. It was the final proof that Higgins had unwittingly helped to pull snooker from the back room to the living room. He won £25,000 as sponsors began to throw money at the game. He of course will not be at the Crucible this year to mark these two anniversaries. Higgins died in pitiful circumstances in 2010, the Hurricane long since a sad shadow of the man who created so much excitement and controversy. But as long as people talk about snooker they will talk about Alex Higgins. It''s an irony he may have enjoyed that snooker''s long road to respectability was given such momentum by a man who sought no such thing. Article courtesy of the Snooker Scene Images are courtesy of Stephen Campbell', '2014-01-01', false, 'Richard Pearson'),
  ('All matches finish 3-2 in extraordinary night', 'all-matches-finish-3-2-in-extraordinary-night', 'Match Reports', '[]'::jsonb, 'It was an amazing week in both leagues as all of the 10 matches ended up 3-2 – surely the first time this has happened in the St Blazey and District Snooker League.', null, '"The night’s big game at Tywardreath saw breaks of 40 by Darren Kirwan and Tregonissey’s Barry McIntosh’s 37 in the home side’s narrow victory."', 'It was an amazing week in both leagues as all of the 10 matches ended up 3-2 – surely the first time this has happened in the St Blazey and District Snooker League.

more Leaders Bugle ‘A’ triumphed over Mevagissey ‘A’ with Richard Lakeman and Mike Towsey mopping up the last two frames. Darren Lock’s fine 55-break settled the Lostwithiel derby in favour of the ‘A’ team. Ian Ball snatched the win for Bugle ‘B’ at Mevagissey ‘B’ – Matt Mills and Ben Rothwell the home marksmen. Bob Stephens and Geoff Hawken saw off Michael Courts and Martin Rowe as Bethel ‘A’ fought back against St Neot. The night’s big game at Tywardreath saw breaks of 40 by Darren Kirwan and Tregonissey’s Barry McIntosh’s 37 in the home side’s narrow victory. In the Rees Memorial League Chris Brown overcame Tyrone Stephen in the deciding frame as St Blazey overcame Bethel ‘D’. Gorran Haven picked up another good win this time over local rivals Mevagissey ‘D’ as Andy Reddall saw off Paul Eccles in the evening’s last frame. Neil Rowe was in excellent form as Tywardreath ‘B’ left Bethel ‘B’ with a victory. Graham Hoskin and David Phipps picked up good wins over Steve Jones and Jason Cocks but Courtney Crockford saw off Terry Middleton in the last frame to seal Bethel ‘C’ victory over Lerryn and finally Bugle ‘C’ sneaked a fine victory over Mevagissey ‘C’ with Ben Prynn and Nathan Shaw the Meva victors.

FULL RESULTS

Victory League: Bugle ‘A’ 3 (G Spencer, P Sturtridge, A Best (32)) Mevagissey ‘A’ 2 (R Lakeman, M Towsey); Tywardreath ‘A’ 3 (D Kirwan (40), L Sturtridge, A Gooch) Tregonissey 2 (R Bilson, B McIntosh); St Neot 3 (A Tamblyn, A Courts, S Courts) Bethel ‘A’ 2 (B Stephens, G Hawken); Mevagissey ‘B’ 2 (M Mills, B Rothwell) Bugle ‘B’ 3 (D Rundle, G Taylor, I Ball); Lostwithiel ‘B’ 2 (B Warne, L Flower) Lostwithiel ‘A’ 3 (C Perring, R Broad, D Lock (55). Rees Memorial League: Gorran Haven 3 (P Grimmett, L McKinstry, A Reddall) Mevagissey ‘D’ 2 (R Blamey, R Prynn); Bethel ‘B’ 2 (B Stunnell, G Buckle) Tywardreath ‘B’ 3 (K Wilks, N Rowe, A Dennis); Bethel ‘D’ 2 (J Pascoe, V Hathway) St Blazey 3 (S Dweings, M Woodward, C Brown); Mevagissey ‘C’ 2 (Ben Prynn, N Shaw) Bugle ‘C’ 3 (J Moore, N Couchman, K Spencer); Lerryn 2 (G Hoskin, D Phipps) Bethel ‘C’ 3 (H Brett, R Smithson, C Crockford). Top breaks of the week: Darren Lock 55, Darren Kirwan 40, Barrie McIntosh 37. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Allen First In Fürth', 'allen-first-in-furth', 'Professional Snooker', '[]'::jsonb, 'Mark Allen won his third European Tour title within the past year by beating Judd Trump 4-2 in the final of the Arcaden Paul Hunter Classic in Fürth, Germany.', null, '"The crowds here are amazing, everything about the tournament reflects well on the name of Paul Hunter and the players feel proud to be a part of it."', 'Mark Allen won his third European Tour title within the past year by beating Judd Trump 4-2 in the final of the Arcaden Paul Hunter Classic in Fürth, Germany.

more World number nine Allen won two European Tour titles last season and has now won the second of the current campaign, and tops the Order of Merit having been runner-up to Mark Selby at the Riga Open. Watched by a packed crowd at the Fürth Stadthalle, Northern Ireland''s Allen collected the trophy and a cheque for 25,000 Euros after getting the better of world number six Trump. A dramatic opening frame came down to a respotted black after Trump had missed frame-ball green, and he was made to pay as Allen took it. Trump hit back with a break of 92 before a scrappy third frame went Allen''s way for 2-1. In the fourth, Allen had a chance to clear but missed a tough last red to a baulk corner, and Trump took advantage to level the match. Allen regained the lead after a poor safety from his opponent on the last red in the fifth. And the 28-year-old from Antrim sealed victory in the next with a fine break of 88. "I''m glad I won this one, having been 3-0 up on Selby in the final in Riga and lost 4-3," said the player nicknamed the Pistol. "It shows that I''m going in the right direction, having got to the last two finals. "I''ve actually played poorly this weekend so I''m glad the final was a bit scrappy - if it had been open then Judd would have scored heavily. "I still feel I need to get more consistent. I don''t know why I do better in the European Tour events than the main ranking events because I don''t prepare any differently. "The crowds here are amazing, everything about the tournament reflects well on the name of Paul Hunter and the players feel proud to be a part of it." Earlier in the semi-finals, Trump beat Ricky Walden 4-1 while Allen edged out veteran Rod Lawler 4-3. The 2014/15 European Tour series comprises six events across the continent, with the top 24 in the final Order or Merit to go through to the Players Championship next March to battle for the £100,000 jackpot. The next event is the Bulgarian Open in Sofia from October 2-5. Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Allen Is Euro Star', 'allen-is-euro-star', 'Professional Snooker', '[]'::jsonb, 'Mark Allen won his second consecutive European Tour event by beating Judd Trump 4-1 in the final of the Kay Suzanne Memorial Cup at the South West Snooker Academy in Gloucester.', null, '"The tournament is named in memory of Kay Suzanne, sister of SWSA owner Paul Mount, and players wore pink shirts to raise awareness of breast cancer. Allen added: "Paul and his family have worked hard on this event and it was great to see the fans and players supporting it so well.""', 'Mark Allen won his second consecutive European Tour event by beating Judd Trump 4-1 in the final of the Kay Suzanne Memorial Cup at the South West Snooker Academy in Gloucester.

more Northern Ireland''s 27-year-old Allen, who won the Ruhr Open last month, became the first player to win back-to-back events in the same season since the Players Tour Championship series was introduced in 2010. He took the opening frame with a 62 clearance, before Trump levelled with a break of 128. Allen took a scrappy third then made three scoring visits in the next for 3-1. And a run of 53 in frame five clinched the £20,000 top prize as well as 2,000 ranking points. "I played very solid snooker over the last couple of days," said Allen. "I had one tight match in the last 32 against Gary Wilson, which I won 4-3, but apart from that I won most of my matches quite comfortably. It''s nice to have won two titles already this season as not many other players have done that." Allen is now looking forward to two major events later this month - the 888casino Champion of Champions in Coventry followed by the williamhill.com UK Championship in York. "My target now is to win a big title and I''m full of confidence," he said. "I''m just happy to be playing well because I was struggling earlier in the season." In the semi-finals, Trump edged out Welshman Jamie Jones 4-3 while Allen saw off Scotland''s Graeme Dott 4-2. The tournament is named in memory of Kay Suzanne, sister of SWSA owner Paul Mount, and players wore pink shirts to raise awareness of breast cancer. Allen added: "Paul and his family have worked hard on this event and it was great to see the fans and players supporting it so well." The European Tour comprises eight events, with the top 24 on the final Order of Merit to qualify for the Grand Finals next March, to be joined by eight more players from the Asian Tour Order of Merit. The next event is the Antwerp Open in Belgium from November 14 to 17. Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Allen Retains Haikou Title', 'allen-retains-haikou-title', 'Professional Snooker', '[]'::jsonb, 'Mark Allen won his second ranking title by beating Matthew Stevens 10-4 at the Yearly Yuan-jiang Gujinggong Liquor Haikou World Open.', null, '""I''m very happy to win and retain my title, to win the same tournament two years in a row is a great achievement," said Allen. "The snooker wasn''t as good as I had hoped. I didn''t get into a rhythm and I didn''t score very heavily. The scoreline was flattering, it wasn''t as one-sided as that. "', 'Mark Allen won his second ranking title by beating Matthew Stevens 10-4 at the Yearly Yuan-jiang Gujinggong Liquor Haikou World Open.

more Allen cruised to victory in the final against Stevens to win the event for the second consecutive year. He''s the first player to win the same world ranking event in back-to-back years since John Higgins captured the Welsh Open crown in 2010 and 2011. Antrim''s 27-year-old Allen remains unbeaten at the tournament on Hainan Island to the south of mainland China, having won ten consecutive matches. The Northern Irishman received the trophy and a cheque for £85,000, and jumps two places to number seven on the ranking list. Allen went through several years of struggling to fulfil his potential, and didn''t reach his first ranking final until the 2011 UK Championship, which he lost to Judd Trump. The left-hander has now established himself as a proven winner and certainly has the talent to continue his progress. He has shown his best form in patches this season, particularly in winning the European Tour event in Antwerp in October and a Championship League group in January. And he played brilliantly to beat John Higgins in the semi-finals yesterday, and had far too much for Welshman Stevens today. Stevens, age 35, enjoyed a run to the final which bordered on the miraculous, having won his first two matches without his own cue. But in the end he had to settle for the £35,000 runner-up prize and has now lost seven of his eight ranking finals. Allen, who thrashed Stephen Lee 10-1 in last year''s final, stormed ahead today with breaks of 48, 52 and 93 in taking the first three frames. Stevens led 55-0 in the fourth only for Allen to make a superb 58 clearance for 4-0. Welshman Stevens rallied after the interval with 67 and 112 to get to 4-2, before Allen pulled away again to take the next two frames, compiling a run of 100 in the eighth. Stevens took a scrappy last frame of the session to keep his hopes of a fight-back alive at 6-3. Stevens looked likely to win the first frame of the evening session until he snookered himself on the last yellow after potting the black. It came down to a safety battle on the blue, and Allen thumped in a brilliant long pot and cleared to snatch it. A break of 100 saw Stevens back to 7-4, only for Allen to win the next with a 55. And when he cleared from the last red in the 13th frame to make it 9-4, his opponent''s hopes had vanished. Allen made a composed 68 in frame 14 to clinch the title. "I''m very happy to win and retain my title, to win the same tournament two years in a row is a great achievement," said Allen. "The snooker wasn''t as good as I had hoped. I didn''t get into a rhythm and I didn''t score very heavily. The scoreline was flattering, it wasn''t as one-sided as that. "But the result is all that matters. My form has been good for the last few months so I''m relieved, more than anything, to finally get a win. Hopefully I can push on now and win more." Stevens, who is up to number ten in the world, said: "The start of the match was important, it could have been 2-2 but I was 4-0 down and it''s difficult to catch up after that. I could never get back to within one frame. "It wasn''t a great match today but Mark''s safety was a lot better than mine and he did the job, so well done to him. It''s always disappointing to lose in finals, but it''s still been a good week for me, especially after losing my cue. I''ve earned a lot of ranking points and I know I''m safe in the top 16." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Allen Wins First Masters Crown', 'allen-wins-first-masters-crown', 'Professional Snooker', '[]'::jsonb, 'Mark Allen enjoyed the best moment of his snooker career as he beat Kyren Wilson 10-7 in the final of the Dafabet Masters, winning a Triple Crown event for the first time.', null, 'Allen then stepped up a gear with breaks of 73 and 119 – the 28th century of the tournament – to lead 7-5 at the interval. In frame 13 he made 34 before running out of position, then Wilson had a scoring chance but potted just one red before missing the black with the rest. Allen’s 50 put him three frames in front.', 'Mark Allen enjoyed the best moment of his snooker career as he beat Kyren Wilson 10-7 in the final of the Dafabet Masters, winning a Triple Crown event for the first time.

more Antrim’s 31-year-old Allen came from 4-3 down to win seven of the last ten frames at Alexandra Palace, before receiving the Paul Hunter Trophy and a career-biggest cheque of £200,000. There were emotional scenes at the end of the match, with Wilson in tears as he reflected on defeat, and Allen embraced by his father Ronnie, wife Kyla, stepson Robbie and baby daughter Harleigh. World number eight Allen was the man of the week in London as he knocked out Luca Brecel, Ronnie O’Sullivan and John Higgins to reach the final. And though he only showed glimpses of the same form today, he did enough to win his tenth career title and first since the 2016 Players Championship. Since his junior days, Allen has been touted as the best Northern Irish player since the days of Alex Higgins and Dennis Taylor, and he has now emulated those two greats by winning snooker’s biggest invitation tournament. He struggled with his game for much of last season, after splitting with coach Terry Griffiths, but Allen made changes to his cue action at the start of the current campaign and has worked hard on the practice table to bed in his improved technique. He is now enjoying the fruits of that labour and savouring his finest hour. Allen had played in only one Triple Crown final before, losing 10-8 to Judd Trump at the 2011 UK Championship. He becomes the first player other than Ronnie O’Sullivan or Mark Selby to win a Triple Crown event since 2015. He is also sure of a place in the Champion of Champions later this year. Kettering’s 26-year-old Wilson also won his biggest ever cheque as the £90,000 runner-up prize eclipses the £85,000 he won for capturing the 2015 Shanghai Masters, his only pro title. He has now lost three finals this season, having been beaten by Ronnie O’Sullivan at the English Open and Ding Junhui at the Yushan World Open. World number 14 Wilson will surely reflect on crucial chances he missed in the first session when he could have established a substantial lead. The first frame of the evening session lasted 40 minutes and came down to the colours. Wilson played a weak safety on the brown, allowing Allen to pot brown and blue to take a 5-4 lead. In frame ten, Allen led 23-8 when he missed a tricky green to a baulk corner, and his opponent punished him with a break of 84 to level the contest. Allen then stepped up a gear with breaks of 73 and 119 – the 28th century of the tournament – to lead 7-5 at the interval. In frame 13 he made 34 before running out of position, then Wilson had a scoring chance but potted just one red before missing the black with the rest. Allen’s 50 put him three frames in front. Wilson, who had never won a match in the Masters before this week, stemmed the tide with a break of 73 to pull back to 8-6. In the 15th, Allen made 49 before missing a tough red to a centre pocket. Wilson replied with 47 to take it to a safety battle on the last red, then took advantage of a missed pot from Allen to clear to the pink and reduce the gap to a single frame. Allen bounced back impressively with a break of 69 to go two up with three to play at 9-7. And a few minutes later the match was over as Allen’s run of 71 gave him the title. Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Allen captures Bulgaria crown', 'allen-captures-bulgaria-crown', 'Professional Snooker', '[]'::jsonb, 'Mark Allen won his first title in 15 months by beating Ryan Day 4-0 in the final of the Victoria Bulgaria Open in Sofia.', null, 'I’m very happy to get another tournament win under my belt,” said the Northern Irishman. “To win 4-0 in the final is a good way to do it and shows my game is in good shape.', 'Mark Allen won his first title in 15 months by beating Ryan Day 4-0 in the final of the Victoria Bulgaria Open in Sofia.

more World number ten Allen dominated the final in the Bulgarian capital to take the 25,000 Euro top prize at the season’s fourth Kreativ Dental Clinic European Tour event. The 29-year-old from Antrim won his first title since last year’s Paul Hunter Classic. Allen also earns a place at the 188BET Champion of Champions, which starts in Coventry on Tuesday, and will face Barry Hawkins on the first round on Friday. Two-time ranking event winner Allen had a disappointing 2014/15 season but has since been reunited with coach and mentor Terry Griffiths and showed signs of a return to form in reaching the semi-finals of the Shanghai Masters and quarter-finals of the International Championship. And he has now added to his silverware collection having won seven matches in Sofia. Breaks of 65 and 76 put him 2-0 up on Welshman Day and he made a 56 in the next before securing it on the final pink. Day, who was trying to win a title carrying ranking points for the first time in his career, had chances in frame four but couldn’t take advantage and Allen cleared from yellow to pink to secure the trophy. “I’m very happy to get another tournament win under my belt,” said the Northern Irishman. “To win 4-0 in the final is a good way to do it and shows my game is in good shape. I haven’t been too happy with my performances this season even though I’ve been winning matches, but now I’m getting closer to where I want to be. “To get a place in the Champion of Champions is a massive bonus and I’ll be going into next week with a lot of confidence having won here.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Andrew is Best in show', 'andrew-is-best-in-show', 'Match Reports', '[]'::jsonb, 'Andrew Best’s breaks of 32 and 31 were the highlight at leaders Bugle ‘A’ returned from Mevagissey ‘B’ with a 5-0 whitewash.', null, '"In the top match of the night Tregonissey beat St Neot 3-2 with Barry McIntosh’s 34 pivotal. Martin Rowe winning the last frame for the visitors keeping it very tight at the top of the division."', 'Andrew Best’s breaks of 32 and 31 were the highlight at leaders Bugle ‘A’ returned from Mevagissey ‘B’ with a 5-0 whitewash.

more Bugle ‘B’ returned to form with a 4-1 win over Lostwithiel ‘B’ – Ian Ball had a 55 but despite a 32-break Graham Taylor lost out to George Lory. Sparks picked up two valuable points away at Tywardreath ‘A’ as Mike Williams surprised Andrew Gooch winning on the pink – Mike Hancock weighed in with a 48 for the home side. In the top match of the night Tregonissey beat St Neot 3-2 with Barry McIntosh’s 34 pivotal. Martin Rowe winning the last frame for the visitors keeping it very tight at the top of the division. St Blazey increased their lead at the top of the Rees League when beating Mevagissey ‘D’ 4-1, Mike Towsey with the visitors’ solitary point. Bethel ‘B’ moved back into second place when winning 3-2 at Lerryn, Guy Buckle seeing off Terry Middleton in the decider. Whilst Bethel ‘C’ came from 2-0 down to overcome their ‘D’ team as Brett, Crockford and Cocks triumphed over Pascoe, Spearman and Tonkin respectively. Mevagissey ‘C’ also recovered from 2-1 down to pip Gorran Haven 3-2 with Lee McKinstry and Paul Grimmett the Haven’s marksmen.

FULL RESULTS

Victory League: Bethel ‘A’ 4 (L Collard, B Stephens, S Allen, G Hawken) Mevagissey ‘A’ 1 (R Lakeman); Mevagissey ‘B’ 0 Bugle ‘A’ 5 (P Sturtridge, G Spencer, A Peers, A Best (32 and 31), I Powell); Bugle ‘B’ 4 (D Rundle, C Rundle, I Ball (55), J Moore) Lostwithiel ‘B’ 1 (G Lory); Tywardreath ‘A’3 (M Hancock (48), D Kirwan, P Baron) Sparks 2 (M Williams, S Bampton); Tregonissey 3 (B McIntosh (34), R Bilson, M Fox) St Neot 2 (N Collins, M Rowe. Rees Memorial League: St Blazey 4 (S Dewings, M Meares, M Woodward, C Brown) Mevagissey ‘D’ 1 (M Towsey); Mevagissey ‘C’ 3 (N Shaw, M Chesterfield, B Prynn) Gorran Haven 2 (L McKinstry, P Grimmett); Lerryn 2 (C McMiram, G Brimicombe) Bethel ‘B’ 3 (M Green, S Hicks, G Buckle); Bethel ‘C’ 3 (H Brett, C Crockford, J Cocks) Bethel ‘D’ 2 (V Hathway, T Stephen). Top breaks of the week: Ian Ball 55, Mike Hancock 48, Barrie McIntosh 34, Andrew Best 32,31. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Andy Hicks Exhibition at Meva Social Club', 'andy-hicks-exhibition-at-meva-social-club', 'League News', '[]'::jsonb, 'Mevagissey Social Club presents - an exhibition by Andy Hicks - Friday 15th March 2013 - Cue off 7pm till late.', null, '"Seats are now on sale from the downstairs bar at Mevagissey social club, Jetty Street, Mevagissey and are £10 each (per seat) + £2 per person for anyone wishing to play against Andy."', 'Mevagissey Social Club presents - an exhibition by Andy Hicks - Friday 15th March 2013 - Cue off 7pm till late.

more Former World Championship Semi Finalist at the Crucible Theatre in Sheffield One of the World''s greatest exhibition players Andy Hicks who will play 12 frames of snooker with anyone who wishes to do battle against him (there dis also a great possibility of extra frames if time permits) Half time interval will include a well appointed buffet and a great raffle (any raffle prizes donated will be most gratefully received) Only 50 seats available The last 2 Andy Hicks nights were very successful so book and pay for your seat early to avoid any disappointment. Seats are now on sale from the downstairs bar at Mevagissey social club, Jetty Street, Mevagissey and are £10 each (per seat) + £2 per person for anyone wishing to play against Andy. Any other information that is required please ask downstairs at the bar when buying your ticket.', '2014-01-01', false, 'Richard Pearson'),
  ('B team triumphant in Blazey derby', 'b-team-triumphant-in-blazey-derby', 'Match Reports', '[]'::jsonb, 'St Blazey ‘B’ followed up their nap hand of last week as they managed to beat their ‘A’ team 4-1.', null, 'Tregonissey ‘B’ bounced back from last week’s hammering to defeat St Stephen ‘B’ 4-1. Rob Garside defeated Sam Simon for the youngsters’ point with Ryan Thomas, Gary Wherry, Chris Robins and Phil Hooley responding.', 'St Blazey ‘B’ followed up their nap hand of last week as they managed to beat their ‘A’ team 4-1.

more Graham Taylor, Jamie Read (47), Mike Hancock and Andrew Gooch their winners with Nick Kendall helping himself to a 31-break while beating Paul Baron. Mevagissey ‘A’ made the long trip to St Neot and returned home with four points. Anthony Maddams saw off Matt Mills for the home team but Phil Staley, Paul Williams, Chris Kendall and Pete Chambers moved Meva up to joint second. Bethel ‘A’ got all the points when they defeated their ‘C’ team. Matt Green’s excellent 38 break got them started followed by wins for Geoff Hakwken, Andy Peers and Leon Collard. Howard Brett put a break of 28 together in the last frame, but was well beaten by chairman Gary Stephens, who potted beautifully to get his point. Bugle ‘B’ put last week’s thrashing behind them as they beat Bethel ‘D’ 4-1, Jason Pascoe’s excellent win over Tony Conroy was Bethel’s only success as Dave and Colin Rundle, Nigel Couchman and Mark Sturtridge prevailed. Tregonissey ‘A’ pipped Bugle ‘A’ 3-2. Gorran Haven sit proudly joint top of the Rees League after taking the full five points at home to Lerryn and keeping hold of the Runabout Shield at the same time. Andy Reddall, Rob Bunney, Richard Holmes, Lee McKinstry and Matt Fox, making a rare appearance, were their marksmen. They are level with Mevagissey ‘B’ who came through 3-2 at home to the Q Bar. Captain Mark Gregory, Ben Rothwell and Dave Kendall were victorious with Matty Woodward and Richard Bolt on target for the Bodmin boys. St Stephen ‘A’ played their first game of the season and came away with a 3-2 win from Bethel ‘B’. Shaun Hicks, having switched his allegiance from Bethel. Anthony Harrison and Dan Allen were their winners with Clive Stuthridge and Jim Tamblyn who sneaked past Cary Clark for the home side. Tregonissey ‘B’ bounced back from last week’s hammering to defeat St Stephen ‘B’ 4-1. Rob Garside defeated Sam Simon for the youngsters’ point with Ryan Thomas, Gary Wherry, Chris Robins and Phil Hooley responding. Finally a very close Mevagissey derby saw the ‘D’ team defeat the ‘C’ team 3-2, Ben and Charlie Prynn both recorded their first wins but the ‘D’ team came through with Rich Lakeman, Rob Blamey and George Lory, who fluked the black, to beat Matt Chesterfield.

FULL RESULTS

Victory League: Tregonissey ‘A’ 3 Bugle ‘A’ 2, St Blazey ‘A’ 1 (N Kendall (31)) St Blazey ‘B’ 4 (G Taylor, J Read (47), M Hancock, A Gooch), St Neot 1 (A Maddams) Mevagissey ‘A’ 4 (P Williams, P Chambers, C Kendall, P Staley), Bethel ‘A’ 5 (M Green (38), G Hawken, L Collard, G Stephens, A Peers) Bethel ‘C’ 0, Bugle ‘B’ 4 (D Rundle, N Couchman, M Sturtridge, C Rundle) Bethel ‘D’ 1 (J Pascoe). Rees Memorial League: Bethel ‘B’ 2 (C Stuthridge, J Tamblyn) St Stephen ‘A’ 3 (S Hicks, A Harrison, D Allen), Gorran Haven 5 (A Reddall, R Bunney, R Holmes, M Fox, L McKinstry) Lerryn 0, Mevagissey ‘D’ 3 (G Lory, R Blamey, R Lakeman) Mevagissey ‘C’ 2 (B Prynn, C Prynn), St Stephen ‘B’ 1 (R Garside) Tregonissey ‘A’ 4 (R Thomas, G Wherry, C Robins, P Hooley), Mevagissey ‘B’ 3 (M Gregory, B Rothwell, D Kendall) Bodmin Pool 2 (M Woodward, R Bolt). Top breaks of the week: N Kendall 31, J Read 47, M Green 38 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Backed by the BBC', 'backed-by-the-bbc', 'Professional Snooker', '[]'::jsonb, 'The BBC''s decision to continue to broadcast snooker until 2017 means the game can continue to be viewed by the masses in the UK.', null, '"It keeps up the momentum of Barry Hearn''s rennovation work in snooker. The deal means the BBC is also saying that the recently announced flatter 128-man flatter structure isn''t a dealbreaker when it comes to a major broadcaster.".', 'The BBC''s decision to continue to broadcast snooker until 2017 means the game can continue to be viewed by the masses in the UK.

more Today''s announcement of a three-year contract extension should be greeted with cheer because it continues to give our beloved game mainstream attention. A large majority of snooker fans in the UK watch the sport on a part-time basis and when the majors - the World Championship, UK Championship and The Masters - are broadcast by the BBC. People like me who follow all the events, including the PTCs and qualifiers and watch the ever-moving world rankings with great interest, are a rare breed. Even today, with snooker streamed online and showed on Eurosport most weeks, the BBC action is the backbone of the season for most fans. That''s why this deal is an absolutely massive boost for the sport. It keeps up the momentum of Barry Hearn''s rennovation work in snooker. The deal means the BBC is also saying that the recently announced flatter 128-man flatter structure isn''t a dealbreaker when it comes to a major broadcaster. The announcement also states that in 2014 there is an option to add a fourth event to the BBC roster. This signifies potential growth of the game in the UK, at a time when the majority of change has come for the rest of the world. Today is a good day for the sport. It helps to keep snooker accessible in the country of its origin. Article courtesy of the OneCue Images Courtesy of: BBC', '2014-01-01', false, 'Richard Pearson'),
  ('Baize baron in the making', 'baize-baron-in-the-making', 'Match Reports', '[]'::jsonb, 'Shree Advani exclusively talks to us about the life of up and coming Cue star Pankaj Advani', null, '"Newspapers called it a “family affair” as the Advani brothers were going to compete for their first shot at a title – the Sampath Handicap Snooker Tournament that was held annually in Bangalore. We both knew it was a championship of little significance in the larger scheme of the sport, but this was our debut into competitive snooker and we both were a step away from our first winner’s trophy.".', 'Shree Advani exclusively talks to us about the life of up and coming Cue star Pankaj Advani

more My curious 10-year old brother wanted to put to rest the mystery about this new hobby I got hooked on to. I offered to take him along to witness this amazing sport. Little did I know that this would become Pankaj''s routine too, not to mention, the start of a new and interesting chapter in the encyclopedia of cue sports. A summer evening in 1995, after my day at school, I was rushing to go pot some balls at the local snooker club with my classmates - a new passion we discovered recently. My curious 10-year old brother (I’m 7 years older than him) innocently asked me where I''ve been going everyday around the same time the last couple of weeks. I told him I went to play snooker. Intrigued and clueless, he wanted to put the mystery to rest about this new hobby I got hooked on to. I offered to take him along to witness this amazing sport. Little did I know that visiting ‘Top Gun’ as a keen observer would become Pankaj’s daily routine too, not to mention, the start of a new and interesting chapter in the encyclopedia of cue sports. He enjoyed watching us using the cue as a wand that magically made the colourful world made up of snooker balls disappear gracefully into pockets, the process bringing about immense joy to the executor. He was fascinated by the elegant swagger around the table by the player who prepared for his next shot, especially after scoring. But Pankaj had something else going on in his mind. He couldn’t take it anymore. He waited too long. He accompanied the big boys for many days and it was time he tried his hand at this pulsating enigma. He wanted to feel the rush he witnessed us experience on the inviting baize. After showing him the basic technique – bridge, stance, aim and strike positions, Pankaj was ready to go. He attempted his maiden shot. It vanished into a corner pocket with zero jaw contact. He got a clean first pot. Then as they say, the rest is history. Cut back to today, Pankaj Advani, the 8-time world champion, is the proud owner of 40 major titles – 8 world (7 billiards and 1 snooker), 6 Asian (5 billiards and 1 snooker team event), 2 Asian Games Gold medals, 1 Australian Open and 23 National. Mind you, these are just the winning titles/gold medals. Today he is a household name in our country of 1.2 billion. “Punks” is the youngest 8-time world champion in any sport in India. It was, however, his first of many titles, though not a major event, that sent warning signs out to the world about the arrival of a child prodigy in 1997. It was a handicap snooker championship (only his second tournament) wherein he defeated some of the top names in the state of Karnataka to meet none other than the person who introduced him to this very sport, yours truly. Newspapers called it a “family affair” as the Advani brothers were going to compete for their first shot at a title – the Sampath Handicap Snooker Tournament that was held annually in Bangalore. We both knew it was a championship of little significance in the larger scheme of the sport, but this was our debut into competitive snooker and we both were a step away from our first winner’s trophy. Pankaj, on that day, displayed that he was made for the big stage. He thrived under pressure and knew how to handle a final. It was bittersweet for me to see my little brother pot away to glory while I remained a mere spectator paying the occasional visit to the table with diminishing confidence. The wonderboy’s innate ability to play the game made me realize the difference between talent and hard work. While I spent hours at the table each day in practice, Pankaj would manage to barely squeeze in less than 2 hours a day, due to a heavy school workload. Yet, he produced some incredible snooker. As I watched him inch closer to the finish line, I began believing that this boy was different, that this player had something. I didn’t know what it was at the time. I still am on the quest of fully understanding his exceptional mind but as a professional I can see that he has a massive capacity to perform outside his standard operation zone when truly tested. He has the uncanny power to outplay his opponent when the going gets tough. He has a strong Emotional Quotient and a high level of self-belief. These attributes have seen him conquer several world and other major championships, leading to the rise and establishment of a rare cueist who can compete at the highest level in not one, but two sports. Article courtesy of the Dr. Shree Advani, Sport & Performance Psychologist and proud brother. Images Courtesy of: Dr. Shree Advani', '2014-01-01', false, 'Richard Pearson'),
  ('Baize of glory: our top 5 Crucible moments...', 'baize-of-glory-our-top-5-crucible-moments', 'Professional Snooker', '[]'::jsonb, 'This year marks the 35th anniversary of the Crucible Theatre staging the World Snooker Championship – which gives us the perfect opportunity to, ahem, cue up the five greatest moments in the history of the grand old…', null, null, 'This year marks the 35th anniversary of the Crucible Theatre staging the World Snooker Championship – which gives us the perfect opportunity to, ahem, cue up the five greatest moments in the history of the grand old tournament.

THAT BLACK-BALL FINAL 1985

Snooker''s greatest ever final, an epic match-up unlikely ever to be surpassed for sheer bum-squeaking drama. In the red-headed corner, Steve Davis, the master cueman with, at that point, three world titles to his name. In the green corner, a Northern Irishman more recognisable for his dustbin-lid specs than his achievements on the baize. The early signs suggested a mismatch as Davis took the first eight frames, but from out of nowhere Taylor produced a fightback of unlikely proportions that would see the match go to the final black of the final frame. As 18 million sat glued to BBC Two as Sunday night became Monday morning, Davis blinked first, overcutting a relatively straightforward black to leave Taylor with the chance to seal the most amazing of comebacks. “Even at 17-15 (down), I thought: ‘Well I’ve come back from 8-0, so don’t be giving up now,’" says Taylor. "To be involved in those last frames and to fight back and make it 17-17, then to go to the final black — incredible. Most people thought that Steve would’ve cut the black in, but it wasn’t as easy as everyone thought. He said that as he walked across the Crucible floor his legs didn’t feel like his and his hands and arms felt like somebody else’s, the pressure was so intense. The final black, I didn’t even grip the cue — I let the butt rest on my fingers and kept my thumb out of the way. I took ages on the shot and really just let go of the cue, so that I couldn’t snatch at it. And that lovely little black ball disappeared into the corner pocket!” “I remember a month later sitting in the bath one day daydreaming and thinking: ‘What happened?’," says Davis. "It took me a long time to recover. But I don’t look back with anything other than fondness now. It was part of my career and what an experience. Obviously at the time it was devastating, but now I look back and think, okay it would’ve been nice to have won another — but it would’ve been a stat. Who knows? If I’d won that, I may not have won others.” Read more at http://www.sport-magazine.co.uk/features/baize-glory-top-5-crucible-moments-1325#WZbMKrgaWkCUdmLH.99

THE PEOPLE’S CHAMPION RISES 1982

For many people, Alex Higgins (image 2) was snooker. Along with the advent of colour television, the Hurricane transformed the game with his bold and fast-potting style. Crowned world champion for the first time in 1972, it would be a further decade before he lifted the coveted trophy again, after beating the old warrior Ray Reardon. The people’s champion sealed the deal in dazzling fashion with a break of 135, before creating one of snooker’s most unforgettable scenes. With tears in his eyes, Higgins had the trophy on one arm and his 17-month-old daughter Lauren in the other — the Crucible had never seen anything like it, nor had the future generation of snooker stars. “I remember watching it as a kid in the front room of our house,” recalls Ken Doherty. “We all had the goose-bumps and were all nearly in tears. That 1982 championship definitely inspired me and, I’m sure, lots of other kids to pick up snooker. Higgins made snooker for me.”

THE GREAT WHITE HOPE 1994

By the early 1990s, it was Jimmy White (image 3) who carried the people’s hopes each spring at the Crucible, but the Whirlwind had already suffered a string of reverses in the final, notably in 1992 when he blew a 14-8 lead against Stephen Hendry, who also beat him in the final 12 months later. A year on and the pair would meet again. This time, it looked as if Jimmy — in a made-for-TV final frame — would finally win a World Championship final at the sixth attempt. But to the gut-wrenching dismay of his huge fan base, disaster struck as he somehow fluffed a routine black off its spot. Cue his nemesis Hendry… “I’d virtually given up hope. He’d played so many difficult shots in the break, to finally get in the position where everything was straightforward and then to miss the black was inexplicable. I remember jumping out of my seat so fast thinking: ‘I can’t believe I’ve got another opportunity.’ Although the balls were pretty straightforward, I made one of the best clearances of my career under pressure. My sponsor was giving me a Bentley as a bonus for winning it and I was thinking: ‘Hold yourself together, you’ve got a great chance here to not only win the world title and the prize that goes with it, but the chance to win a Bentley as well.’”

THE NEED FOR SPEED 1997

Ronnie O’Sullivan’s reputation as modern snooker’s most gifted player was cemented with the sport’s quickest ever 147. Playing Mick Price in the first round of the 1997 worlds, the Rocket (image 4) recorded an extraordinary maximum in five minutes and 20 seconds. “At the time, you don’t really realise; you are just seeing these balls floating in,” remembers John Virgo, who commentated on the game for the BBC. “And they were floating in — it wasn’t crash, bang, wallop stuff. He hit the ball so sweetly, it was just poetry. When somebody came up and said it was five minutes and 20 seconds, you just went: ‘Wow!’ I don’t think anyone will ever beat that time for a maximum break. It was just a sensational moment in the game.”

THREE-POINT TURN 2005

Shaun Murphy (image 5) had long been earmarked as a certain star of the future, but his form had dipped to the point where he was even considering giving up the game ahead of the 2005 World Championship. “I lost the final qualifying match in the China Open and had a massive row with (coach) Steve in the car park at Prestatyn,” he tells Sport. “Cues were slammed down, words exchanged and that was it. I never even intended to play in the World Championships — I was going to give up and get a proper job. I went to Mercedes Benz in Sheffield and approached them about a job selling cars.” Murphy reconsidered and entered the World Championships as a 150/1 outsider, but against expectation blazed his way to the final. “It was weird — one of the lowest times of my life followed by what is currently the highest point of my snooker life,” he says of the thrilling 18-16 final win over Matthew Stevens. “The stuff that Steve and I had been working on all seemed to come together in that last couple of weeks of the season.” Article courtesy of the Sport Magazine Images Courtesy of: Action Images & Günter Leitenbauer', '2014-01-01', false, 'Richard Pearson'),
  ('Baron week for Bethel', 'baron-week-for-bethel', 'Match Reports', '[]'::jsonb, 'Bethel ‘A’ had a very Baron night against joint leaders St Blazey ‘B’ as Paul Baron’s fine 65 and Darren Kirwan’s 40 helped complete a 5-0 whitewash.', null, '"Bugle ‘A’ recorded an excellent 5-0 victory at Lostwithiel ‘A’ with Andy Peers’ 30 and Andrew Best’s 36 helping to see off the home side."', 'Bethel ‘A’ had a very Baron night against joint leaders St Blazey ‘B’ as Paul Baron’s fine 65 and Darren Kirwan’s 40 helped complete a 5-0 whitewash.

more Bugle ‘A’ recorded an excellent 5-0 victory at Lostwithiel ‘A’ with Andy Peers’ 30 and Andrew Best’s 36 helping to see off the home side. Ryan Tonkin’s victory over Chris Stephenson was the least Bethel ‘D’ deserved as Tregonissey shaded three very tight frames which puts them clear in third position with a game in hand over the top two. Bugle ‘B’ recorded their first win of the season, 4-1 over St Blazey ‘A’ for whom Matty Woodward scored the solitary point and Leighton Varcoe’s fine 42 break helped seal a close 3-2 victory over Lostwithiel ‘B’ who had veterans Len Flower and Richard Broad on target. Mevagissey ‘B’s fine 4-1 win at St Stephen saw them joint top of the league and faced second-placed Bethel ‘C’ last night, who last week produced an excellent victory over Bodmin Sparks with Paul Thomas defeating Mike Bolt in the deciding frame. Mevagissey ‘D’ climbed the table after defeating near neighbours Gorran Haven 4-1 with Bob Colling winning for the Haven, while stablemates Mevagissey ‘C’ produced a great 3-2 home victory over Bugle ‘C’ with Matt and Joe Chesterfield the victory along with the predatory Dave Tregale.

FULL RESULTS

Victory League: Bethel ‘D’ 1 (R Tonkin) Tregonissey 4 (R Bilson, R Pearson, B McIntosh, J Cocks), Bugle ‘B’ 4 (C Rundle, D Rundle, J Moore, I Ball) St Blazey ‘A’ 1 (M Woodward), Lostwithiel ‘A’ 0 Bugle ‘A’ 5 (A Best (36), G Spencer, A Peers (30), I Powell, P Sturtridge), Mevagissey ‘A’ 3 (M Mills, L Varcoe (42), C Kendall) Lostwithiel ‘B’ 2 (L Flower, R Broad), St Blazey ‘B’ 5 (G Taylor, P Baron (65), M Hancock, A Gooch, D Kirwan (40)) Bethel ‘A’ 0. Rees Memorial League: Mevagissey ‘C’ 3 (D Tregale, M Chesterfield, J Chesterfield) Bugle ‘C’ 2 (N Couchman, M Pascoe), Gorran Haven 1 (B Cooling) Mevagissey ‘D’ 4 (R Blamey, J Tomlinson, N Parker, S Mills), St Stephen 1 (A Harrison) Mevagissey ‘B’ 4 (M Gregory, M Rowe, D Kendall, N Shaw), Bethel ‘C’ 3 (H Brett, M Powell, P Thomas) Sparks 2 (M Williams, S Bampton). Top breaks of the week: A Best 36, A Peers 30, L Varcoe 42, P Baron 65, D Kirwan 40 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Baron week for Bugle ''A''', 'baron-week-for-bugle-a', 'Match Reports', '[]'::jsonb, 'Tywardreath ‘A’ produced an excellent win at Bugle ‘A’ 3-2, to move to within three points of leaders Lostwithiel. Paul Baron’s fine 46-break a telling contribution.', null, '"St Blazey keep on ticking away nicely with a solid 3-2 win over Tywardreath ‘B’ with captain fantastic Mickey Mears notching a 33."', 'Tywardreath ‘A’ produced an excellent win at Bugle ‘A’ 3-2, to move to within three points of leaders Lostwithiel. Paul Baron’s fine 46-break a telling contribution.

more Tregonissey’s clean sweep at at Lostwithiel ‘B’ shows that the defending champions are reluctant to give up their crown and the next round of league matches on November 6 sees all of the top six sides locking horns. Mevagissey ‘B’ continue to find their feet in the big league as Dave Kendall’s 36-break helped secure a good 4-1 win at Sparks. Bethel ‘B’ collected their fifth straight 3-2 victory, over Mevagissey ‘C’, to continue their pursuit of leaders St Blazey, with Matt Green again in fine form with a 38. Lerryn made the long trip to Gorran Haven and won their first game of the season 3-2 with Dave Phipps winning the final frame. St Blazey keep on ticking away nicely with a solid 3-2 win over Tywardreath ‘B’ with captain fantastic Mickey Mears notching a 33. Strengthened Bethel ‘D’ beat Bugle ‘C’ 5-0 which did not reflect on how well Bugle played. Geoff Hawken’s season’s best 12 break – the highlight of the evening.

FULL RESULTS

Victory League: Lostwithiel ‘B’ 0 Tregonissey 5 (B McIntosh, C Kendall, R Pearson, R Bilson, M Fox); Bugle ‘A’ 2 (G Spencer, I Powell) Tywardreath ‘A’ 3 (P Baron (46), M Hancock, L Sturtridge); Mevagissey ‘A’ 2 (L Varcoe, M Fox) Lostwithiel ‘A’ 3 (D Lock, C Perring, A Maddams); Sparks 1 (M Williams) Mevagissey ‘B’ 4 (M Gregory, D Kendall (36), B Rothwell, M Mills); St Neot 4 (S Courts, A Courts, A Pearce, N Collins) Bugle ‘B’ 1 (D Rundle). Rees Memorial League: Bethel ‘D’ 5 (T Stephen, R Tonkin, G Hawken, A Spearman, J Pascoe) Bugle ‘C’ 0; Bethel ‘B’ 3 (M Sweet, B Stunnell, M Green (38)) Mevagissey ‘C’ 2 (J Chesterfield, M Chesterfield); Gorran Haven 2 (P Grimmett, R Holmes) Lerryn 3 (G Hoskin, T Middleton, D Phipps); Tywardreath ‘B’ 2 (P Hunt, K Wilkes) St Blazey 3 (M Mears (33), M Woodward, C Brown). Top breaks of the week: Paul Baron 46, D Kendall 36, Matt Green 38, Mickey Mears 33 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Barrie McIntosh is the County Singles Champ', 'barrie-mcintosh-is-the-county-singles-champ', 'League News', '[]'::jsonb, 'On Friday 11th April a decent crowd turned up to watch Barrie McIntosh take on Richard Lloyd for the coveted title of Cornwall County Singles Champion', null, null, 'On Friday 11th April a decent crowd turned up to watch Barrie McIntosh take on Richard Lloyd for the coveted title of Cornwall County Singles Champion

more Barrie having been in the final once before was desperate to continue his great finish to the season as County champion, however after a nervous start which saw Richard Lloyd win the opening 2 frames, Barrie turned on the style reeling off 5 frames in a row to take the title from the defending champ. The opening frame saw a series of misses from both players before Richard Lloyd settled first and registered a break of 32 to take the first frame, the 2nd frame took a similar vain and aided by some luck and a 52 break saw Lloyd take a 2-0 lead. Desperate to register his first frame Barrie knuckled down to snatch the 3rd frame on the final pink to get him in the match, this seemed to give Barrie the confidence he needed and a cool 39 break in the 4th saw him ease to a 2-2 scoreline at the mid session interval. After the break it was all Barrie and with breaks of 32, 62, and 30 he wrapped up the victory 5-2. St Blazey Snooker would like to thank everyone involved in arranging the final, including the County Association, St Neot Club and of course everyone who attended to support the evening. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Barrie lands the Boynton Trophy', 'barrie-lands-the-boynton-trophy', 'Competitions', '[]'::jsonb, 'Thirty-one of the leading ranking snooker players contested the Gordon Boynton Trophy at Bugle Working Mens Club last Saturday.', null, null, 'Thirty-one of the leading ranking snooker players contested the Gordon Boynton Trophy at Bugle Working Mens Club last Saturday.

more With play starting at 10am there were some of the league’s big guns knocked out in the first round namely Ian Powell, Darren Kirwan, Ryan Bilson, Mike Hancock and defending champion Jason Cocks all departing the competition to be consoled with a pint and a pasty in the bar. Play continued throughout the day and the semi-finals arrived with Gary Spencer (Bugle) knocked out on the pink by young Aaron Courts (St Neot) while in the other semi Matt Rowe (Mevagissey) tackled Barry McIntosh with Barrie victorious. The final started with Aaron having a 25-point handicap lead but this was quick wiped out when Barrie produced a 47 break. Back came Aaron with a 16 break but Barrie quickly responded with some excellent potting to take the trophy. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Barrie''s 127 break is highlight of season', 'barries-127-break-is-highlight-of-season', 'Match Reports', '[]'::jsonb, 'In the top match of the evening in the St Blazey and District Snooker League at Bugle a Barrie McIntosh superb 127 clearance break helped Tregonissey to a couple of points which put a dent in the home side’s title…', null, '"Tywardreath ‘A’ took full advantage in their title surge by trouncing Mevagissey ‘A’ 5-0. In the final frame of the night Leighton Varcoe’s 31 was bettered by Mike Hancock’s 35 to seal the win which leaves the Legion boys in a very challenging position."', 'In the top match of the evening in the St Blazey and District Snooker League at Bugle a Barrie McIntosh superb 127 clearance break helped Tregonissey to a couple of points which put a dent in the home side’s title ambitions.

more Records are being checked to see if Barry’s 127 is the highest-ever break in the league. Tywardreath ‘A’ took full advantage in their title surge by trouncing Mevagissey ‘A’ 5-0. In the final frame of the night Leighton Varcoe’s 31 was bettered by Mike Hancock’s 35 to seal the win which leaves the Legion boys in a very challenging position. Bugle ‘B’ continued their recent good run with a 3-2 win at Sparks – Richie Bolt and Mike Williams on target for the home side. George Lory saw off Jason Pascoe in the decider as Lostwithiel ‘B’ gained three valuable points to move further away from the relegation zone as they edged Bethel ‘A’ 3-2, whilst Lostwithiel ‘A’ pipped St Neot by the odd frame in their effort to move up to forth place. Mevagissey ‘C’ had a magnificent 4-1 victory at Tywardreath ‘B’ as messes Tregale, Shaw and J and M Chesterfield severely dented the Legion’s boys hopes of promotion. That result leaves St Blazey only needing two points to guarantee promotion. Not to be outdone Mevagissey ‘D’ produced a 4-1 home win over luckless Lerryn with Charles McMiram registering the away point. Bugle ‘C’ must still fancy their chances of sneaking into second place after a good 3-2 win at Bethel ‘C’ recovering from 2-0 down and Gorran Haven produced another fine performance as Rob Bunney, Lee McKinstry and Paul Grimmett victorious when defeating Bethel ‘C’.

FULL RESULTS

Victory League: Mevagissey ‘A’ 0 (NS - L Varcoe (31)) Tywardreath ‘A’ 5 (D Kirwan, P Baron, A Gooch, L Sturtridge, M Hancock (35), Bugle ‘A’ 3 (G Spencer, A Peers, P Sturtridge) Tregonissey 2 (B McIntosh (127), R Bilson), Lostwithiel ‘B’ 3 (B Warne, J Daniell, G Lory) Bethel ‘A’ 2 (G Hawken, S Allen), Sparks 2 (R Bolt, M Williams) Bugle ‘B’ 3 (I Ball, D Rundle, C Rundle), St Neot 2 (M Courts, A Tamblyn) Lostwithiel ‘A’ 3 (R Broad, A Maddams, D Lock). Rees Memorial League: Mevagissey ‘D’ 4 (R Blamey, J Prynn, M Gregory, P Eccles) Lerryn 1 (C McMiram), Gorran Haven 3 (R Bunney, L McKinstry, P Grimmett) Bethel ‘C’ 2 (J Cocks, C Crockford), Tywardreath ‘B’ 1 (A Dennis) Mevagissey ‘C’ 4 (D Tregale, N Shaw, J Chesterfield, M Chesterfield), Bethel ‘B’ 2 (B Stunell, M Sweet) Bugle ‘C’ 3 (K Moore, N Couchman, J Moore). Top breaks of the week: Leighton Varcoe 31, Mike Hancock 35, Barrie McIntosh 127 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Basement boys cause a shock', 'basement-boys-cause-a-shock', 'Match Reports', '[]'::jsonb, 'In the St Blazey and District Snooker League Victory League bottom of the table Mevagissey ‘B’ pulled off an excellent victory over third-placed Lostwithiel ‘A’ by the odd frame.', null, '"Bethel ‘A’ crawled into a 2-0 lead over Bugle ‘B’ courtesy of Steve Allen and Geoff Hawken but when Mark Sturtridge raced into a 40-1 lead over Matt Green the tide looked to of turned until Matt produced a very nice 33 break and potted most of the colours to win on the pink but Dave Rundle and Ian Ball replied giving Bethel a welcome 3-2 win."', 'In the St Blazey and District Snooker League Victory League bottom of the table Mevagissey ‘B’ pulled off an excellent victory over third-placed Lostwithiel ‘A’ by the odd frame.

more They also took the Runabout Shield back to Meva to defend in the process of their victory. Victories for Ben Rothwell over Chris Perring, Dave Kendall with a great win over Steve Courts and Mark Gregory’s final frame win over Cyril Dickenson sealed the victory. Tregonissey ‘A’ took four more points in their quest of the league title against St Blazey ‘A’. Leigh Rosevear saw off Martin Knight in the first frame but it was one-way traffic after that with Barry McIntosh with a 32 and Jason Cocks’ 44 the highlights of the evening. Gary Spencer had two 31 breaks in his frame against Roger Smithson as Bugle ‘A’ claimed all five frames against Bethel ‘C’ and wold have hoped to close the gap even further on Treggy after visiting Meva last night with the table toppers on their bye week. Bethel ‘A’ crawled into a 2-0 lead over Bugle ‘B’ courtesy of Steve Allen and Geoff Hawken but when Mark Sturtridge raced into a 40-1 lead over Matt Green the tide looked to of turned until Matt produced a very nice 33 break and potted most of the colours to win on the pink but Dave Rundle and Ian Ball replied giving Bethel a welcome 3-2 win. In the Rees League Lostwithiel ‘B’ consolidated their position at the top by seeing off Mevagissey ‘D’ 5-0 an excellent win bearing in mind Meva’s recent good run. Bethel ‘D’ slumped to a surprising 3-2 home defeat to Bugle ‘C’ who thoroughly deserved their win and could have been better but for some desperately bad luck for Kevin Spencer against Shaun Hicks. Nigel Couchman and particularly Sam Wingrave playing well on the night. Lerryn picked up an excellent 3-2 home win over St Stephen ‘A’ with David Phipps and Charles McMiram putting them two up but with Dan Allen and Gary Clark replying it was left to Graham Hoskin to beat Anthony Harrison to bag the win. Gorran Haven picked up two points at home to Bethel ‘B’ for whom Jim Tamblyn, Dave Morshead and Rich Allen won. Rob Bunney and Lee McKinstry notching the home wins seeing off Guy Buckle and Clive Sturtridge respectively. Tregonissey ‘B’ have jumped into second place thanks to a 4-1 away win at St Stephen ‘B’. Gary Wherry, Chris Robins, Justin and Phil Hooley, who made 33, were the marksmen.

FULL RESULTS

Victory League: Tregonissey ‘A’ 4 (R Bilson, B McIntosh (32), C Stephenson, J Cocks (44)) St Blazey ‘A’ 1 (L Rosevear), Bethel ‘A’ 3 (S Allen, G Hawken, M Green (33)) Bugle ‘B’ 2 (D Rundle, I Ball), Bugle ‘A’ 5 (A Best, P Strurtridge, A Peers, I Powell, G Spencer (31+31)) Bethel ‘C’ 0, Lostwithiel ‘A’ 2 (D Lock, A Maddams) Mevagissey ‘B’ 3 (B Rothwell, D Kendall, M Gregory). Rees Memorial League: Lerryn 3 (D Phipps, C McMiram, G Hoskins) St Stephen ‘A’ 2 (D Allen, C Clark), Bethel ‘D’ 2 (S Hicks, B Stunnell) Bugle ‘C’ 3 (N Couchman, K Moore, S Wingrave), Mevagissey ‘D’ 0 Lostwithiel ‘B’ 5 (J Daniell, L Flower, A Parnell, G Loy, R Broad), St Stephen ‘B’ 1 Tregonissey ‘B’ 4 (J Hooley, P Hooley (33), C Robins, G Wherry), Gorran Haven 2 (R Bunney, L McKinstry) Bethel ‘C’ 3 (J Tamblyn, D Morshead, R Allen). Top breaks of the week: B McIntosh 32, J Cocks 44, M Green 33, G Spencer 31+31, P Hooley 33 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Basement boys upset the odds', 'basement-boys-upset-the-odds', 'Match Reports', '[]'::jsonb, 'Bottom of the table Bethel ‘C’ produced the shock of the season beating top of the table Mevagissey ‘A’ on their own patch.', null, 'Nick Kendall produced a superb 71 break which was especially good as the pink and black were tied up as St Blazey ‘A’ gained a comfortable 4-1 victory over Bethel ‘D’, Steve Benallack recording the away point.', 'Bottom of the table Bethel ‘C’ produced the shock of the season beating top of the table Mevagissey ‘A’ on their own patch.

more Paul Williams’ 62 break against Paul Thomas got the evening going but Martin Powell restored parity seeing off Paul Chambers. Matt Mills secured Meva’s second point but Howard Brett easily beat Phil Staley to set up a final frame shoot-out between Kendall and Smithson and despite Chris knocking in a fine 32 break the wiley old captain of Bethel wore him down for a 66-44 victory to really open up the league title fight. Bugle ‘A’ took advantage of Meva’s slip getting four points at home to St Blazey ‘B’. Jamie Read beat Paul Sturtridge for the away side but Bugle edged the other four frames, which were all very close, to move back up to second place. St Neot recovered from last week’s set back after beating Bugle ‘B’ 4-1. Darren Lock’s 41 and 33 breaks made his game safe but credit to Jake Moore, who cleared up with a 35 clearance for some respectability. Steve Courts and Chris Perring added to the home total before Keith Moore took Bugle’s point against Anthony Maddams. Ian Hunter saw off Colin Rundle in the last. Len Flower came from 40 points behind to beat Andy Peers but was Pelynt’s only success at Bethel ‘A’ improved form continued. Geoff Hawken’s fluked black ball win over John Daniell was followed by comfortable wins for Matt Green, Leon Collard and Gary Stephens. Nick Kendall produced a superb 71 break which was especially good as the pink and black were tied up as St Blazey ‘A’ gained a comfortable 4-1 victory over Bethel ‘D’, Steve Benallack recording the away point. Mevagissey ‘B’s unbeaten record was in real trouble at Bethel ‘B’, going 2-0 down after victories by Clive Stuthridge and Guy Buckle. But the Meva boys dug deep and Dave Kendall, Nathan Shaw and Matt Rowe got them home. Mevagissey ‘C’ returned from Lerryn with a 3-2 win. Joe Chesterfield had a few shaky moments when beating Charles McMiram but Predator Tregale had to buy the sausage rolls at work on Wednesday morning after he lost to Terry Middleton. Matt Chesterfield and James Stephens traded frames leaving Charlie Prynn’s victory over Dave Vipond to settle the result. Bodmin Q-Bar stand in second place after gaining a decent 3-2 away win at Mevagissey ‘D’. Nigel Allen, Richie Bolt and Steve Bampton were the winners with Malcolm Meneer pushing Rich Lakeman all the way in the last frame. George Lory got Meva’s second point when defeating Mike Bolt. There were four black ball finishes between Gorran Haven and St Stephen ‘B’. Andy Reddall (Darren Biggen), Richard Holmes (Josh Doherty), Lee McKinstry (Terry Nicholls) were successful for the home side with Craig Nicholls getting the better of Rob Bunney for St Stephen’s point with Paul Grimmett comfortable win over Rob Garside completing the Seasiders’ win.

FULL RESULTS

Victory League: Bugle ‘A’ 4 (Andrew Best, Gary Spencer, Ian Ball, Ian Powell) St Blazey ‘B’ 1 (Jamie Read), St Blazey ‘A’ 4 Bethel ‘D’ 1 (Steve Benallack), Mevagissey ‘A’ 2 (Paul Williams (62), Matt Mills) Bethel ‘C’ 3 (Martin Powell, Howard Brett, Roger Smithson), Bethel ‘A’ 4 (Leon Collard, Geoff Hawken, Matt Green, Gary Stephens) Pelynt 1 (Len Flower), St Neot 4 (Steve Courts, Darren Lock (41+33), Chris Perring, Ian Hancock) Bugle ‘B’ 1 (Keith Moore). Rees Memorial League: Bethel ‘B’ 2 (Clive Stuthridge, Guy Buckle) Mevagissey ‘B’ 3 (Nick Kendall, Nathan Shaw, Matt Rowe), Lerryn 2 (Terry Middleton, James Stephens) Mevagissey ‘C’ 3 (Joe Chesterfield, Matt Chesterfield, Charlie Prynn), Mevagissey ‘D’ 2 (George Lory, Rich Lakeman) Bodmin Q-Bar 3 (Nigel Ahern, Rich Bolt, Steve Bampton), Gorran Haven 4 (Andy Reddall, Richard Holmes, Paul Grimmett, Lee McKinstry) St Stephen ‘B’ 1 (Craig Nicholls). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: P Williams 62, D Lock 41+33, N Kendall 71 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bazzer the dazzler', 'bazzer-the-dazzler', 'Match Reports', '[]'::jsonb, 'After first netting a 32 break in his first frame against R Maddams, Barry McIntosh returned to the table to record a magnificent 101 break to help his Tregonissey side beat Lostwithiel ‘A’ 4-1 with Darren Lock’s…', null, '"Tywardreath ‘A’ moved to within two points of the summit as they triumphed 4-1 over Bugle ‘B’ for whom league stalwart Mo Rescorla captured the scalp of Darren Kirwan."', 'After first netting a 32 break in his first frame against R Maddams, Barry McIntosh returned to the table to record a magnificent 101 break to help his Tregonissey side beat Lostwithiel ‘A’ 4-1 with Darren Lock’s breaks of 34 and 31 claiming the away side’s only point.

more Tregonissey are now only three points behind leaders Bugle ‘A’. Tywardreath ‘A’ moved to within two points of the summit as they triumphed 4-1 over Bugle ‘B’ for whom league stalwart Mo Rescorla captured the scalp of Darren Kirwan. St Neot made a welcome return to winning ways at Mevagissey ‘A’ as all the three Courts – Aaron, Michael and Steve won their frames along with Martin Rowe with Rich Lakeman Meva’s marksman. Bethel ‘A’ completed a good 4-1 home win over Mevagissey ‘B’ with Matt Mills playing really well to beat Steve Allen for Meva’s point. St Blazey continued their relentless surge for the Rees league title despatching Mevagissey ‘C’ 3-2 and opening up a six-point lead over Bethel ‘B’ who had a bye. Bethel ‘D’ moved up to second place beating Mevagissey ‘D’ 4-1 with Andy ‘40 winks’ Spearman the pick of the Bethel players. Gorran Haven raced into a 3-0 lead over Tywardreath ‘B’ but Graham Kent and Alan Dennis shared the lead for a 3-2 result – another great result for Gorran in their first year in the league. Bugle ‘C’ also kept their recent good form going with a 5-0 thrashing of Lerryn.

FULL RESULTS

Victory League: Mevagissey ‘A’ 1 (R Lakeman) St Neot 4 (A Courts, M Courts, S Courts, M Rowe); Lostwithiel ‘B’ 3 (A Parnall, G Lory, L Rossiter) Sparks 2 (S Bampton, R Bolt); Bethel ‘A’ 4 (G Stephens, B Stephens, G Hawken, L Collard) Mevagissey ‘B’ 1 (M Mills); Tywardreath ‘A’ 4 (A Gooch, P Baron, M Hancock, L Sturtridge) Bugle ‘B’ 1 (M Rescorla); Tregonissey 4 (B McIntosh (32 and 101), C Stevenson, C Kendall, R Pearson) Lostwithiel ‘A’ 1 (D Lock 34 and 31). Rees Memorial League: Mevagissey ‘D’ 1 (R Blamey) Bethel ‘D’ 4 (D Morshead, A Spearman, R Tonkin, V Hathway); Gorran Haven 3 (A Reddall, L McKinstrey, R Bunney) Tywardreath ‘B’ 2 (G Kent, A Dennis); St Blazey 3 (L Roseveare, M Woodward, C Brown) Mevagisey ‘C’ 2 (M Chesterfield), N Shaw); Lerryn 0 Bugle ‘C’ 5 (K Moore, J Moore, N Couchman, K Spencer, J Conroy). Top breaks of the week: Barrie McIntosh 101 & 32, Darren Lock 34 & 31 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Best of the rest for Bugle', 'best-of-the-rest-for-bugle', 'Match Reports', '[]'::jsonb, 'Andrew Best’s 44 break helped Bugle ‘A’ return from Lostwithiel ‘B’ with a 4-1 victory to keep the title surge going whilst Tregonissey claimed four points over Bethel ‘A’.', null, '"The Mevagissey derby ended with a 3-2 victory for the ‘A’ team – Matt Mills’ fine 39 break gave him a great victory over Leighton Varcoe."', 'Andrew Best’s 44 break helped Bugle ‘A’ return from Lostwithiel ‘B’ with a 4-1 victory to keep the title surge going whilst Tregonissey claimed four points over Bethel ‘A’.

more Bob Stephens was 28 points ahead of Ryan Bilson but a 35 clearance gave Bilson the frame only for Leon Collard to overcome Barry McIntosh in the last frame to claim Bethel’s point. The Mevagissey derby ended with a 3-2 victory for the ‘A’ team – Matt Mills’ fine 39 break gave him a great victory over Leighton Varcoe. Sparks picked up two useful points when visiting St Neot, Clive Sturtridge and Steve Banpton scoring heavily when registering the away team’s point. In the Rees League David Tregales victory over Paul Eccles claimed bragging rights for the ‘C’ team in another Mevagissey derby. Bethel ‘D’ moved into second place after beating their ‘B’ team 4-1, Ben Stidwell defeating Vince Hathway for his side’s only point. While Dave Phipps and Dave Vipond picked up two useful points for Lerryn against Tywardreath ‘B’ with Alan Dennis knocking in a fine 44 for the visitors who move into third place in the league. St Blazey moved closer still to the title with a comfortable 4-1 victory over Bethel ‘C’ Jason Cocks victory over Stuart Dewings the only bright spot for the home side.

FULL RESULTS

Victory League: Mevagissey ‘B’ 2 (B Rothwell, M Mills (39)) Mevagissey ‘A’ 3 (M Fox, P Staley, M Towsey); Lostwithiel ‘B’ 1 (L Flower) Bugle ‘A’ 4 (A Best (44), P Sturtridge, G Spencer, I Powell); St Neot 3 (A Courts, T Farrant, M Rowe) Sparks 2 (C Sturtridge, S Bampton); Bugle ‘B’ 2 (D Rundle, C Rundle) Lostwithiel ‘A’ 3 (C Dickenson, C Perrin, D Lock (48)); Tregonissey 4 (R Pearson, R Bilson (35), C Kendall, C Stephenson) Bethel ‘A’ 1 (R Collard). Rees Memorial League: Mevagissey ‘C’ 3 (B Prynn, Ed Chesterfield, D Tregale) Mevagissey ‘D’ 2 (R Blamey, C Prynn); Lerryn 2 (D Phipps, D Vipond) Tywardreath ‘B’ 3 (P Hunt, A Dennis (44), K Wilks); Bethel ‘D’ 4 (A Spearman, J Pascoe, T Stephen, R Tonkin) Bethel ‘B’ 1 (B Stunnell); Bethel ‘C’ 1 (J Cocks) St Blazey 4 (M Woodward, L Rosevear, C Brown, L Reynolds). Top breaks of the week: Andrew Best 44, Ryan Bilson 35, Matt Mills 39, Alan Dennis 44, Darren Lock 48. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Best’s 82 break for Bugle in Bethel victory', 'bests-82-break-for-bugle-in-bethel-victory', 'Match Reports', '[]'::jsonb, 'A superb break of 82 by Andrew Best of Bugle ‘A’ helped his side to pip Bethel ‘A’.', null, '"Mevagissey ‘D’ have jumped from seventh to equal fourth place in the league after a excellent 4-1 win at Bethel ‘B’. James Tomlinson, Richard Lakeman, Rob Blamey and Adam Pollard their winners with Clive Stuthridge replying with the Meva boys hopeful of continuing their good form until the end of the season."', 'A superb break of 82 by Andrew Best of Bugle ‘A’ helped his side to pip Bethel ‘A’.

more Andrew was unlucky not to go on to a well deserved century and overtake the highest break so far of 101 by Darren Lock. Good wins by Gary Stephens and Leon Collard gave Bethel a chance but Gary Spencer’s final-frame win was enough for the win. In the evening’s top match Tregonissey ‘A’ pipped St Blazey ‘B’ 3-2. Wins for Barry McIntosh (39) and Chris Stephenson (30) and Jason Cocks did the damage. There were also breaks of 39 by Ryan Bilson and a 35 by Darren Kirwan but they both lost on the night. Mevagissey ‘B’ pulled off a great 4-1 home win over Bugle ‘B’ courtesy of Matt Rowe, Mark Gregory, Dave Kendall and Nathan Shaw with Ian Ball replying. Those four points helped Meva draw level with Bethel ‘C’ at the bottom. The Bethel lads could not believe how unlucky they were to lose 4-1 at home to Mevagissey ‘A’. Roger Smithson beat Matt Mills and Martin Powell and Howard Brett were in winning positions only to be denied by clearances by Pete Chambers and Paul Williams respectively. Lostwithiel ‘A’ picked up a 4-1 home win over St Blazey ‘A’. Darren Lock with a 32 with wins for Cyril Dickenson, Steve Courts, Anthony Maddams as well with Matt Woodward replying for the Blazey boys. Tregonissey ‘B’ gave runaway leaders Lostwithiel ‘B’ a run for their money before losing 3-2. There were good wins for Richard Opie and Ryan Thomas only to be outdone by Josh Daniell, George Lory and Richard Broad. Mevagissey ‘D’ have jumped from seventh to equal fourth place in the league after a excellent 4-1 win at Bethel ‘B’. James Tomlinson, Richard Lakeman, Rob Blamey and Adam Pollard their winners with Clive Stuthridge replying with the Meva boys hopeful of continuing their good form until the end of the season. Bethel ‘D’ remain second following a good 4-1 away win at Gorran Haven. Andy Reddall beat Ben Stunnell to get Gorran’s point but three tight frames on the night all went the way of the Bethel boys. Bugle ‘C’ produced a sterling 3-2 victory at Mevagissey ‘C’ with Ed Cook, Kev Spencer and young Sam Wingrave their heroes with Charlie Prynn and ‘predator’ Tregale notching for the home side. St Stephen ‘B’ thought that they had beaten Lerryn 3-2 at home but sadly played an ineligible player so forfeited the frame and the match so Charles McMiram has a win against his name for Lerryn despite only scoring one point from the match.

FULL RESULTS

Victory League: Lostwithiel ‘A’ 4 (C Dickenson, S Courts, A Maddams, D Lock (32)) St Blazey ‘A’ 1 (M Woodward), Mevagissey ‘B’ 4 (M Rowe, M Gregory, D Kendall, N Shaw) Bugle ‘B’ 1 (I Ball), Bethel ‘C’ 1 (R Smithson) Mevagissey ‘A’ 4 (C Kendall, P Chambers, P Williams, P Staley), St Blazey ‘B’ 2 (P Baron, G Taylor – D Kirwan (35 break)) Tregonissey ‘A’ 3 (B McIntosh (39), C Stephenson (30), J Cocks – R Bilson (39 break), Bugle ‘A’ 3 (I Powell, A Best (82), G Spencer) Bethel ‘A’ 2 (L Collard, G Stephens). Rees Memorial League: Mevagissey ‘C’ 2 (D Tregale, C Prynn) Bugle ‘C’ 3 (Ed Cook, K Spencer, S Wingrave), Tregonissey ‘B’ 2 (R Opie, R Thomas) Lostwithiel ‘B’ 3 (J Daniell, G Lory, R Broad), Bethel ‘B’ 1 (C Stuthridge) Mevagissey ‘D’ 4 (J Tomlinson, R Lakeman, R Blamey, A Pollard), St Stephen ‘B’ 2 (R Garside, J Doherty) Lerryn 3 (C McMiram, G Hoskin, T Middleton), Gorran Haven 1 (A Reddall) Bethel ‘D’ 4 (S Hicks, R Tonkin, J Pascoe, A Spearman). Top breaks of the week: D Lock 32, D Kirwan 35, B McIntosh 39, C Stephenson 30, R Bilson 39 A Best 82. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bethel avoid the wooden spoon', 'bethel-avoid-the-wooden-spoon', 'Match Reports', '[]'::jsonb, 'The big talking point of the final league games in the St Blazey and District Snooker League was who would end up with the wooden spoon in the Victory League.', null, '"Runners-up Mevagissey ‘A’ suffered an odd frame home reverse to St Blazey ‘B’. Pete Chambers and Matt Mills got the home points with Paul Baron, Graham Taylor and Mike Hancock, with an excellent 59 break replied."', 'The big talking point of the final league games in the St Blazey and District Snooker League was who would end up with the wooden spoon in the Victory League.

more Bethel ‘C’ held a two-point advantage over Mevagissey ‘B’ but faced a tough game at Bugle ‘B’. Martin Powell beat Keith Moore to give Bethel an early advantage but Mark Sturtridge, Ian Ball and Dave Rundle put the home side 3-1 up. The final frame went to respot between Jake Moore and Howard Brett and after over 10 minutes of excellent safety play Howard sunk the black to claim the point, which as it turned out saved them from a play-off match Mevagissey ‘B’. The Meva boys produced a stirring fightback form 2-0 down at Bethel ‘A’ to claim a fine win which was all in vain as veteran Leighton Varcoe, Nathan Shaw and Ben Rothwell were the winners. Runners-up Mevagissey ‘A’ suffered an odd frame home reverse to St Blazey ‘B’. Pete Chambers and Matt Mills got the home points with Paul Baron, Graham Taylor and Mike Hancock, with an excellent 59 break replied. Bugle ‘A’s disappointing season ended with a home defeat to Lostwithiel ‘A’. Andy Peers and Paul Sturtridge had put them 2-1 up but Chris Perring and Steve Courts followed up Darren Lock’s victory to give Losty the victory. In the Rees League St Stephen ‘A’ recorded an excellent 4-1 win at Bethel ‘B’ to leapfrog the opponents into third place. Clive Stuthridge was the only victor for the home side as Dan Allen, Anthony Garside and Cary Clarke and Anthony Harrison sealed the big win. Champions Lostwithiel ‘B’ beat runners-up Bethel ‘D’ 3-2 a respotted black between John Daniell and Jason Pascoe the standout frame which Jason pinched with Bethel’s other point gained by Steve Benallack. Mevagissey ‘D’ ended with a 3-2 victory at Lerryn. Scott Mills, James Tomlinson and Rob Blamey with Gordon Brimicombe and a rare win for Dave Phipps registered the home side and Mevagissey ‘C’ rounded off their season with a 3-2 home win over Gorran Haven. Predator Tregale’s excellent victory over Lee McKinstry the highlight of the evening. Matt and Joe Chesterfield both won for the home side with Rob Bunney and Richard Holmes replying. The league’s presentation night is on Saturday, April 18 at Mevagissey Social Club, 7.30pm start. It will be followed by a buffet and Razorlight Disco with the main prize on the night is winning two tickets for two people to attend the world snooker championships semi-finals at Sheffield. For details contact Geoff on 078055 93185.

FULL RESULTS

Victory League: Bugle ‘A’ 2 (A Peers, P Sturtridge) Lostwithiel ‘A’ 3 (D Lock, C Perring, S Courts), Mevagissey ‘A’ 2 (P Chambers, M Mills) St Blazey ‘B’ 3 (P Baron, M Hancock (59), G Taylor), Bethel ‘A’ 2 (M Green, G Stephens) Mevagissey ‘B’ 3 (L Varcoe, N Shaw, B Rothwell), Bugle ‘B’ 3 (I Ball, D Rundle, M Sturtridge) Bethel ‘C’ 2 (H Brett, M Powell). Rees Memorial League: Bethel ‘B’ 1 (C Sturthridge) St Stephen ‘A’ 4 (D Allen, A Garside, C Clarke, A Harrison), Lostwithiel ‘B’ 3 (L Flower, G Lory, R Broad) Bethel ‘D’ 2 (J Pascoe, S Benallack), Lerryn 2 (G Brimicombe, D Phipps) Mevagissey ‘D’ 3 (S Mills, J Tomlinson, R Blamey) Mevagissey ‘C’ 3 (J Chesterfield, M Chesterfield, D Tregale) Gorran Haven 2 (R Bunney, R Holmes). Top breaks of the week: M Hancock 59 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bethel bounce back to move to the top of the pile', 'bethel-bounce-back-to-move-to-the-top-of-the-pile', 'Match Reports', '[]'::jsonb, 'Bethel ‘A’ have moved to the top of the Victory League after victory at St Blazey ‘A’.', null, 'Tregonissey ‘A’ picked up four points at home to Pelynt whose Phil Ormand beat Ryan Bilson for their point. Barrie McIntosh, Jason Simmonds, Martin Knight and Jason Cocks’ first win of the season gave them the victory.', 'Bethel ‘A’ have moved to the top of the Victory League after victory at St Blazey ‘A’.

more It started well for the home side as Liam Reynolds beat Matt Green but Geoff Hawken, Gary Stephens, who knocked in a fine 50 break, Andy Peers and Leon Collard, who luckily pipped Nick Kendall, secured a 4-1 win. Mevagissey ‘B’ continue to pick up good points and took two from Bugle ‘A’, Andrew Best and Paul Sturtridge put the home side ahead but Ben Rothwell’s fine 75-22 victory over Gary Stephens and Mark Gregory’s win over Ian Ball sandwiched by Jake Moore’s win gave the Meva boys a deserved win. Tregonissey ‘A’ picked up four points at home to Pelynt whose Phil Ormand beat Ryan Bilson for their point. Barrie McIntosh, Jason Simmonds, Martin Knight and Jason Cocks’ first win of the season gave them the victory. Mevagissey ‘A’ and St Neot had a great match. Darren Lock knocked in a 53 as he beat Leighton Varcoe whilst Pete Chambers had a 31 when beating Cyril Dickenson, Phil Staley (Chris Perring) and Matt Mills’ close victory over Anthony Maddams secured Meva’s win with a vintage performance from Steve Courts got St Neot’s second point. Tregonissey ‘B’ continue to top the Rees League after a 3-2 win at Gorran. Lee McKinstry and Rob Bunney got the home points with Mark Sullivan and Justin and Phil Hooley bagging the win. Bethel ‘B’ remain second after a tight 3-2 home win over Lerryn. Richard Bolt, Guy Buckle and Matt Green got the home points with Graham Hoskin turning over Clive Stuthridge and Terry Middleton getting the better of Martin Isted for the away team. Stacey Hancock got Treggy’s ‘C’ off to a good start at home to Bethel ‘D’ beating Andy Spearman but that was as good as it got as Dave Morshead, Lee Searle, Jason Pascoe and Ross McMenemy secured a 4-1 win.

FULL RESULTS

Victory League: Bugle ‘A’ 3 (A Best, P Sturtidge, J Moore) Mevagissey ‘B’ 2 (B Rothwell, M Gregory), St Blazey ‘A’ 1 (L Reynolds) Bethel ‘A’ 4 (G Hawken, G Stephens (50), A Peers, L Collard), Mevagissey ‘A’ 3 (P Staley, P Chambers (31), M Mills) St Neot 2 (D Lock (53), S Courts), Tregonissey ‘A’ 4 (B McIntosh, J Simmonds, M Knight, J Cocks) Pelynt 1 (P Ormand), St Stephen ‘A’ 1 (A Garside) Bugle ‘B’ 4 (M Strurtridge, K Moore, D Rundle, T Conroy). Rees Memorial League: Gorran 2 (L McKinstry, R Bunney) Tregonissey ‘B’ 3 (M Sullivan, J Hooley, P Hooley), Tregonissey ‘C’ 1 (S Hancock) Bethel ‘D’ 4 (D Morshead, L Searle, J Pascoe, R McMenemy), Bethel ‘B’ 3 (R Bolt, G Buckle, M Green) Lerryn 2 (G Hoskins, T Middleton). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: D Lock 53 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bethel cause major shock', 'bethel-cause-major-shock', 'Match Reports', '[]'::jsonb, 'Bottom of the table team Bethel ‘D’ really put the future of the Victory League title back in the melting pot by seeing off table toppers Bugle ‘A’ 3-2.', null, '"There were four very tight frames as Bethel ‘A’ came away from Mevagissey ‘A’ with a 3-2 victory, with Leighton Varcoe and Ben Prynn winning for the home side, while Lostwithiel ‘A ‘picked up a very useful 3-2 home win over Tregonissey courtesy of Dan Courtis, Chris Perring and Darren Lock."', 'Bottom of the table team Bethel ‘D’ really put the future of the Victory League title back in the melting pot by seeing off table toppers Bugle ‘A’ 3-2.

more Richie Allen, Martin Knight and Ryan Tonkin secured the win as they face their battle against relegation, while Gary Spencer''s 40 and 37 clearance failed to lift the gloom in the Bugle corner. St Blazey ‘B’ took full advantage to record a 4-1 home victory over Lostwithiel B, and could have expected a clean sweep as Mike Hancock fired in a 31 break, only to lose to Jason Hill, but the victory put them back on level points with Bugle ‘A’. St Blazey ‘A’ returned from St Neot with a great 3-2 win as Chris Brown, Nick Kendall and Liam Reynolds, in his first game of the season, took them to victory - Steve Courts recorded a 33 break for the latter when seeing off Leigh Rosevear. There were four very tight frames as Bethel ‘A’ came away from Mevagissey ‘A’ with a 3-2 victory, with Leighton Varcoe and Ben Prynn winning for the home side, while Lostwithiel ‘A ‘picked up a very useful 3-2 home win over Tregonissey courtesy of Dan Courtis, Chris Perring and Darren Lock. The delayed match on Thursday night saw Bugle ‘A’ move four points clear at the top of the table after seeing off St Neot, with only Steve Courts stopping the whitewash. Mevagissey ‘B’ remain at the top of the Rees League after winning 4-1 at Lerryn, for whom Gordon Brimicombe was victorious. They have been joined at the top by Bethel ‘C’, who whitewashed Bugle ‘C’ through Roger Smithson, Martin Powell, Courtney Crockford, Steve Jones and Paul Thomas. But having played a game more, the victory for Bethel ‘B’ at Gorran Haven meant all four teams from the club had wins and keeps the ‘B’ team well in the running for promotion. Ben Prynn was break-building again this time with a 31, as Mevagissey ‘C’ triumphed 3-2 at home to Bodmin Sparks - Dave Tregale and Matt Chesterfield victorious with Clive Stuthridge and Mike Bolt on target for the Sparks. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bethel ‘C’ stun high-flying Lostwithiel ‘A’', 'bethel-c-stun-high-flying-lostwithiel-a', 'Match Reports', '[]'::jsonb, 'There were two stand out results, one from each league to make the headlines this week in the St Blazey and District Snooker League.', null, '"Mevagissey ‘A’ remain in second place with a 3-2 win away at St Blazey ‘A’. Leigh Rosevear and Nick Kendall won for the home side with Pete Chambers’ 35 and Paul Williams’ 56 with victory also for captain Staley securing the win."', 'There were two stand out results, one from each league to make the headlines this week in the St Blazey and District Snooker League.

more They now look clear favourites at this early stage. In the Victory League Bethel ‘C’ recorded their first league win by walloping high-flying Lostwithiel ‘A’ 4-1 – Darren Lock’s fine 52 break was the visitors only bright spot as Thomas, Crockford, Brett and Powell saw off the strangely out of sorts visitors – who could have no complaints about the result. The result moves the ‘C’ team, up with their ‘A’ team and Bugle ‘B’ in the league. Another strong performance from table toppers Tregonissey ‘A’ saw them move seven points clear at the summit after returning from Bugle ‘B’ 4-1 victors. Martin Knight’s black ball win over Ian Ball was vital to them while Jason Cocks had a 36 break but lost his frame to Dave ‘Shorts’ Rundle; Ryan Bilson also weighed in with a 32. Mevagissey ‘A’ remain in second place with a 3-2 win away at St Blazey ‘A’. Leigh Rosevear and Nick Kendall won for the home side with Pete Chambers’ 35 and Paul Williams’ 56 with victory also for captain Staley securing the win. St Blazey ‘B’ won 4-1 at Mevagissey ‘B’ who remain firmly rooted to the bottom of the league. Nathan Shaw picked up a good win over Darren Kirwan, but wins for Mike Hancock, Brian Phillips, Paul Baron and Graham Taylor took the points back to Blazey. In the Rees League leaders Lostwithiel ‘B’ scored a terrific 5-0 home win over second-placed Bethel ‘D’. There were four very fight frames on the night which all went the way of the leaders to inflict Bethel’s first defeat of the season, opening up a six-point lead at the top of the table. George Lory, Richard Broad, Andy Parnell and Len Flower and John Daniell were the home marksmen. Dave Phipps and Terry Middleton recorded their first wins of the season as Lerryn secured an excellent 4-1 victory at Bugle ‘C’. Graham Hoskin and Gordon Brimicombe also won with Kev Spencer replying for the hosts. Tregonissey ‘B’ had to come from 2-1 behind to pip Gorran Haven by the odd frame – Andy Reddall and Richard Holmes potting the away points but Steve Simon and Phil and Michael Hooley captured the win. Mevagissey ‘D’ continued their good form by beating St Stephen ‘A’ 4-1 for their fourth win on the trot. Rob Blamey, James Tomlinson, Scott Mills and Rich Lakeman were the winners with Stacey Hancock replying. On Thursday evening Tregonissey ‘A’ won 3-1 at Bethel ‘C’. The highlight of the evening being a fantastic 108 break by Barry McIntosh.

FULL RESULTS

Victory League: St Blazey ‘A’ 2 (L Rosevear, N Kendall) Mevagissey ‘A’ 3 (P Chambers, P Williams, P Staley), Bugle ‘B’ 1 (D Rundle) Tregonissey ‘A’ 4 (M Knight, R Bilson (32), B McIntosh, C Stephenson - J Cocks (36 but lost)), Mevagissey ‘B’ 1 (N Shaw) St Blazey ‘B’ 4 (M Hacnock, B Phillips, P Baron, G Taylor), Bethel ‘C’ 4 (P Thomas, C Crockford, H Brett, M Powell) Lostwithiel ‘A’ 1 (D Lock). Rees Memorial League: St Stephen ‘A’ 1 (S Hancock) Mevagissey ‘D’ 4 (R Blamey, S Mills, R Lakeman, J Tomlinson) Bugle ‘C’ 1 (K Spencer) Lerryn 4 (D Phipps, G Brimicombe, T Middleton, G Hoskin), Lostwithiel ‘B’ 5 (G Lory, R Broad, A Parnell, L Flower, J Daniell) Bethel ‘D’ 0, Tregonissey ‘B’ 3 (S Simon, P Hooley, M Hooley) Gorran Haven 2 (A Reddall, R Holmes). Mevagissey ‘C’ v St Stephen ‘B postponed’. Top breaks of the week: R Bilson 32, J Cocks 36, P Chambers 35, P Williams 56, D Lock 52 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Big breaks for Tregonissey', 'big-breaks-for-tregonissey', 'Match Reports', '[]'::jsonb, 'Victory League leaders Tregonissey knocked in three breaks of 30 as they took four points at home to Bugle ‘B’.', null, 'Bethel ‘A’ went three up at St Neot through Andy Peers, Matt Green and Garry Stephens, who knocked in a fine 31, with Darren Lock and Steve Courts taking the final two frames for the home side.', 'Victory League leaders Tregonissey knocked in three breaks of 30 as they took four points at home to Bugle ‘B’.

more Ryan Bilson’s 37, Jason Cocks’ 31 and Barrie McIntosh, also with a 31, along with Martin Knight got their points with Mark Sturtridge beating Richard Pearson for the away point. Bugle ‘A’ kept well clear in second as they took all five frames against Mevagissey ‘B’, who are in deep trouble at the base of the table. Four of the frames were well contested but Ian Ball, Andrew Best, Ian Powell, Gary Spencer and Paul Sturtridge all secured wins. Bethel ‘A’ went three up at St Neot through Andy Peers, Matt Green and Garry Stephens, who knocked in a fine 31, with Darren Lock and Steve Courts taking the final two frames for the home side. St Blazey picked up a 4-1 win at home to Mevagissey ‘D’ thanks to wins for Liam Reynolds, Chris Morford, Mickey Meares and Dean Willis. Matt Ashton took out Stewart Dewings for the away point. Justin Hooley and Stuart Giles got two away points for Tregonissey ‘B’ at Pelynt, who sealed the win through Len Flower, Richard Broad and Phil Ormond. Bethel ‘C’ closed the gap on leaders Mevagissey ‘C’ as they got four points at home to St Stephen. Leigh Rosevear and Paul Thomas put them two up only for Dan Parmenter to beat Courtney Crockford to pull one back but the home team responded with Howard Brett and captain Roger Smithson winning their games. Leaders Mevagissey ‘C’ dropped two points at home to Tregonissey ‘C’. ‘The Predator’ Tregale, Ben Prynn and Matt Chesterfield got their points with Carol Stephens beating Adrian Evans and Alan Meades defeating Joe Chesterfield for the away team. Bethel ‘D’ keep plugging away hoping for any slip-ups by the top two. This time they took four points at home to Lostwithiel. Steve Benallack, Jason Pascoe, Andy Spearman (walkover) and Ross McMenemy did the damage with Terry Nicholls pipping Dave Morshead for Lostwithiel’s single point. Graham Hoskin beat Mo Roscorla to give Lerryn the lead at Bugle ‘C’ and despite some close games Bugle took the last four through Nigel Couchman, Kevin Spencer, Damian Knight and Roy Bayliss. Matt Fox and Steve Williams got two points for Gorran at home to Bethel ‘B’ with Rob Bunney just missing out to give Clive Stuthridge what would have been his second defeat of the season, but he survived and with wins also for Scott Patterson and Guy Buckle the away side took the spoils.

FULL RESULTS

Victory League: Bugle ‘A’ 5 (I Ball, A Best, I Powell, G Spencer, P Sturtridge) Mevagissey ‘B’ 0, Tregonissey ‘A’ 4 (R Bilson (37), J Cocks (31), M Knight, B McIntosh (31)) Bugle ‘B’ 1 (M Sturtridge), Pelynt 3 (L Flower, R Broad, P Ormond) Tregonissey ‘B’ 2 (J Hooley, S Giles), St Blazey 4 (L Reynolds, C Morford, M Meares, D Willis) Mevagissey ‘D’ 1 (M Ashton), St Neot 2 (D Lock, S Courts) Bethel ‘A’ 3 (A Peers, G Stephens (31), M Green). Rees Memorial League: Gorran 2 (M Fox, S Williams) Bethel ‘B’ 3 (S Patterson, C Stuthridge, G Buckle), Bugle ‘C’ 4 (N Couchman, K Spencer, D Knight, R Bayliss) Lerryn 1 (G Hoskin), Mevagissey ‘C’ 3 (D Tregale, B Prynn, M Chesterfield) Tregonissey ‘C’ 2 (C Stephens, A Meades), Bethel ‘C’ 4 (L Rosevear, P Thomas, H Brett, R Smithson) St Stephen 1 (D Parmenter), Bethel ‘D’ 4 (S Benallack, J Pascoe, A Spearman (w/o), R McMenemy) Lostwithiel 1 (T Nicholls). Top breaks of the week: R Bilson 37, J Cocks 31, B McIntosh 31, G Stephens 31 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Big night in the Victory League', 'big-night-in-the-victory-league', 'Match Reports', '[]'::jsonb, 'It was a massive night in the Victory League title race as second placed Tregonissey ‘A’ now head the table courtesy of a five point win at St Neot.', null, 'St Blazey ‘B’ are now out of the race despite a 4-1 home victory over doomed Bethel ‘D’. Martin Powell’s victory over Dave Grose, their single frame, as Paul Baron, Andrew Gooch, Graham Taylor and Mike Hancock secured a top four finish.', 'It was a massive night in the Victory League title race as second placed Tregonissey ‘A’ now head the table courtesy of a five point win at St Neot.

more Previous leaders Mevagissey ‘A’ slumped to a 4-1 home defeat to Bugle ‘A’ and the top two played each other last night with Meva needing a win to keep the race alive. There were big wins for all five Treggy players with Jason Cocks knocking in a 30 break and pivotal wins for Jason Simmons and Ryan Bilson over Steve Courts and Darren Lock respectively. Pete Chambers’ victory over Andrew Best was Meva’s only bright spot as Paul Sturtridge, Gary Spencer, Ian Powell and Ian Ball kept Bugle right in the mix. St Blazey ‘B’ are now out of the race despite a 4-1 home victory over doomed Bethel ‘D’. Martin Powell’s victory over Dave Grose, their single frame, as Paul Baron, Andrew Gooch, Graham Taylor and Mike Hancock secured a top four finish. Bethel ‘D’s fate was settled following a 3-2 home reverse to Pelynt. Richard Broad, Andy Parnell and Dan Chivers got the away side’s frames with Jason Pascoe and Ryan Tonkin replying. Mickey Meares knocked in a nice 38 break in his frame against Andy Peers and Nick Kendall defeated Gary Stephens but this couldn’t stop St Blazey ‘A’ slipping to defeat at Bethel ‘A’ for whom Dave Patton, Bob Stephens and Matt Green prevailed. Mevagissey ‘B’ secured the Rees League title with a 4-1 victory at St Stephen ‘B’. Terry Nicholls got the home point but Rothwell, Shaw, Gregory and Rowe got the deserved champs home. They are now three teams on 47 points in the race for second promotion spot Anthony Garside, Dan Allen and Cary Clarke with Graham Hoskin and Charles McMiram replying. Bethel ‘B’ are right in the race after defeating Gorran Haven 4-1. Matt Fox was victorious for the home side but Bethel shaded three tight frames to secure the win. Bodmin Q-Bar suffered a 4-1 defeat at Tregonissey ‘B’. Brian Barnicoat’s second win of the season got the away point but Gary Wherry and Phil, Justin and Mike Hooley all got important wins for the Treggy boys.

FULL RESULTS

Victory League: Bethel ‘A’ 3 (Dave Patton, Bob Stephens, Matt Green) St Blazey ‘A’ 2 (Nick Kendall, Mickey Meares (38)), Bethel ‘D’ 2 (Jason Pascoe, Ryan Tonkin) Pelynt 3 (Richard Broad, Andy Parnell, Dan Chivers), Mevagissey ‘A’ 1 (Pete Chambers) Bugle ‘B’ 4 (Paul Sturtridge, Gary Spencer, Ian Powell, Ian Ball), St Blazey ‘B’ 4 (Paul Baron, Mike Hancock, Andrew Gooch, Graham Taylor) Bethel ‘C’ 1 (Martin Powell), St Neot 0 Tregonissey ‘A’ 5 (Chris Stephenson, Martin Knight, Jason Cocks (30), Jason Simmons, Ryan Bilson). Rees Memorial League: Tregonissey ‘B’ 4 (Gary Wherry, Phil Hooley, Justin Hooley, Mike Hooley) Bodmin Q-Bar 1 (Brian Barnicoat), Lerryn 2 (Graham Hoskins, Charles McMiram), St Stephen ‘A’ 3 (Anthony Garside, Dan Allen, Cary Clarke), Gorran Haven 1 (Matt Fox) Bethel ‘B’ 4 (Jim Tamblyn, Clive Stuthridge, Guy Buckle, Dave Morshead), St Stephen ‘B’ 1 (Terry Nicholls) Mevagissey 4 (Ben Rothwell, Nathan Shaw, Mark Gregory, Matt Rowe). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: M Meares 38, J Cocks 30 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bingham Beats Allen To Take Shanghai Crown', 'bingham-beats-allen-to-take-shanghai-crown', 'Professional Snooker', '[]'::jsonb, 'Stuart Bingham won the second world ranking title of his career by thrashing Mark Allen 10-3 in the final of the Bank of Communications OTO Shanghai Masters.', null, '""The scoreline was flattering," admitted Bingham. "I started off very well but from 4-1 every frame could have gone either way. I was fortunate to be 6-3 up and tonight I scrapped my way through."', 'Stuart Bingham won the second world ranking title of his career by thrashing Mark Allen 10-3 in the final of the Bank of Communications OTO Shanghai Masters.

more Bingham outplayed his opponent in a one-sided final as Allen failed to reproduce the form which saw him beat Mark Selby in the semi-finals yesterday. World number 11 Bingham won five consecutive frames from 5-3 as he coasted to the £85,000 top prize. The 38-year-old from Basildon in Essex doubled his career tally of ranking titles having won his first at the 2011 Australian Goldfields Open. He avoided a third straight loss in ranking finals having finished second best to Ricky Walden at the 2012 Wuxi Classic and Stephen Maguire at the 2013 Welsh Open. Bingham, who also won the invitational Premier League in 2012, has been one of the biggest beneficiaries of the dramatic growth of the World Snooker Tour over the past five years, from less than ten events per season to around 30. A player who simply loves competing in tournaments above anything else, Bingham has found the best and most consistent form of his career in his mid-to-late 30s, allowing him to make the transition from journeyman to prolific winner. Bingham, who beat home favourite Ding Junhui in the semi-finals yesterday, dominated the early stages of the final, taking the first four frames with top breaks of 99 and 68. Northern Ireland''s Allen got off the mark with a 97 and appeared to be back in the match when he cleared with 41 to close to 4-2. The next two frames were shared, then Bingham crucially won the ninth by potting blue, pink and black to make it 6-3 at the end of the first session. The opening frame of the evening session was another scrappy one and again Bingham snatched it, clearing from last red to pink. That virtually ended Allen''s resistance as his Bingham dominated the 11th for 8-3 then took the last two with runs of 57 and 81. "The scoreline was flattering," admitted Bingham. "I started off very well but from 4-1 every frame could have gone either way. I was fortunate to be 6-3 up and tonight I scrapped my way through. "I''m delighted to win such a big title, it means a lot. Mark Williams calls me Chesney Hawkes because he says I''m a one-hit wonder, so he won''t be able to call me that any more. Knowing that you can win a title brings different pressures and I have knocked on the door a few times since. It''s very tough to win a tournament these days but after I beat Dominic Dale here in the second round, and played really well, I thought it could be my week." Allen, who missed out on the third ranking title of his career, said: "I''m very disappointed to lose, but more disappointed by the way I played. From start to finish I struggled, and Stuart capitalised on the mistakes I made. He was the deserving winner on the day. At 6-3 down I felt I could still win, but the first two frames of the evening session were scrappy, I had chances in both but didn''t take them. At 8-3 down I felt I wasn''t playing well enough to come back. "I''m still proud of myself for the way I handled situations in the match which didn''t go quite my way. I''ve been nowhere near my best this week but I''ve handled myself well and that shows I''m going in the right direction." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Bingham Is Championship League King', 'bingham-is-championship-league-king', 'Professional Snooker', '[]'::jsonb, 'Stuart Bingham won the eighth annual Championship League Snooker event by beating Mark Davis 3-2 at Crondon Park in Essex in the internet-streamed event.', null, '"Davis had led the best of five final 2-1 to look favourite for the victory. A break of 126 by Bingham in the fourth frame, the second best of the final group, levelled things before a run of 79 sealed the win."', 'Stuart Bingham won the eighth annual Championship League Snooker event by beating Mark Davis 3-2 at Crondon Park in Essex in the internet-streamed event.

more In total 27 players competed in this year''s event but it was the most local, Bingham, who scooped the honours and with it an accumulated cash total of £28,500. In addition, the win guarantees Bingham a spot in the starting line-up of the exclusive Champion of Champions tournament which takes place in Coventry in November. The Basildon potter said: "I am over the moon. It is a great field of players here and a long tournament if you stay in a few groups. It isn''t just about winning this; it is getting the Champion of Champions spot too. "I lost a couple of matches at the start of the group and ended up having to beat Barry Hawkins 3-0 to get into the play-offs, I managed that and so maybe the writing was on the wall. "It can be an endurance test and in the end there wasn''t much to separate myself and Mark but it''s a great one to win." Davis had led the best of five final 2-1 to look favourite for the victory. A break of 126 by Bingham in the fourth frame, the second best of the final group, levelled things before a run of 79 sealed the win. Hastings-based Davis hauled off a total of £24,650 for his efforts. Earlier, the experienced duo saw off young pretenders Matthew Selt and Ben Woollaston in their semi final matches. The Championship League Snooker event is a venture between Matchroom Sport and Perform where 25 of the game''s elite players compete with all matches broadcast on a host of betting websites. Results The Final Stuart Bingham 3-2 Mark Davis 84-1 (72), 7-86 (30, 40), 10-68 (43), 126-2 (126), 79-0 (79) Semi-Finals Matthew Selt 1-3 Stuart Bingham 64-20, 0-110 (110), 18-58 (34), 41-63 Mark Davis 3-2 Ben Woollaston 24-75 (45), 38-85 (38, 85), 67-28 (57), 80-0 (80), 58-25 Thursday Group Results Matthew Selt 1-3 Mark Davis 8-69 (59), 119-0 (47, 72), 34-80 (34, 80), 0-88 (79) Barry Hawkins 3-2 Ben Woollaston 80-0 (80), 39-79 (67), 105-5 (105), 22-55, 57-8 Stuart Bingham 0-3 Xiao Guodong 43-55 (Bingham 30, Xiao 35), 43-68 (43, 43), 1-63 (55) Allister Carter 1-3 Ben Woollaston 0-84 (57), 1-76 (60), 57-29, 0-52 Barry Hawkins 3-0 Mark Davis 60-39 (40), 70-0 (70), 79-0 (34, 45) Matthew Selt 3-0 Xiao Guodong 58-9 (42), 71-67 (Selt 36, Xiao 30), 139-0 (139) Matthew Selt 3-2 Ben Woollaston 68-42 (45), 1-88 (52), 71-0 (49), 1-101 (101), 66-2 (35, 31) Allister Carter 2-3 Mark Davis 71-52 (Carter 50, Davis 52), 40-87 (Carter 40, Davis 43), 102-0 (102), 31-61, 51-63 (51, 58) Barry Hawkins 0-3 Stuart Bingham 40-70 (40, 70), 14-63 (34), 9-77 (50) Centuries 139 - Matthew Selt v Xiao Guodong 126 - Stuart Bingham v Mark Davis (F) 124 - Matthew Selt v Barry Hawkins 118 - Stuart Bingham v Ben Woollaston 116 - Matthew Selt v Allister Carter 110 - Stuart Bingham v Matthew Selt (SF) 105 - Barry Hawkins v Ben Woollaston 103 - Allister Carter v Matthew Selt 103 - Mark Davis v Stuart Bingham 102 - Allister Carter v Mark Davis 101 - Stuart Bingham v Mark Davis 101 - Ben Woollaston v Matthew Selt Article courtesy of the World Snooker Images Courtesy of: Da Zhuang', '2014-01-01', false, 'Richard Pearson'),
  ('Bingham is Prince of Wales', 'bingham-is-prince-of-wales', 'Professional Snooker', '[]'::jsonb, 'Stuart Bingham beat Judd Trump 9-8 in a thrilling Coral Welsh Open final to win his first title since becoming World Champion 21 months ago.', null, '“It means a lot to me, I had a tear in my eye when I was clearing up. All the practice, the determination and the friends and family supporting me. It has been a tough road from winning the World Championship, but that makes it ever sweeter to get my hands on another trophy.”', 'Stuart Bingham beat Judd Trump 9-8 in a thrilling Coral Welsh Open final to win his first title since becoming World Champion 21 months ago.

more Bingham let slip a 4-0 lead and fell behind at 8-7, but won the last two frames to clinch the £70,000 top prize and the Ray Reardon Trophy. It was gripping stuff for a packed Motorpoint Arena in the closing stages as a succession of frames came down to the colours, and Bingham won just enough of them before making an excellent match-winning break in the decider. The 40-year-old from Basildon landed the fourth ranking title of his career and ended a long wait for more silverware since his Crucible triumph in 2015. By winning his first Welsh Open crown, Bingham buried the memory of the 2013 final in Newport when he was edged out 9-8 by Stephen Maguire. He stays at number two in the world rankings, still well behind Mark Selby. Trump missed out on the chance to win two ranking titles in the same season for the first time, having landed the European Masters in October. He has now lost seven of his 13 ranking finals and six of his 11 meetings with Bingham. The 27-year-old from Bristol still moves up one place in the rankings to third thanks to his £30,000 runner-up prize. Trump, playing in his first Welsh Open final, trailed 5-3 after the first session but quickly halved the gap tonight by dominating the first frame of the evening. He was first among the balls in frame ten but missed the black off its spot on 48 and Bingham punished him with a 63 clearance to go 6-4 up. Runs of 41 and 27 gave Trump the next frame and he also won the 12th after laying a snooker on the final yellow, to draw level at 6-6 at the interval. Trump looked favourite in frame 13 until he went in-off while escaping from a snooker on the last red, and Bingham made a cool clearance to regain the lead. Frame 14 also came down to the last red, and this time Bingham escaped from a snooker but left the red over a baulk corner, allowing his opponent to level at 7-7. Trump then took the lead for the first time by winning an edgy 15th, potting the thinnest of cuts on the final green to a centre pocket and clearing to the pink. But Bingham hit back to win a tense 40-minute 16th, laying a snooker on the brown then making a clearance which included a doubled pink to a centre pocket. Both players had chances early in the decider, and Trump was unlucky not to open the pack when potting the yellow when he led 25-24. After a brief safety exchange, Bingham fired in a long red and then kept his composure in a run of 55 which got him past the winning line. “I’m just thankful to get my hands on this trophy,” said Bingham, who has won four of his seven ranking finals. “I don’t know how I did it, maybe true grit and determination. “I started really well but then Judd came out showing his true class. He came out all guns blazing tonight, I didn’t know where to put the white ball in the end. He plays one way and that is attack, that is why he is a big hit with the fans and a great snooker player. “I honestly don’t know what got me over the line tonight, but I did it somehow. “It means a lot to me, I had a tear in my eye when I was clearing up. All the practice, the determination and the friends and family supporting me. It has been a tough road from winning the World Championship, but that makes it ever sweeter to get my hands on another trophy.” Trump said: “It isn’t too bad to take. At 4-0 down I was disappointed, but the rest of the match I was quite good. I dominated most of the frames, but threw away a few and that changed the match. “You get punished at this level if you miss easy balls. I just fell a little bit short today. It was just the odd shot here and there that could have gone right and I would have won. I had my chances in the last frame and messed them up. “I was probably the better player in tonight’s session. I just didn’t score heavily enough.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Bingham on top of the world', 'bingham-on-top-of-the-world', 'Professional Snooker', '[]'::jsonb, 'Stuart Bingham won the Betfred World Championship for the first time by beating Shaun Murphy 18-15 in an extraordinary final at the Crucible.', null, 'It’s just unreal,” he said. “You dream of it as a kid playing. But it’s reality now. I’m going to be the same person, playing in all the tournaments, and I’ll be hopefully a good role-model. Any kids out there growing up that want to play, just stick at it. With a lot of hard work, a lot of practice and a lot of self-belief, something like this can happen.', 'Stuart Bingham won the Betfred World Championship for the first time by beating Shaun Murphy 18-15 in an extraordinary final at the Crucible.

more Murphy looked to have the momentum when he came from 15-12 down to 15-15, but Bingham won a crucial hour-long 31st frame and went on to take the next two to win the famous trophy and £300,000 top prize. After his second round win over Graeme Dott, Bingham revealed that “once I was out there, a calm descended on me, and stayed for the whole match.” That state of calmness at the table remained throughout the tournament, and he finished a superb match in the style of a true champion. Starting the event a 50-1 outsider having never previously been beyond the quarter-finals in Sheffield, Bingham has won the tournament the hard way, knocking out Ronnie O’Sullivan and Judd Trump before coming from 8-4 down to see off 2005 champion Murphy. Basildon’s 38-year-old Bingham, who made his Crucible debut 15 years ago, is the oldest first-time winner since Walter Donaldson, who was 40 when he took his maiden title in 1947, and must be grouped with Joe Johnson, Graeme Dott and Murphy himself as the shock winners of the modern era. Considered something of a journeyman pro for much of his 20-year career, Bingham didn’t win a ranking tournament or figure among the world’s top 16 until capturing the 2011 Australian Goldfields Open. That victory added a huge injection of self-belief to his undoubted talent, and he has since become a prolific winner. Indeed this season he had already won three tournaments, including his second ranking title at the Shanghai Masters. He may have carried the nickname Ball-Run since his amateur days, but there is nothing lucky about this triumph. It’s reward for countless years of hard work, dedication to practice and playing in virtually any tournament he could enter. He is a man who simply loves nothing more than playing snooker, and has won the affection of many for what Barry Hearn described as a “beautiful ordinariness.” Bingham, who was supported tonight by wife Michelle and three-year-old son Shae, climbs to a career-high ranking of second, and also earns a place in the England team at the World Cup in China in June, where he will play alongside Mark Selby. Murphy missed out on the chance to become only the sixth player to lift the trophy more than once at the Crucible, after Steve Davis, Stephen Hendry, John Higgins, Mark Williams and Ronnie O’Sullivan. The 32-year-old has enjoyed great success this season with an all-out attack approach at the table, notably winning the Masters with a 10-2 thumping of Neil Robertson. The Nottingham-based cueman played superb snooker en route to the world final and was odds-on favourite before the match. But after a strong start, not enough of his trademark long pots found their target, and he was picked off by Bingham’s superior all-round game. Five-time ranking event winner Murphy takes home a cheque for £125,000. One of the highest quality finals in Crucible history featured six centuries and 24 more breaks over 50 in the 33 frames. Trailing 14-11 going into the concluding session, Murphy dominated the opening frame tonight with top runs of 33 and 28. Bingham responded with a 102, his tenth century of the tournament and the 86th in all, to restore his three-frame lead at 15-12. Bingham looked to be cruising further ahead when he led 55-0 in the next, but a missed black off the spot let Murphy in for an excellent 75 clearance, highlighted by a cracking pot on the last red. There was also a chance for Bingham in the 29th frame but he missed a tricky pink with the rest and Murphy capitalised with 64 to trail by just one at the interval. Further errors from Bingham in the 30th, twice missing reds to a top corner, allowed Murphy to take it in three scoring visits to draw level at 15-15. The epic 31st frame lasted 63 minutes and came down to the colours. Murphy missed the final yellow when he had a chance to clear, then gave away 38 points in fouls after being trapped in three snookers. Bingham then potted yellow and green to edge 16-15 ahead. Bingham made a classy 55 early in the next before missing a red to top corner, but Murphy was unable to manufacture a counter-attack and when Bingham potted the fourth-last red he was two up with three to play. And when Murphy missed a risky long red early in frame 33, Bingham seized his opportunity brilliantly with a match-winning 88. “At 15-15 I thought my chance was gone, my arm felt like someone else’s and nerves sort of got to me,” said Bingham, who joins Ken Doherty as the only player to win the world title at amateur and professional level. “But we had a marathon 31st frame and I pinched it on the colours, and from then on I played pretty solid. “I got through my first round against Robbie Williams with a bit of a cold, and then went from strength to strength. I had a great win over Graeme Dott and then a great, great win over Ronnie. I was worried playing Judd, because I needed to capitalise on my chance. I could easily not be sitting here, Judd had a kick when it was 16-16. As Shaun said, sometimes your name is on the trophy. “In the last frame I was just playing one ball at a time. I actually didn’t realise I’d won the frame until the crowd clapped, then I looked at the score and realised. “I was the underdog against Ronnie and Judd, but when I came out for the final I might have had 80 per cent of the crowd and I just thought ‘wow’. It’s just unbelievable to be sitting here as world champion. “Just to witness and experience the final, I didn’t care if I won or lost to start with. In the first session I came out at 4-4 and then I thought ‘I can do this.’ Then we had a good battle until the end.” Murphy said: “I’m disappointed, nobody wants to lose in the final. But the way Stuart played all the way through the tournament, he played like a champion. When I went 8-4 up he wasn’t worried about it, he played like a winner all the way through the match. Sometimes in sport people are meant to win things. Stuart is a massive fan of the game, he loves snooker more than life itself, he fully deserves to win this tournament. I’m disappointed to lose but I’m very, very happy for him and his family. “I know how hard it is to win this championship. He made such a nice break in the last frame. I can have no regrets really, I feel I’ve played some really great stuff throughout this championship. There can only be one winner and again unfortunately this year it wasn’t me. “It seemed to be very good scoring throughout the final, good tactical play, not many missed chances. I thought we put on a really good show.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Blazey blow their chance of being in the title mix', 'blazey-blow-their-chance-of-being-in-the-title-mix', 'Match Reports', '[]'::jsonb, 'A very tense end of the season awaits as most of the top teams still have to play each other but St Blazey ‘B’ look to have blown their chances after crashing to a 4-1 defeat at Tregonissey ‘A’.', null, 'Bugle ‘A’ have jumped back into contention following a full house win over Pelynt. Phil Ormand pushed Ian Ball all the way but lost 63-61 and wins for Andrew Best (52), Gary Spencer, Ian Powell and Paul Sturtridge leaves them still in with a shout.', 'A very tense end of the season awaits as most of the top teams still have to play each other but St Blazey ‘B’ look to have blown their chances after crashing to a 4-1 defeat at Tregonissey ‘A’.

more It had all started so well for them as Jamie Read knocked in breaks of 34 and 32 when defeating Ryan Bilson but wins for Chris Stephens (Mike Hancock), Jason Simmons (Andrew Gooch), Jason Cocks, who had a 32 in his win over Graham Taylor, and Martin Knight’s black ball win over Paul Baron saw them stay two points behind Mevagissey ‘A’. Meva themselves won 4-1 at home to doomed Bethel ‘D’. The visitors started well with Steve Banallack beating Pete Chambers but Phil Staley, 32 break, Matt Mills, Paul Williams and Chris Kendall’s black ball win over Ryan Tonkin sees them remain at the summit. Bugle ‘A’ have jumped back into contention following a full house win over Pelynt. Phil Ormand pushed Ian Ball all the way but lost 63-61 and wins for Andrew Best (52), Gary Spencer, Ian Powell and Paul Sturtridge leaves them still in with a shout. Bottom of the table Bethel ‘C’ pulled off an excellent odd frame win at St Neot. Howard Brett and Roger Smithson put them 2-0 up but Darren Lock who had a 58 clearance and Steve Courts levelled things up but Ben Stunnell was Bethel’s hero as he beat Cyril Dickinson in the last to send the visitors home happy. Bugle ‘B’ picked up a superb 4-1 win at St Blazey ‘A’. Keith Moore and Dave and Colin Rundle put them 3-0 up before Nick Kendall replied with a 62 break to see off Mark Sturtridge only for Jake Moore to beat Leigh Rosevear to moved Bugle 10 points clear of the relegation spot. Mevagissey ‘D’ certainly hold the bragging rights after thumping previously unbeaten champions elect Mevagissey ‘B’. They romped into a 3-0 lead through Rob Blamey, Ian Latham and Rich Lakeman. Dave Kendall replied only for George Lory to hammer Mark Gregory for their fourth point. Lerryn slumped to a 4-1 home defeat to Tregonissey ‘B’. Graham Hoskin saw off Aiden Craddock for their point but wins for Gary Wherry and Justin, Phil and Michael Hooley got the visitors home. Gorran had an excellent 4-1 home win over Mevagissey ‘C’ to move equal on points with them. Lee McKinstry started the ball rolling slaying the Predator and further wins for Paul Grimmett, Andy Reddall and Rob Bunney followed with Matt Chesterfield beating Richard Holmes for the the away side. Malcolm Meneer and Brian Barnicoat, with his first league win, got Bodmin Q-Bar’s two points at St Stephen ‘A’. Stuart Bell, Cary Clarke and Anthony Harrison secured wins for the home side who stay right in the promotion mix.

FULL RESULTS

Victory League: Bugle ‘A’ 5 (Andrew Best (52), Gary Spencer, Ian Ball, Ian Powell, Paul Sturtridge) Pelynt 0, St Blazey ‘A’ 1 (Nick Kendall (62)) Bugle ‘B’ 4 (Keith Moore, Dave Rundle, Colin Rundle, Jake Moore), Tregonissey ‘A’ 4 (Chris Stephenson, Jason Simmons, Jason Cocks (34), Martin Knight) St Blazey ‘B’ 1 (Jamie Read (32+34)), Mevagissey ‘A’ 4 (Phil Staley (32), Matt Mills, Paul Williams, Chris Kendall) Bethel ‘D’ 1 (Steve Benallack), St Neot 2 (Darren Lock (58 clearance), Steve Courts) Bethel ‘C’ 3 (Howard Brett, Roger Smithson, Ben Stunnell). Rees Memorial League: t Stephen ‘A’ 3 (Stuart Bell, Cary Clarke, Anthony Harrison) Bodmin Q-Bar 2 (Brian Barnicoat, Malcolm Meneer), Lerryn 1 (Graham Hoskin) Tregonissey ‘B’ 4 (Justin Hooley, Gary Wherry, Phil Hooley, Mike Hooley), Mevagissey ‘D’ 4 (Rob Blamey, Ian Latham, Rich Lakeman, George Lory) Mevagissey ‘B’ 1 (Dave Kendall), Gorran Haven 4 (Lee McKinstry, Paul Grimmett, Andy Reddall, Rob Bunney) Mevagissey ‘C’ 1 (Matt Chesterfield). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: A Best 52, N Kendall 62, J Cocks 34, J Read 32+34, P Staley 32, D Lock 58 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Blazey boys extend their lead at the top', 'blazey-boys-extend-their-lead-at-the-top', 'Match Reports', '[]'::jsonb, 'St Blazey ‘B’ continued their title surge with a convincing 4-1 home victory over Bugle ‘B’ with Darren Kirwan’s 44 and Mike Hancock’s 53 clearance the highlights of the evening.', null, '"Top result in the Rees League saw Mevagissey ‘B’ triumph 4-1 at Bodmin Sparks to jump to joint top of the league with Bethel ‘C’ who gained a 3-2 victory over their ‘B’ team with Howard Brett, Roger Smithson and Martin Powell securing the win."', 'St Blazey ‘B’ continued their title surge with a convincing 4-1 home victory over Bugle ‘B’ with Darren Kirwan’s 44 and Mike Hancock’s 53 clearance the highlights of the evening.

more Jake Moore’s victory over Baz Baron was the only bright spot for the visitors. Chasing Bugle ‘A’ were in fine form when running up a 3-0 lead at home to St Blazey ‘A’ but Chris Brown and Mickey Meares pegged them back for two crucial points in the title race. In the Bethel derby Jason Pascoe and Ryan Tonkin picked up two valuable points for the basement boys the ‘D’ side but messrs Allen, Rowe and Hawken saw the ‘A’ team home whilst St Neot travelled away from Mevagissey ‘A’ with a 3-2 victory as Mike and Steve Courts with Martin Rowe were successful with Matt Mills and Leighton Varcoe registering for the Seasiders. The Lostwithiel derby saw the ‘A’ team victorious 3-2 over their ‘B’ team – Josh Daniell and Richard Broad won for the ‘B’ team but Chris Perring, Dan Courts and Darren Lock, who had a 50 break, took the bragging rights for the ‘A’ side. Top result in the Rees League saw Mevagissey ‘B’ triumph 4-1 at Bodmin Sparks to jump to joint top of the league with Bethel ‘C’ who gained a 3-2 victory over their ‘B’ team with Howard Brett, Roger Smithson and Martin Powell securing the win. And in the Mevagissey derby the ‘D’ team strengthened by the inclusion of Richard Lakeman produced a great 4-1 victory over their ‘C’ team and could perhaps make a late challenge for the title. Gorran Haven moved above non-playing Bugle ‘C’ at the bottom when they gained two points at home to St Stephen. Lee McKinstry and Andy Reddall took the home side’s points but Anthony Garside, Cary Clark and Anthony Harrison in the deciding frame to the victory back to Clay Country.

FULL RESULTS

Victory League: Bethel ‘A’ 3 (S Allen, N Rowe, G Hawken) Bethel ‘D’ 2 (J Pascoe, R Tonkin), Bugle ‘A’ 3 (A Best, G Spencer (30), A Peers) St Blazey ‘A’ 2 (C Brown, M Meares), Lostwithiel ‘B’ 2 (J Daniell, R Broad) Lostwithiel ‘A 3 (D Lock (50), C Perring, D Courts), St Blazey ‘B’ 4 (G Taylor, A Gooch, D Kirwan (44), M Hancock (53) Bugle ‘B’ 1 (J Moore), Mevagissey ‘A’ 2 (M Mills, L Varcoe) St Neot 3 (A Courts, S Courts, M Rowe). Rees Memorial League: Mevagissey ‘D’ 4 (J Tomlinson, S Mills, N Parker, R Lakeman) Mevagissey ‘C’ 1 (M Chesterfield), Sparks 1 (M Bolt) Mevagissey ‘B’ 4 (D Kendall, M Gregory, N Shaw, M Rowe), Bethel ‘B’ 2 (G Buckle, J Tamblyn) Bethel ‘C’ 3 (H Brett, M Powell, R Smithson), Gorran Haven 2 (L McKinstry, A Reddall) St Stephen 3 (A Garside, C Clark, A Harrison). Top breaks of the week: G Spencer 30, D Lock 50, D Kirwan 44, M Hancock 53 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Blazey boys rise to the summit', 'blazey-boys-rise-to-the-summit', 'Match Reports', '[]'::jsonb, 'As expected St Blazey ‘B’ climbed to the top of the St Blazey and District Victory League after claiming a 5-0 whitewash of Bethel ‘D’.', null, '"The victory sees them open up a three-point lead on Bugle ‘A’ at the halfway point of the season – Mike Hancock with a 31 break and three breaks of 20 was unstoppable in amassing 106 points against Ryan Tonkin."', 'As expected St Blazey ‘B’ climbed to the top of the St Blazey and District Victory League after claiming a 5-0 whitewash of Bethel ‘D’.

more The victory sees them open up a three-point lead on Bugle ‘A’ at the halfway point of the season – Mike Hancock with a 31 break and three breaks of 20 was unstoppable in amassing 106 points against Ryan Tonkin. Tregonissey also had a clean sweep at Lostwithiel ‘B’ a result which leaves John Daniell’s boys with a massive job to avoid relegation, Barry McIntosh compiled a great 79 break before unluckily breaking down as he threatened the top break. Mevagissey ‘A’ won the mid-table battle over Bugle ‘B’ as Chris Kendall a rejuvenated Mike Towsey and Matty Mills were victorious as were Rave Rundle and Jake Moore for the Bugle boys. Lostwithiel ‘A’ have pulled clear at the bottom after a good 3-2 win at St Neot with Darren Lock’s 39 break the highlight. Bethel ‘A’ picked up a fantastic 4-1 victory at St Blazey ‘A’ a night which saw Steve Allen’s first victory of the season with a 32-break. Matt Woodward also weighed in with a 31 while thrashing Geoff Hawken. The Rees League is amazing as only 12 points separate top to bottom – Mevagissey ‘B’ made a big statement at Bugle ‘C’ by coming away with a 5-0 victory to move joint-second and Bodmin Sparks triumphed 3-2 at Mevagissey ‘D’ to sit nicely in third place with James Tomlinson and Scott Mills on the mark for the Fishermen. Gorran Haven’s second victory of the season, a 3-2 home win over Lerryn courtesy of Rob Bunney, Lee McKinstry and Andy Reddall saw them close the gap on Bugle ‘C’ to just one point with Lerryn leapfrogging the Bugle boys with their two points. Mevagissey ‘C’ had a nightmare evening at St Stephen as Gary Clark, Stacey Hancock, John Bennett and Carole Stephens, with her first win of the season, saw the home side victorious with Matt Chesterfield replying.

FULL RESULTS

Victory League: Bethel ‘D’ 0 St Blazey ‘B’ 5 (A Gooch, P Baron, D Kirwan, M Hancock (31), G Taylor), Lostwithiel ‘B’ 0 Tregonissey 5 (R Bilson, J Cocks, B McIntosh (79), C Stephenson, R Pearson), Mevagissey ‘A’ 3 (C Kendall, M Towsey, M Mills) Bugle ‘B’ 2 (D Rundle, J Moore), St Blazey ‘A’ 1 (M Woodward (31) Bethel ‘A’ 4 (G Stephens, B Stephens, L Collard, S Allen (32)), St Neot 2 (S Courts, I Wilton) Lostwithiel ‘A’ 3 (D Lock (39), D Courts, C Perring). Rees Memorial League: Bugle ‘C’ 0 Mevagissey 5 (M Rowe, N Shaw, D Kendall, M Gregory, B Rothwell), Mevagissey ‘D’ 2 (J Tomlinson, S Mills) Sparks 3 (R Bolt, C Stuthridge, M Williams), Gorran Haven 3 (R Bunney, L McKinstry, A Reddall) Lerryn 2 (C McMiram, G Brimicombe), St Stephen 4 (C Clark, S Hancock, J Bennett, C Stephens) Mevagissey ‘C’ 1 (M Chesterfield). Top breaks of the week: B McIntosh 79, M Hancock 31, M Woodward 31, S Allen 32, D Lock 39 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Blazey pip the leaders', 'blazey-pip-the-leaders', 'Match Reports', '[]'::jsonb, 'The big match of the evening proved thrilling to the end as second-placed St Blazey ‘B’ pipped leaders Bugle ‘A’ by the odd frame – Andrew Best’s 39-break gave the away side a 2-0 lead but Paul Baron and Darren…', null, '"Mevagissey ‘A’ caused a surprise by defeating Tregonissey 3-2 as Leighton Varcoe, Matt Mills and Chris Kendall against his old team secured the win."', 'The big match of the evening proved thrilling to the end as second-placed St Blazey ‘B’ pipped leaders Bugle ‘A’ by the odd frame – Andrew Best’s 39-break gave the away side a 2-0 lead but Paul Baron and Darren Kirwan levelled the scores.

more In the decider Paul Sturtridge opened up a 20-point lead going into the colours but a fine 27 clearance by Mike Hancock clinched victory for Blazey and also inflicted a first defeat of the season for Poweller and Stir-fry. Mevagissey ‘A’ caused a surprise by defeating Tregonissey 3-2 as Leighton Varcoe, Matt Mills and Chris Kendall against his old team secured the win. Bethel ‘D’ are well adrift at the bottom after a 4-1 home defeat by St Blazey ‘A’ who jumped to joint third place Ryan Tonkin getting the home side’s frame. Lostwithiel ‘B’ picked up a welcome win at Bugle ‘B’ with Len Flower, Richard Broad and Jason Hill who had a 55-break securing the win and all thee Courts – Steve, Aaron and Michael were winners with Bob Stephens and Leon Collard successful as St Neot beat Bethel ‘A’ by the odd frame. Bethel ‘B’ leapfrogged their ‘C’ team after defeating St Stephen 3-2 to top the league with Guy Bicklle. Steve Hicks and Mike Sweet their winners. There was an excellent win for Lerryn over Mevagissey ‘D’ as messrs Phipps, Brimincombe and Hoskin moved the basement boys level with Gorran Haven, who crashed 4-1 at home to Bodmin Sparks, who moved up to fourth spot in a very tight division as only 11 points separate top from bottom. There was another good night for the ‘C’ team in the Mevagissey derby as Matt and Joe Chesterfield and Ben Prynne helped secure the bragging rights over their ‘B’ team who remain in third place thanks to Matt Rowe and Dave Kendall’s frame wins.

FULL RESULTS

Victory League: Bethel ‘D’ 1 (R Tonkin) St Blazey ‘A’ 4 (C Brown, M Meares, M Woodward, S Dewings), Bugle ‘B’ 2 (J Moore, I Ball) Lostwithiel ‘B’ 3 (J Hill (55), L Flower, R Broad), Mevagissey ‘A’ 3 (L Varcoe, M Mills, C Kendall) Tregonissey 2 (R Bilson, C Stephenson), St Blazey ‘B’ 3 (P Baron, D Kirwan, M Hancock) Bugle ‘A’ 2 (A Best (39), G Spencer), St Neot 3 (A Courts, M Courts, S Courts) Bethel ‘A’ 2 (B Stephens, L Collard). Rees Memorial League: Lerryn 3 (D Phipps, G Brimicombe, G Hoskin) Mevagissey ‘D’ 2 (R Blamey, N Parker), Mevagissey ‘C’ 3 (M Chesterfield, J Chesterfield, B Prynne) Mevagissey ‘B’ 2 (M Rowe, D Kendall), Gorran Haven 1 (R Holmes) Sparks 4 (R Bolt, M Williams, S Bampton, M Bolt), St Stephen 2 (A Harrison, A Garside) Bethel ‘B’ 3 (G Buckle, S Hicks, M Sweet). Top breaks of the week: J Hill 55, A Best 39 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Blazey''s B boys forced to pull out of the league', 'blazeys-b-boys-forced-to-pull-out-of-the-league', 'Match Reports', '[]'::jsonb, 'It was a bad week for the league as St Blazey ‘B’ pulled out after only playing two matches due to lack of players.', null, 'Tregonissey ‘B’ are top of the Rees League after a 4-1 win at St Stephen ‘B’. Rob Garside beat Michael Hooley in the first frame but with Mark Sullivan winning a close second frame against Craig Nicholls which was followed by easy wins for Ryan Thomas and Phil and Justin Hooley.', 'It was a bad week for the league as St Blazey ‘B’ pulled out after only playing two matches due to lack of players.

more In the Victory League Mevagissey ‘A’ are top of the table after a close 3-2 victory over their ‘B’ team who have made a good start to the season themselves. James Popperwell produced a 39 break for the second week running in beating Mark Gregory, Matt Mills and the legend Varcoe also won but Nathan Shaw and Dave Kendall both won on the black to give the ‘B’ side a respectable result. Bugle ‘A’ were cruising at home to St Blazey ‘A’ through Jake Moore. Ian Ball and Gary Spencer but the away team fought back with Stewart Dewing beating Andrew Best and in-form Mickey Meares defeating Mark Sturthridge. Tregonissey ‘A’ recorded their first win of the season beating St Stephen ‘A’ 4-1. Dan Allen beat Jason Cocks in the first frame but Martin Knight, Barrie McIntosh, Ryan Bilson and Matt Woodward helped moved them up to joint third. Tregonissey ‘B’ are top of the Rees League after a 4-1 win at St Stephen ‘B’. Rob Garside beat Michael Hooley in the first frame but with Mark Sullivan winning a close second frame against Craig Nicholls which was followed by easy wins for Ryan Thomas and Phil and Justin Hooley. Jacqui Hancock recorded Tregonissey C’s first point of the season beating Martin Isted of Bethel ‘B’ but Richie Bolt, Jim Tamblyn, Clive Stuthridge and Guy Buckle saw them move into second place. In the Mevagissey derby ‘C’ team beat the ‘D’ team 4-1 with three frames decided on the black which were all won by the ‘C’ team. Rich Lakeman switched rooms to beat Ben Prynn but Joe and Matt Chesterfield, Charlie Prynn and The Predator sealed the bragging rights. In the Bethel derby the ‘C’ team showed their promotion potential as they defeated their ‘D’ team 4-1. Lee Searle’s last-frame victory over Ben Stunnell prevented the whitewash but Leigh Rosevear, Howard Brett, Courtney Crockford and captain Roger Smithson have put them fourth in the league with a game in hand on all above.

FULL RESULTS

Victory League: Bugle ‘A’ 3 (Jake Moore, I Ball, G Spencer) Bugle ‘B’ 2 (S Dewings, M Meares), Mevagissey ‘A’ 3 (M Mills, J Popperwell (39), L Varcoe) Mevagissey ‘B’ 2 (N Shaw, D Kendall), Tregonissey ‘A’ 4 (M Knight, B McIntosh, R Bilson, M Woodward) St Stephen ‘A’ 1 (D Allen). Rees Memorial League: Bethel ‘C’ 4 (L Rosevear, H Brett, C Crockford, R Smithson) Bethel ‘D’ 1 (L Searle), Mevagissey ‘D’ 1 (R Lakeman) Mevagissey ‘C’ 4 (J Chesterfield, D Tregale, C Prynn, M Chesterfield), Tregonissey ‘C’ 1 (J Hancock) Bethel ‘D’ 4 (R Bolt, C Buckle, J Tamblyn, C Stuthridge), St Stephen ‘B’ 1 (R Garside) Tregonissey ‘B’ 4 (M Sullivan, R Thomas, P Hooley, J Hooley). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: J Popperwell 39, Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bond Claims Seniors Title', 'bond-claims-seniors-title', 'Professional Snooker', '[]'::jsonb, 'Nigel Bond won the Wyldecrest Park Homes World Seniors Championship without conceding a frame in his four matches at the Mountbatten Centre in Portsmouth.', null, null, 'Nigel Bond won the Wyldecrest Park Homes World Seniors Championship without conceding a frame in his four matches at the Mountbatten Centre in Portsmouth.

more Bond, who still plays on the main tour and is ranked 45 in the world, beat Welshman Tony Chappel 2-0 in the best-of-three final having seen off Dennis Taylor, Tony Knowles and last year''s winner Darren Morgan en route to the final. Both finalists had come through qualifying to claim their place in the tournament and former World Championship finalist Bond took a close first frame 68-54 after both players missed opportunities to take a 1-0 lead by potting the black. The second frame was more one-sided with breaks of 33 and 28 helping Bond to take it 66-4 and claim the £18,000 prize money. "It is a great feeling," he said on collecting his trophy. "It has been a great weekend, all of the players have enjoyed it. "I think I played a bit scrappy yesterday and only really got going in the second frame against Chappel but then I felt I got into a nice rhythm. I was playing great on the practice table but sometimes it is not always easy to put it out there on the match table." Runner-up Chappel conceded the best player won. "I have really enjoyed it and I have got further than I expected to get," he said. "The better man definitely won. Nigel is a tour player and you could see on the table that he was playing like one and looked like one, and that was the difference." Article courtesy of the World Snooker Images Courtesy of: Action Images Last 16 Darren Morgan 2-0 Joe Johnson Dennis Taylor 0-2 Nigel Bond Dene O''Kane 2-0 Barry West Steve Davis 2-1 Cliff Thorburn Tony Drago 1-2 Tony Chappel Karl Townsend 1-2 Tony Knowles Alain Robidoux 2-0 Les Dodd Mike Hallett 0-2 Jimmy White Quarter-finals Steve Davis 0-2 Darren Morgan Dene O''Kane 2-1 Jimmy White Alain Robidoux 0-2 Tony Chappel Tony Knowles 0-2 Nigel Bond Semi-finals Nigel Bond 2-0 Darren Morgan Tony Chappel 2-1 Dene O''Kane Final Nigel Bond 2-0 Tony Chappel', '2014-01-01', false, 'Richard Pearson'),
  ('Boring, boring Selby just isn''t fair', 'boring-boring-selby-just-isnt-fair', 'Professional Snooker', '[]'::jsonb, 'That''s the angle many people would have you believe after the world number one retained his title in Furth. Although I respect everyone''s opinion, I can''t go along with this.', null, '"Love him or hate him, he’s going to be around at the top end of our game for plenty of years to come yet."', 'That''s the angle many people would have you believe after the world number one retained his title in Furth. Although I respect everyone''s opinion, I can''t go along with this.

more The real story here, in my opinion, is that one of the sport''s top players rekindled his form, returned to the winner''s circle and sent out a message that he''s back in the race for titles. I believe Leicester''s Mark Selby is somewhat wrongly labelled a negative player on the baize, but he''s not the world number one for no reason. You don''t have to believe Selby is the best player in the world, but the ranking points he''s accumulated over the past two years means he deserves to sit at the top of the tree. Selby''s excellent all-round game is built on excellent safety, patience and knowing exactly when to push the boat out. He doesn''t play kamikaze shots but plays a measured game that allows him to compete with anyone. I don''t think this should be mistaken with negativity. When a chance comes along, he can score as heavily as anyone. In fact, he holds the record for the most number of centuries in a single season and has scored the most hundreds in a single match at the Crucible. He might not be rash, but he most definitely is clinical. That''s why it''s a joy to see him back on form. Selby was back to his solid best in Germany and showed that he''s over the neck injury that has stifled him since the build-up to April''s World Championship. It''s neither easy nor enjoyable playing Selby in a big game. He makes it tough for his opponents and showed why in Germany. He looked back in the zone and back in the mood for the rest of the season. He deserves an extremely big congratulations for defending a very competitive title. It was surely only a matter of time until Selby started playing the kind of snooker we know he''s capable of. He''s a tough match player. He can front run a match and also come from behind. I''m sure he will be in the hunt to win more titles. Love him or hate him, he''s going to be around at the top end of our game for plenty of years to come yet. Selby wasn''t the only star this weekend though. Runner-up Joe Swail showed he''s still got it. After falling off the professional circuit last season, he returned with very little practice to show he can still deliver. Then there were the incredible German fans. They packed out the arena all weekend long and laid bold claim to being the most enthusiastic fans in the world. There''s no way the players can''t enjoy playing in Germany. Article courtesy of OnCue Image Credits: Slider Image 1: Mike Sewell, Slider Image 2: Günter Leitenbauer, Sider Image 3: Monique Limbos, In Article Image: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Bouncing back to take all the frames', 'bouncing-back-to-take-all-the-frames', 'Match Reports', '[]'::jsonb, 'Tregonissey ‘A’ bounced back from last week’s surprise defeat to their ‘B’ team by taking all five frames at Mevagissey ‘A’ – a result which leaves Meva’s title hopes hanging by a thread.', null, 'Mark Sturtridge put Bugle ‘B’ ahead at Mevagissey ‘B’ defeating Matt Chesterfield. The home side then reeled of three on the trot through Ben Rothwell, Matt Rowe and Nathan Shaw with Dave Rundle knocking in a majestic 35 break to get the second away point.', 'Tregonissey ‘A’ bounced back from last week’s surprise defeat to their ‘B’ team by taking all five frames at Mevagissey ‘A’ – a result which leaves Meva’s title hopes hanging by a thread.

more Barrie McIntosh knocked in a 36 break whilst defeating Leighton Varcoe and there were also wins for Jason Cocks, Jason Simmons, Richard Pearson and Ryan Bilson. Big wins for Jake Moore, Andrew Best (61 break) and Ian Ball put Bugle ‘A’ 3-0 up against their ‘B’ team. Dave Rundle pulled one back defeating Paul Sturtridge but Gary Spencer beat Mark Sturtridge in a low-scoring final frame to seal a fine win. Bethel ‘A’ remain third after getting the better of St Blazey winning two blackball frames to help clinch a 4-1 win. Liam Reynolds potted superbly to defeat Leon Collard but wins for Garry Stephens, Matt Green, Geoff Hawken and Andy Peers sealed the victory. Tregonissey ‘B’ followed up last week’s maiden victory with another win this time over Mevagissey ‘B’. Andrew Gooch, Simon Garrington and Phil Hooley put them 3-0 up with Meva replying through Dave Kendall and Matt Rowe, who knocked in a 33. Tony Farrant had a 34 break to help St Neot get the better of Pelynt with a 3-2 win. Matt Vessey and Darren Lock also registered with Len Flower and Phil Ormond replying. Bethel ‘C’ have moved joint top of the Rees League courtesy of a 4-1 win at Lostwithiel. Mark McGurrel took the home point beating Leigh Rosevear on the black, with Roger Smithson, Courtney Crockford, Howard Brett and Ben Stunnell victorious for the visitors. Joint leaders Mevagissey ‘C’ went 2-0 down at home to Bethel ‘D’ as Jason Pascoe and Gavin Dyche got the visitors off to a flier but fortunes turned as Joe and Matt Chesterfield defeating Dave Morshead and Ross McMenemy to level things up, with Adrian Evans defeating Dayle Dyche for victory and keeping their hands on the Runabout Shield. Lerryn went 2-0 up at Tregonissey ‘C’ through Graham Hoskin and Luke Shakespear but the evening turned right around as Alan Meades, Michael Edwards and Cal Stephens sealed Treggy’s second win of the season. St Stephen came down to earth with a bump after last week’s maximum with a 4-1 defeat at Bethel ‘B’. Chris Brown (walkover) claimed their only win as Guy Buckle, Clive Stuthridge, Jim Tamblyn and Richie Bolt sealed the win to move them up to fourth.

FULL RESULTS

Victory League: Mevagissey ‘A’ 0 Tregonissey ‘A’ 5 (J Cocks, J Simmons, R Pearson, B McIntosh (36), R Bilson), Bugle ‘B’ 1 (D Rundle) Bugle ‘A’ 4 (J Moore, A Best (61), I Ball, G Spencer), Pelynt 2 (L Flower, P Ormond) St Neot 3 (D Lock, T Farrant (34), M Vessey), Bethel ‘A’ 4 (G Stephens, G Hawken, M Green, A Peers) St Blazey 1 (L Reynolds), Tregonissey ‘B’ 3 (A Gooch, S Garrington, B Rothwell) Mevagissey ‘B’ 2 (D Kendall, M Rowe (33)). Rees Memorial League: Mevagissey ‘C’ 3 (M Chesterfield, J Chesterfield, A Evans) Bethel ‘D’ 2 (G Dyche, J Pascoe), Lostwithiel 1 (M McGurrell) Bethel ‘C’ 4 (R Smithson, C Crockford, H Brett, B Stunnell), Tregonissey ‘C’ 3 (A Meades, M Edward, C Stephens) Lerryn 2 (G Hoskin, L Shakespear), Bethel ‘B’ 4 (G Buckle, C Stuthridge, J Tamblyn, R Bolt) St Stephen 1 (C Brown). Top breaks of the week: B McIntosh 36, A Best 61, T Farrant 34, M Rowe 33 Home team/player to contact by January 28 and matches to be played by February 12. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Brilliant Ding Is Star Of India', 'brilliant-ding-is-star-of-india', 'Professional Snooker', '[]'::jsonb, 'Ding Junhui won the first ever world ranking event in India with a superb performance to beat home favourite Aditya Mehta 5-0 in the final of the Indian Open.', null, '"Despite Ding''s supremacy, this tournament will be remembered for Mehta''s historic run as never before had an Indian player been beyond the last eight of a ranking event. Inspired by enthusiastic fans in his homeland, he picked the perfect week to produce the best snooker of his life so far."', 'Ding Junhui won the first ever world ranking event in India with a superb performance to beat home favourite Aditya Mehta 5-0 in the final of the Indian Open.

more The incredible run of Mehta was brought to an end as he had no answer to the brilliance of Ding in a one-sided final at the Meridien Hotel in New Delhi. China''s Ding won his eighth world ranking title and second in a row having triumphed at the Shanghai Masters last month. He is the first player to win back-to-back ranking titles in the same season since Ronnie O''Sullivan won the European Open and Irish Masters in 2003. Having also reached the final of the Ruhr Open European Tour event in between those two ranking crowns, Ding is currently showing the most consistent form of his career. The 26-year-old, who received £50,000 plus the £2,000 high break prize for a stunning 142 in his semi-final against Robbie Williams, will be aiming for a hat-trick of ranking titles when he plays in the International Championship in Chengdu later this month. Despite Ding''s supremacy, this tournament will be remembered for Mehta''s historic run as never before had an Indian player been beyond the last eight of a ranking event. Inspired by enthusiastic fans in his homeland, he picked the perfect week to produce the best snooker of his life so far. World Games gold-medallist Mehta, who practises with Ding at the Star Academy in Sheffield, showcased a fine all-round game in winning several dramatic matches, notably against friend and compatriot Pankaj Advani in the quarter-finals. The fairytale finish eluded Mehta but he and Advani are becoming outstanding role models for snooker in India, on and off the table, and at the end of a wonderful week it''s clear that there is potential for the sport to grow in India. Remarkably, this was the second consecutive ranking final featuring two Asian players, following Ding''s defeat of China''s Xiao Guodong in Shanghai, underlining the growing influence of the continent on snooker. Mehta had chances in the opening frame but couldn''t capitalise and Ding took it with well-crafted 52 clearance. After that he shut his opponent out as Mehta scored just two points in the remainder of the match. Ding piled in breaks of 81, 107, 93 and 100 as he cruised through the last four frames before lifting the trophy. "It feels great to be the champion at the first ever ranking tournament in India," said Ding, who beat the likes of John Higgins and Neil Robertson in reaching the final. "Especially to play against Aditya in the final. I''m proud for myself and I''m enjoying this. I''ll rest for the next few days then hope to do well in the next tournament. "I think I am playing the best snooker of my career. I have improved and I''m stronger. I still have a lot of things to learn. "The Indian snooker fans are very good and they understand the game. The arena is good here and never gets sticky. "Aditya has improved so much. He has a very good safety game and he is strong. He''s getting better and better." Mehta said: "I have learned a lot from this tournament and there are a lot of positives. I have reached milestones ever year in my career and this is the greatest so far. My hard work is bearing fruit. I want to keep achieving my goals and make a career out of snooker. "A few years ago I would never have predicted this. My heart has been in the right place and I have put the right amount of work in, and shown myself that nothing is impossible. I am very proud to have represented India in this tournament and for the fact that the event has been successful. "I was mentally drained going into the final because I have had so many close matches which took everything out of me. I was completely gone. I needed a good start because when Ding gets on a roll, no one can stop him. Next time I will be more fit mentally and physically. "I wasn''t surprised by how well Ding played because he does it every day in practice. His cue ball control, potting and safety game, I see it day in and day out. That''s what I aspire to." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Brilliant Fu claims Glasgow glory', 'brilliant-fu-claims-glasgow-glory', 'Professional Snooker', '[]'::jsonb, 'Marco Fu came from 4-1 down to beat John Higgins 9-4 in the final of the Coral Scottish Open in Glasgow.', null, '“It feels unbelievable,” said Fu. “To beat John in Glasgow is one of the biggest wins of my career. It was a great occasion and I managed to play some good match snooker. It’s a dream come true. I was fearing the worst at 3-0 down because the way John was playing was very difficult to contain. I was guessing I was going to be 7-1 down after the first session, I would have even taken 6-2. I was over the moon at 4-4, those three frames I won from 4-1 down were the most important part of the match.', 'Marco Fu came from 4-1 down to beat John Higgins 9-4 in the final of the Coral Scottish Open in Glasgow.

more Higgins had started the match brilliantly with three consecutive centuries, but he was then outplayed by his opponent and denied the chance to capture a title on home turf just a few miles from Wishaw. Instead Hong Kong’s Fu won eight frames in a row to land the third world ranking title of his career and the £70,000 top prize as well as the inaugural Stephen Hendry Trophy, presented by snooker’s most successful ever player. Victory caps off a magnificent week for Fu in which he has played the best snooker of his career. In winning 36 frames in seven matches, the 38-year-old made a remarkable 11 centuries and 21 more breaks over 50. Fu started the current season poorly, failing to get beyond the last 32 of a ranking event until the recent UK Championship, where he reached the semi-finals. He has gone up another gear again this week to win his first ranking title since the 2013 Australian Open. It’s also his second ranking crown in Scotland having won the Grand Prix in Aberdeen in 2007. Fu, who has now won nine of his 15 meetings with Higgins, jumps from 14th in the world to eighth. World number three Higgins missed out on the chance to win a 29th career ranking title, which would have put him ahead of Steve Davis and Ronnie O’Sullivan on the all-time list and just seven behind Hendry’s record of 36. Tied at 4-4 after the first session Fu won the opening frame tonight by building a 58-6 lead then surviving his opponent’s attempts to gain a snooker on the colours. That put Fu ahead for the first time in the match and he gathered momentum with a break of 89 to lead 6-4. Fu looked set to take frame 11 until he missed a short range pot on the last red to a centre pocket. Higgins had the chance to strike a hammer blow by clearing the table, but he lost position on the pink then left a tough thin cut on the black, playing with the rest, in the jaws of a top corner. Fu slotted in the black to go three frames ahead. Higgins had lost six frames in a row at that point, and he had to chance to stop the rot early in the next, but only made 24 before missing a red to a centre pocket. After a safety exchange, Fu rolled in a brilliant pot on a red along the length of the side cushion, setting him up for a run of 59 which proved enough to make it 8-4 at the interval. Fu looked to be cruising over the winning line in frame 14 until he missed a red to a baulk corner on 60. Higgins had one last chance and made 27 before failing to gain position on the last red. When he accidentally knocked the pink in when trying to play safe his hopes were fading, and the handshake came when he left the green over a corner pocket. “It feels unbelievable,” said Fu. “To beat John in Glasgow is one of the biggest wins of my career. It was a great occasion and I managed to play some good match snooker. It’s a dream come true. I was fearing the worst at 3-0 down because the way John was playing was very difficult to contain. I was guessing I was going to be 7-1 down after the first session, I would have even taken 6-2. I was over the moon at 4-4, those three frames I won from 4-1 down were the most important part of the match. “My safety was helping me to get chances and I scored really well throughout the week. Before the UK Championship I worked on a few technical things with my coach Wayne Griffiths. My alignment was way off for potting balls so I had to correct that, as well as my cue action. I spent a lot of time practising but even going to York I wasn’t that confident. I managed to find some form during the UK and I was able to bring that into this tournament. “It has been frustrating in my career to have only won two ranking titles. The way I score could have given me more success but I have always missed out in the semis or final of big tournaments. So it’s nice to win today and remind myself that I can do it under pressure. I’m really confident now going into the second half of the season. I’ll take a holiday now over Christmas then from the new year I’ll be getting ready for the Masters.” Higgins said: “The shot which turned it against me was at 4-2 when there were two reds left and I should have taken the green and tried to move a red off the side cushion. But I played the brown and ended up missing the double on the red. That’s what was in my mind when I went back to my house after the first session. I played the wrong shot and it came back to haunt me. “I still felt good at 4-4 because I couldn’t have played much better. Marco ground his way back into the game and played some good safety. I still fancied playing well tonight but Marco shut me out. I’ve got no complaints because he played superb snooker. He put me in some positions I couldn’t find my way out of. He has been the player of the week and a worthy winner. “The fans were fantastic so I’m just gutted that I couldn’t make it close for them and create a great atmosphere. It would have been good to win a 29th ranking title but hopefully there will be time in the future to do that. I’ve had a great couple of months (winning the China Championship and Champion of Champions) so it will be a good Christmas then I’ll be ready for the Masters.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle and St Blazey drop vital points in top two chase', 'bugle-and-st-blazey-drop-vital-points-in-top-two-chase', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ and St Blazey ‘B’ both dropped points they could ill afford to in pursuit of Mevagissey ‘A’ and Tregonissey ‘A’ who both recorded nap hand wins.', null, 'Bodmin Q-Bar’s 4-1 victory over Lerryn gives them a bit of breathing space in second place. James Stephens took Lerryn’s point but good wins for Malcolm Meneer, his first of the season, Phil Ashton, Steve Bampton and Richie Boly, who remains unbeaten, saw them home.', 'Bugle ‘A’ and St Blazey ‘B’ both dropped points they could ill afford to in pursuit of Mevagissey ‘A’ and Tregonissey ‘A’ who both recorded nap hand wins.

more Meva bounced back to form beating Pelynt. Paul Williams got the ball rolling with a 43 break, while beating Andy Parnell. Pete Chambers, Chris Kendall and Phil Staley all had comfortable victories with Matt Mills beating Len Flower on the black to complete the full house. Martin Powell was the only one who got anywhere near a win but lost to Jason Simmons as Treggy triumphed at Bethel ‘C’. Barrie McIntosh’s 38, Jason Cocks’ 34, Martin Knight and Chris Stephenson all won as they moved into second place, two points behind Meva. Bugle ‘A’ made a good start at Bethel ‘D’ with Andrew Best and Paul Stuthridge gaining win but Jason Pascoe’s excellent victory over Gary Spencer was followed by Ryan Tonkin’s superb 64 break against Ian Ball to level things up but Andy Spearman was well beaten by Ian Powell in the decider. St Blazey ‘B’ dropped a point at home to St Neot with Darren Lock knocking in a fine 55 whilst defeating Graham Taylor. Steve Courts had a 31 break but was blown away by a 58 from Jamie Read. Andrew Gooch was pushed all the way by Anthony Maddams but his victory along with Paul Baron’s and Mike Hancock’s keeps the Blazey boys on the fringe, with games against Meva and Treggy still to come. Bugle ‘B’ suffered a 3-2 home defeat to Bethel ‘A’. Matt Green’s good form continued beating Keith Moore. Dave Rundle and Mark Stuthridge put the home side ahead only for Leon Collard and super-sub Bob Stephens to seal it for the visitors. Bodmin Q-Bar’s 4-1 victory over Lerryn gives them a bit of breathing space in second place. James Stephens took Lerryn’s point but good wins for Malcolm Meneer, his first of the season, Phil Ashton, Steve Bampton and Richie Boly, who remains unbeaten, saw them home. St Stephen ‘A’ slipped to a surprise defeat at Tregonissey ‘B’ to damage their promotion hopes. Anthony Harrison and Cary Clarke traded frames with Phil Hooley and Gary Wherry, which left Ryan Thomas to inflict a first defeat of the season on Dan Allen to seal the home side’s win. Dave Morshead gave Bethel ‘B’ a good start at Mevagissey beating Joe Chesterfield but wins for Ben Prynn, Matt Chesterfield and James Prynn put Meva 3-1 up. Only for Guy Buckle to overcome the Predator Tregale for Bethel’s second point. St Stephen ‘B’ raced into a 2-0 lead over Mevagissey ‘D’ courtesy of Craig Nicholls and Jim Doherty but the visitors fought back to win with victories for George Lory, Rich Lakeman and Rob Blamey.

FULL RESULTS

Victory League: Bethel ‘D’ 2 (Jason Pascoe, Ryan Tonkin (64) Bugle ‘A’ 3 (Andrew Best, Paul Stuthridge, Ian Powell), Bethel ‘C’ 0 Tregonissey ‘A’ 5 (Barrie McIntosh (38), Jason Cocks (34), Martin Knight, Jason Simmons, Chris Stephenson), Pelynt 0 Mevagissey ‘A’ 5 (Paul Williams, Pete Chambers, Chris Kendall, Phil Staley, Matt Mills), Bugle ‘B’ 2 (Dave Rundle, Mark Sturtridge) Bethel ‘A’ 3 (Matt Green, Leon Collard, Bob Stephens), St Blazey ‘B’ 4 (Andrew Gooch, Jamie Read (58), Paul Baron, Mike Hancock) St Neot 1 (Darren Lock (55). Rees Memorial League: Tregonissey ‘B’ 3 (Phil Hooley, Gary Wherry, Ryan Thomas) St Stephen ‘A’ 2 (Anthony Harrison, Cary Clarke) Mevagissey ‘C’ 3 (Ben Prynn, Matt Chesterfield, James Prynn) Bethel ‘B’ 2 (Dave Morshead, Guy Buckle), Bodmin Q-Bar 4 (Malcolm Meneer, Richard Bolt, Philip Ashton, Steve Bampton) Lerryn 1 (James Stephens), St Stephen ‘B’ 2 (Craig Nicholls, Josh Doherty) Mevagissey ‘D’ 3 (George Lory, Richard Lakeman, Rob Blamey). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: B McIntosh 38, J Cocks 34, R Tonkin 64, J Read 58, P Williams 43, D Lock 55, S Courts 31 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle back in title race after whitewash win', 'bugle-back-in-title-race-after-whitewash-win', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ produced a great win at Meva ‘B’ with all five frames to hopefully reignite their title challenge with leaders Tregonissey ‘A’ dropping two points at Pelynt.', null, 'Mevagissey ‘A’ travelled home from St Neot with a 3-2 win. Chris Kendall travelled from Plymouth to win his frame with Phil Staley and Paul Williams also victorious. Anthony Maddams and Darren Lock, who knocked in a 33 replied for the home side.', 'Bugle ‘A’ produced a great win at Meva ‘B’ with all five frames to hopefully reignite their title challenge with leaders Tregonissey ‘A’ dropping two points at Pelynt.

more They did all they had to do to keep their season alive. Andy Best started the ball rolling followed by wins for Gary Spencer, Ian Ball, Ian Powell, on his first appearance of the season, and Paul Sturtridge completed the nap hand. At Pelynt Andy Parnell took out Martin Knight to get the home side off the mark but Matt Woodward and Ryan Bilson responded. Barrie McIntosh hit a 32 break in the next but lost to Phil Ormand with Jason Cocks taking the loss for the visitors. Second-placed Bethel ‘A’ toiled all night to record a 3-2 home win over St Blazey ‘A’. Nick Kendall slaughtered Geoff Hawken in the opener, followed by Liam Reynolds’ convincing win over Andy Peers. Garry Stephens responded with a fine 32 break to start the comeback with Matt Green levelling things after beating Mark Craddock leaving Leon Collard beating Mark’s son Aiden in the decider to claim the win. Mevagissey ‘A’ travelled home from St Neot with a 3-2 win. Chris Kendall travelled from Plymouth to win his frame with Phil Staley and Paul Williams also victorious. Anthony Maddams and Darren Lock, who knocked in a 33 replied for the home side. At the bottom Bugle ‘B’ really improved their chances of staying up by beating St Stephen ‘A’ 4-1. Tony Conroy, Dave Rundle, Mark Sturtridge who hit a fine 31 break and captain Keith Moore took their frames with Anthony Garside responding for the bottom side. Darren Biggens’ 30 break helped him to beat George Lory to give St Stephen ‘B’ their only point at home to Mevagissey ‘D’ which keeps Meva right in the promotion frame Rich Lakeman, Phil Ashton, Scott Mills and Rob Blamey replied leaving them only a point behind leaders Tregonissey ‘B’. Tregonissey remain top after defeating Gorran 4-1. Phil and Justin Hooley put them 2-0 up but Paul Grimmett beat Adam Tuck to peg them back only for Richard Opie and Mike Hooley to get the last two frames. Bethel ‘B’ remain in third after going to Lerryn and coming home with a 4-1 victory. Charles McMiram took out Martin Isted to give the home side a good start but Bethel responded with wins for Jim Tamblyn, Guy Buckle, Clive Stuthridge and Rich Bolt. Bethel ‘D’ fell behind at home to Tregonissey ‘C’ when Stacey Hancock beat Andy Spearman and could of gone further behind but for Dave Morshead’s black ball win over Michaela Edwards and Jason Pascoe coming from behind to pip Amanda Fleming with further victories for Ross McMenemy and Ryan Tonkin giving them a 4-1 win.

FULL RESULTS

Victory League: Mevagissey ‘B’ 0 Bugle ‘A’ 5 (A Best, G Spencer, I Ball, I Powell, P Sturtridge), Bethel ‘A’ 3 (G Stephens (32), M Green, L Collard) St Blazey ‘A’ 2 (L Reynolds, N Kendall), St Neot 2 (A Maddams, D Lock (33) Mevagissey ‘A’ 3 (C Kendall, P Staley, P Williams), Pelynt 2 (A Parnell, P Ormand) Tregonissey ‘A’ 3 (M Woodward, R Bilson, J Cocks), Bugle ‘B’ 4 (T Conroy, D Rundle, M Sturtridge (31), K Moore) St Stephen ‘A’ 1 (A Garside). Rees Memorial League: Tregonissey ‘B’ 4 (P Hooley, J Hooley, R Opie, M Hooley) Gorran 1 (P Grimmett), St Stephen ‘B’ 1 (D Biggen (30) Mevagissey ‘D’ 4 (R Lakeman, P Ashton, S Mills, R Blamey), Bethel ‘D’ 4 (J Pascoe, R McMenemy, D Morshead, R Tonkin) Tregonissey ‘C’ 1 (S Hancock), Lerryn 1 (C McMiram) Bethel ‘B’ 4 (J Tamblyn, G Buckle, C Stuthridge, R Bolt). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: G Stephens 32, D Lock 33, M Sturtridge 31, B McIntosh 32, D Biggens 30 The draw for the next round of all the competitions was made by Matt Rowe and Mark Gregory at Mevagissey Social Club. Seniors: Philip Ormand v Geoff Hawken, Leon Collard v Len Flower. Singles: Barrie McIntosh v Steve Courts, Ryan Bilson v James Popplewell, Gary Stephens v Andrew Best, Darren Lock v Andy Peers. Bill Toms: Barrie McIntosh v Adrian Bowyer, Darren Lock v Ryan Bilson, Jason Simmons v Andrew Best, Jason Cocks v Philip Hooley. Willie Thomas: Philip Hooley v Jim Tamblyn, Stacey Hancock v Leigh Rosevear, Clive Stuthridge v Justin Hooley, Courtney Crockford v George Lory. Doubles: J Popplewell and P Staley v M Knight and M Woodward, M Green and C Stuthridge v S Courts and D Lock, A Best and G Spencer v G Hawken and A Peers, G Stephens and R Opie v J Cocks and J Simmons. Team Pairs: Bugle ‘B’ v Bugle ‘A’, Bethel ‘A’ v Tregonissey ‘A’. To be played on Tuesday, February 7. Team Handicap: St Blazey ‘A’ v Bethel ‘C’ to be played on Tuesday, February 7, Bugle ‘B’ v Bethel ‘A’ date TBA. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle back on top', 'bugle-back-on-top', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ have opened up a two-point lead at the top of the league after beating Bethel ‘A’ 4-1 with Gary Spencer’s 39-break seeing off Geoff Hawken on a respotted black with Bob Stephens’ victory getting Bethel’s point.', null, '"In the Rees League, Tywardreath ‘B’ moved into second place when beating Bugle ‘C’ who could get no Moore, Jake and Keith that is, than two points."', 'Bugle ‘A’ have opened up a two-point lead at the top of the league after beating Bethel ‘A’ 4-1 with Gary Spencer’s 39-break seeing off Geoff Hawken on a respotted black with Bob Stephens’ victory getting Bethel’s point.

more Darren Lock’s 36 was pivotal in Lostwithiel ‘A’s victory at Sparks and St Neot remain unbeaten after seeing off Tywardreath 3-2. Tregonissey bounced back from last week’s setback by beating Mevagissey ‘A’ 4-1 with the dependable Leighton Varcoe seeing off Richard Pearson for the home side. The league is really split in two halves, with five teams on 11 points at the bottom. In the Rees League, Tywardreath ‘B’ moved into second place when beating Bugle ‘C’ who could get no Moore, Jake and Keith that is, than two points. Tyrone Stephens’ 40-break for a now-settled Bethel ‘D’ helped them to a 4-1 win over Lerryn and they will now be looking to close the gap and challenge the leaders St Blazey, who won 4-1 at Gorran Haven, Lee McKinstrey registering the home side’s point.

FULL RESULTS

Victory League: Mevagissey ‘A’ 1 (L Varcoe) Tregonissey 4 (C Kendall, R Bilson, M Fox, B McIntosh); Bugle ‘A’ 4 (G Spencer (39), A Peers, I Powell, P Stutridge) Bethel ‘A’ 1 (B Stephens); Lostwithiel ‘B’ 3 (J Daniell, G Lory, A Parnell) Mevagissey ‘B’ 2 (D Kendall, M Rowe); Sparks 2 (C Stuthridge, S Bampton) Lostwithiel ‘A’ 3(D Grose, C Dickinson, D Lock (36)); St Neot 3 (M Courts, M Rowe, S Courts) Tywardreath ‘A’ 2 (L Sturtridge, P Baron). Rees Memorial League: Mevagissey ‘D’ 3 (R Blamey, N Parker, J Prynn) Bethel ‘C’ 2 (J Cocks, C Crockford); Gorran Haven 1 (L McKinstrey) St Blazey 4 (L Roseveare, L Reynolds, S Dewings, M Woodward); Tywardreath ‘B’ 3 (K Wilkes, P Hunt, A Dennis) Bugle ‘C’ 2 (J Moore, K Moore); Bethel ‘D; 4 (T Stephen (40), J Pascoe, A Spearman, R Tonkin) Lerryn 1 (G Brimicombe). Top breaks of the week: Tyrone Stephens 40, Gary Spencer 39 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle closing in on title', 'bugle-closing-in-on-title', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ go into next week''s home match against St Neot needing four frames to clinch the title with last week’s results seeing both Tywardreath ‘A’ and Tregonissey dropping points.', null, '"Bugle ‘A’s 4-1 win at Bodmin Sparks leaves them in pole position to reclaim the champions title, Sparks’ point coming from Clive Stutridge over the luckless Andy Peers. "', 'Bugle ‘A’ go into next week''s home match against St Neot needing four frames to clinch the title with last week’s results seeing both Tywardreath ‘A’ and Tregonissey dropping points.

more Matt Mills’ two breaks of 39 and 40 saw off Mike Hancock and with Mark Gregory defeating Andrew Gooch the Legion boys only came away with a 3-2 victory at basement boys Mevagissey ‘B’ and with Treggy dropping two points at Bugle ‘B’ courtesy of Ian Ball and Dave Rundle. Bugle ‘A’s 4-1 win at Bodmin Sparks leaves them in pole position to reclaim the champions title, Sparks’ point coming from Clive Stutridge over the luckless Andy Peers. St Neot cemented fourth place when defeating Lostwithiel ‘B’ 4-1 with Jason Hill on target for the away side who face a relegation shoot-out on the final week of the season when they go to Sparks with the losers likely to be relegated. Bethel ‘A’s recent poor run continued as they were unlocked at Lostwithiel ‘A’ 4-1 with only reserve Matt Green registering a frame. With St Blazey and Bethel ‘D’ both having a bye, Mevagissey ‘C’ jumped into joint third place after a 4-1 home win over Lerryn, league stalwart Graham Hoskin saving the whitewash. Bugle ‘C’s challenge faltered at home to Bethel ‘C’ as only Jake Moore and Andy Fooks posted victories and with a tough fixture at St Blazey left a top three spot looks unlikely. Bethel ‘B’ saw off the determined challenge of Gorran Haven 3-2 with Rob Bunney and the predatory Lee McKinstry recording another victory in the first season whilst Tywardreath ‘B’ bounced back from their recent poor run when seeing off Mevagissey ‘D’ with Neil Rowe’s 35 and a majestic performance from old timer John Wilson the highlights of the evening.

FULL RESULTS

Victory League: Sparks 1 (C Stuthridge) Bugle ‘A’ 4 (I Powell, G Spencer, A Best (33), P Sturtridge) St Neot 4 (A Tamblyn, S Courts, M Rowe, A Courts) Lostwithiel ‘B’ 1 (J Hill), Mevagissey ‘B’ 2 (M Gregory, M Mills (39+40)) Tywardreath ‘A’ 3 (P Baron, L Sturtridge, D Kirwan), Bugle ‘B’ 2 (I Ball, D Rundle) Tregonissey 3 (B McIntosh (33), R Pearson, R Bilson), Lostwithiel ‘A’ 4 (C Dickenson, C Perring, D Lock, A Maddams) Bethel ‘A’ 1 (M Green). Rees Memorial League: Tywardreath ‘B’ 4 (J Wilson, G Kent, N Rowe (35), K Wilks) Mevagissey ‘D’ 1 (R Blamey), Bethel ‘B’ 3 (S Hicks, G Buckle, M Green) Gorran Haven 2 (R Bunney, L McKinstry), Mevagissey ‘C’ 4 (B Prynn, M Chesterfield, N Shaw, D Tregale) Lerryn 1 (G Hoskin), Bugle ‘C’ 2 (A Fooks, J Moore) Bethel ‘C’ 3 (C Crockford, S Jones, J Cocks). Top breaks of the week: Matt Mills, 40, 39, Andrew Best 33, Barrie McIntosh 33, N Rowe, 35 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle end Bethel''s title hopes', 'bugle-end-bethels-title-hopes', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ got four home points with every frame being close to virtually put Bethel ‘A’ out of the title race.', null, 'Bethel ‘D’ moved into third place after defeating Tregonissey ‘C’. Stacey Hancock beat Dayle Dyche and Carol Stephens pushed Jason Pascoe all the way but lost out with Dave Morshead, Gavin Dyche and Ross McMenemy securing the home win.', 'Bugle ‘A’ got four home points with every frame being close to virtually put Bethel ‘A’ out of the title race.

more Gary Spencer took blue and pink to end Andy Peers chances with Andrew Best recovering from being 42 points down to Geoff Hawken to clear the colours for a 27 to sneak it. Jake Moore and Paul Sturtridge both just managed to win against Leon Collard and Garry Stephens, with Matt Green getting the away point, beating Ian Ball. Mevagissey ‘A’ defeated their ‘D’ team 3-2 to stay fourth. Rich Lakeman and Mark Ashton got two welcome points as the ‘D’ team look to climb the table with Phil Staley, James Popplewell and Paul Williams winning for the ‘A’ side. St Neot had a good 4-1 home win over Tregonissey ‘B’ with victories for Steve Courts, Darren Lock, Matt Vessey and Chris Perring. Andrew Gooch got the away point, defeating Anthony Maddams. Mevagissey ‘B’ got two points at Pelynt as the battle at the bottom intensifies. Richard Broad and Dave Chivers, who knocked in a 30 break put the home side 2-0 up, with Mark Gregory and Matty Rowe levelling up with Phil Ormond beating Dave Kendall in the decider. St Blazey put in a solid performance as they beat Bugle ‘B’ 4-1. Nick Kendall’s 40 and Chris Morford’s 31 got two frames under their belt along with wins for D Willis and Stewart Dewings with Colin Rundle taking the decider against Liam Reynolds. Mevagissey ‘C’ took full advantage of Bethel ‘C’s night off to record a fine 5-0 win at home to Lerryn. Matt Chesterfield, Ben Prynn, Adrian Evans and ‘The Predator’ Tregale all had comfortable wins with John Hancock unlucky to lose out to Joe Chesterfield. Bethel ‘D’ moved into third place after defeating Tregonissey ‘C’. Stacey Hancock beat Dayle Dyche and Carol Stephens pushed Jason Pascoe all the way but lost out with Dave Morshead, Gavin Dyche and Ross McMenemy securing the home win. Bugle ‘C’ and Lostwithiel played on Thursday with a 3-2 home win. Darren Biggen got the away side off to a good start beating Phil Johns, but Bugle went 3-1 up thanks to Nigel Couchman, Damian Knight and Roy Bayliss with Craig Nicholls seeing off Kevin Spencer for the away team’s second point.

FULL RESULTS

Victory League: Mevagissey ‘A’ 3 (P Staley, J Popplwell, P Williams) Mevagissey ‘D’ 2 (R Lakeman, M Ashton), Bugle ‘A’ 4 (G Spencer, A Best, J Moore, P Sturthridge) Bethel ‘A’ 1 (M Green), Pelynt 3 (R Broad, D Chivers (30), P Ormond) Mevagissey ‘B’ 2 (M Gregory, M Rowe), St Blazey 4 (N Kendall (40), D Willis, S Dewings, C Morford (31)) Bugle ‘B’ 1 (C Rundle), St Neot 4 (S Courts, D Lock, M Vessey, C Perring) Tregonissey ‘B’ 1 (A Gooch). Rees Memorial League: Bugle ‘C’ 3 (N Couchman, D Knight, R Bayliss) Lostwithiel 2 (D Biggen, C Nicholls), Mevagissey ‘C’ 5 (M Chesterfield, B Prynn, A Evans, J Chesterfield, D Tregale) Lerryn 0, Bethel ‘D’ 4 (D Morshead, J Pascoe, R McMenemy, G Dyche) Tregonissey ‘C’ 1 (S Hancock). Top breaks of the week: C Morford 31 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle fightback to clinch title', 'bugle-fightback-to-clinch-title', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ clinched the St Blazey and District Snooker League title the hard way, coming from 2-0 down to beat St Neot, with their three points enough as Tywardreath ‘A’ dropped two to Lostwithiel ‘A’.', null, '"Tregonissey’s nap hand at home to relegated Mevagissey ‘B’ saw them jump into second place with only one game left Barry McIntosh’s 40 and 33 again to the fore. "', 'Bugle ‘A’ clinched the St Blazey and District Snooker League title the hard way, coming from 2-0 down to beat St Neot, with their three points enough as Tywardreath ‘A’ dropped two to Lostwithiel ‘A’.

more Aaron Courts’ 35 and Dad Steven’s 39 sent texts all around the area but messers Stirfry Besty and Spencer pulled Bugle through. The Legion boys started well as Kirwan and Baron won but stiff resistance from Broad and Maddams pegged them back leaving the league title out of reach again. Tregonissey’s nap hand at home to relegated Mevagissey ‘B’ saw them jump into second place with only one game left Barry McIntosh’s 40 and 33 again to the fore. Leon Collard’s fine 33 break clinched a welcome 3-2 win for Bethel ‘A’ over Bugle ‘B’ and Sparks and Lostwithiel ‘B’ went into last night’s game only one point apart in the big relegation fight out after Sparks picked up two valuable points at Mevagissey ‘A’. Bethel ‘D’ clinched promotion into the top flight after seeing off Gorran Haven, Rich Allen, Andy Spearman and Jason Pascoe their marksmen while Bethel ‘C’ completed their season with a good 3-2 win over Mevagissey ‘C’ with captain Roger Smithson excelling in the final frame. Champions St Blazey battled hard for a 3-2 victory over Bugle ‘C’ with Jake and Keith Moore triumphant for the away side and finally Bethel ‘B’s season ended with a 5-0 walkover over Mevagissey ‘D’ who were unable to raise a side.

FULL RESULTS

Victory League: Mevagissey ‘A’ 3 (M Towsey, P Staley, M Fox) Sparks 2 (S Bampton, R Bolt), Bugle ‘A’ 3 (P Sturtridge, A Best, G Spencer) St Neot 2 (A Courts (35), S Courts (39)), Tregonissey 5 (B McIntosh (40+33), C Stephenson, R Bilson, R Pearson, C Kendall) Mevagissey ‘B’ 0, Bethel ‘A’ 3 (B Stephens, G Hawken, L Collard (33)) Bugle ‘B’ 2 (G Taylor, I Ball), Tywardreath ‘A’ 3 (D Kirwan, P Baron, M Hancock) Lostwithiel ‘A’ 2 (R Broad, A Maddams). Rees Memorial League: Gorran Haven 2 (L McKinstry, R Holmes) Bethel ‘D’ 3 (R Allen, A Spearman, J Pascoe), Bethel ‘C’ 3 (H Brett, J Cocks, R Smithson) Mevagissey ‘C’ 2 (J Chesterfield, N Shaw), St Blazey 3 (M Woodward, C Brown, M Mears) Bugle ‘C’ 2 (K Moore, J Moore). Bethel ‘B w/o Mevagissey ‘D’. Top breaks of the week: Aaron Courts 35, Steve Courts 39, Barry McIntosh 40, 33, Leon Collard 33. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle flying high in Victory League', 'bugle-flying-high-in-victory-league', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ trounced St Neot 5-0 to extend their lead at the top of the St Blazey and District Snooker League to six points.', null, '"Dave Rundle meanwhile had a 55 and Ian Ball’s 54 inspiring Bugle ‘B’ to a good win over in-form Bugle ‘A’."', 'Bugle ‘A’ trounced St Neot 5-0 to extend their lead at the top of the St Blazey and District Snooker League to six points.

more They have now taken 23 out of the last 25 available points, which is tremendous form by anyone’s standards. Paul Sturtridge claiming a vital win over Martin Rowe, despite his opponent’s 31 break. Tregonissey’s Chris Kendall had a 40-break in his side’s 4-1 win at Mevagissey ‘B’ whose Ben Rothwell was the only winner. Tywardreath ‘A’ remain second after a close 3-2 away win at Lostwithiel ‘A’, Darren Lock winning a respotted black over Mike Hancock to claim the home side’s second point. Mevagissey ‘A’ returned to winning ways, as they were comfortable 4-1 winners at Sparks with Mike Bolt saving the whitewash with a great win over Matt Fox. Dave Rundle meanwhile had a 55 and Ian Ball’s 54 inspiring Bugle ‘B’ to a good win over in-form Bethel ‘A’. In the Rees League table topping St Blazey went to Bugle ‘C’ and came away with a 3-2 win with Jake Moore and Nigel Couchman, who had a 32, were Bugle’s marksmen. Bethel ‘B’ returned to form after last week’s surprise defeat at Gorran to beat Mevagissey ‘D’ 4-1, with Rob Blamey continuing his good run beating Mike Sweet for his side’s only point. Mevagissey ‘C’ and Bethel ‘C’ had some very tight frames with the away side completing their first half programme, claiming a 3-2 win to climb to third place in the table. Bethel ‘D’ meanwhile jumped up a couple places after overcoming Gorran Haven 4-1, Lee McKinstry preventing the whitewash.

FULL RESULTS

Victory League: Sparks 1 (M Bolt) Mevagissey ‘A’ 4 (M Towsey, L Varcoe, R Lakeman, P Staley); St Neot 0 Bugle ‘A’ 5 (A Peers, P Sturtridge, A Best, I Powell, G Spencer); Mevagissey ‘B’ 1 (B Rothwell) Tregonissey 4 (C Kendall (40), B McIntosh, R Bison, R Pearson); Bugle ‘B’ 3 (I Ball (32), G Taylor, D Rundle (55)) Bethel ‘A’ 2 (L Collard, G Hawken); Lostwithiel ‘A’ 2 (D Lock, R Broad) Tywardreath ‘A’ 3 (P Baron, L Sturtridge, A Gooch). Rees Memorial League: Bethel ‘B’ 4 (G Buckle, M Green, B Stunnell, S Hicks) Mevagissey ‘D’ 1 (R Blamey); Bethel ‘D’ 4 (J Pascoe, A Spearman, V Hathway, R Tonkin) Gorran Haven 1 (L McKinstry); Mevagissey ‘C’ 2 (M Chesterfield, N Shaw) Bethel ‘C’ 3 (R Smithson, J Cocks, C Crockford); Bugle ‘C’ 2 (J Moore,N Couchman (32)) St Blazey 3 (M Meares, M Woodward, L Reynolds). Top breaks of the week: Dave Rundle 55, Ian Ball 54, Martin Rowe 31, Chris Kendall 40, Nigel Couchman 32 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle move a step closer to the title', 'bugle-move-a-step-closer-to-the-title', 'Match Reports', '[]'::jsonb, 'Defending champions Bugle ‘A’ took a major step towards winning this year''s title by defeating nearest rivals St Blazey ‘B’ 4-1 in a night of high-quality snooker.', null, '"In the Rees League, leaders Mevagissey ‘B’ took a major step towards promotion as they saw off their own C side 4-1 – Joe Chesterfield''s victory over Nathan Shaw the only bright spot for the underdogs."', 'Defending champions Bugle ‘A’ took a major step towards winning this year''s title by defeating nearest rivals St Blazey ‘B’ 4-1 in a night of high-quality snooker.

more Breaks of 32 by Gary Spencer, 30 by Ian Powell, and 35 by Andrew Best - although he was edged out by Mike Hancock – saw Bugle edge closer to the title, although St Blazey still have a game in hand. St Neot travelled to Bethel ‘A’ and came away with a deserved 4-1 win as only Gary Stephens produced the goods for the home side - Steve Courts with an excellent 46 and Tony Farrant with a 36 the highlights for the visitors. Tregonissey consolidated their third-place spot while thumping Mevagissey ‘A’ 5-0, with Barry McIntosh’s 31 and 39 against Leighton Varcoe sealing all the points. Bugle ‘B’ trounced Lostwithiel 5-0, a result which pushes John Daniell’s boys closer to relegation - Arsene Moore saw off John on a respot in the first frame, but Bugle ran away with the other frames for a deserved win. Bethel ‘D’ are hanging on in the top division by the skin of their teeth after a 4-1 defeat at St Blazey ‘A’, with Ryan Tonkin again showing good form to overturn Leigh Rosevear. In the Rees League, leaders Mevagissey ‘B’ took a major step towards promotion as they saw off their own C side 4-1 – Joe Chesterfield''s victory over Nathan Shaw the only bright spot for the underdogs. Stacey Hancock produced her frame of the season, defeating Matt Green as St Stephen went home from Bethel ‘B’ with a 4-1 win, with only Mike Sweet on target for the Fat Boys. Mevagissey ‘D’ were only stopped by Terry Middleton when beating Lerryn 4-1. Some very tight frames on the night generally went Meva''s way, as they strive for a strong end to the season. Gorran Haven picked up two useful points at Bodmin Sparks, courtesy of Rob Bunney and Lee McKinstry, but Mike Bolt, Mike Williams and Clive Stuthridge scored for the Sparkies, securing them the victory. In a rescheduled match on Thursday night, Bugle ‘C’ returned home from Gorran with a 3-2 victory.

FULL RESULTS

Victory League: St Blazey ‘A’ 4 (M Woodward (31), C Brown, L Reynolds, S Dewings) Bethel ‘D’ 1 (R Tonkin), Lostwithiel ‘B’ 0 Bugle ‘B’ 5 (K Moore, J Moore, D Rundle, I Ball, M Sturtridge), Tregonissey 5 (R Bilson, R Pearson, J Cocks, C Stephenson, B McIntosh (31+39) Mevagissey ‘A’ 0, Bugle ‘A’ 4 (P Sturtridge, G Spencer (32), I Conroy, I Powell (30); A Best lost (35) St Blazey ‘B’ 1 (M Hancock), Bethel ‘A’ 1 (G Stephens) St Neot 4 (I Wilton, T Farrant (36), A Courts, S Courts (46). Rees Memorial League: Mevagissey ‘D’ 4 (R Blamey, J Tomlinson, S Mills, R Lakeman) Lerryn 1 (T Middleton), Mevagissey ‘B’ 4 (N Shaw, M Gregory, B Rothwell, D Kendall) Mevagissey ‘C’ 1 (J Chesterfield), Sparks 3 (M Bolt, M Williams, C Stuthridge) Gorran Haven 2 (R Bunney, L McKinstry), Bethel ‘B’ 1 (M Sweet) St Stephen 4 (C Clark, A Harrison, A Garside, S Hancock), Gorran Haven 2 Bugle ‘C’ 3. Top breaks of the week: M Woodward 31, B McIntosh 31, 39, G Spencer 32, A Best 35, T Farrant 36, S Courts 46 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle off to a flier with 5-0 whitewash', 'bugle-off-to-a-flier-with-5-0-whitewash', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ played their first match of the season and saw off clubmates Bugle ‘B’ 5-0.', null, 'Mevagissey ‘B’ beat St Neots 3-2 for an excellent win with Ben Rothwell’s victory over Steve Courts pivotal. Dave Kendall and Mark Gregory also won with Andy Ridgement and Darren Lock replying.', 'Bugle ‘A’ played their first match of the season and saw off clubmates Bugle ‘B’ 5-0.

more Paul Sturtridge, Gary Spencer and Ian Ball put them 3-0 up with Jake beating Keith in the battle of the Moores and Andrew Best sealed the nap hand beating Mark Sturtridge. Tregonissey ‘A’ no longer hold the Runabout Shield after a 4-1 home defeat to Bethel ‘A’. Garry Stephens (Matt Woodward) and Matt Green (Martin Knight) put Bethel two clear and Andy Peers’ fluked pink saw off Ryan Bilson, who had battled back from 46 points behind to give himself a chance. Barrie McIntosh got Treggy’s point beating Leon Collard with Geoff Hawken sneaking past Jason Cocks in the final frame. St Blazey ‘B’ got off the mark with a full house against Pelynt. Mickey Meares and Mike Hancock both got 31 breaks but Graham Taylor got the better of Phil Ormond by one point on the black with Paul Baron and Ryan Tonkin competing the points total. Mevagissey ‘B’ beat St Neots 3-2 for an excellent win with Ben Rothwell’s victory over Steve Courts pivotal. Dave Kendall and Mark Gregory also won with Andy Ridgement and Darren Lock replying. James Popperwell knocked in a 39 break as Mevagissey ‘A’ beat St Stephen ‘A’ 4-1. Dan Allen got the better of Matt Mills for the home point with Leighton Varcoe, Chris Kendall and Paul Chambers also winning for the Seasiders. The big game in the Rees League saw Bethel ‘B’ beat Meva ‘D’ 3-2. Ian Latham beat Martin Isted in the last with both of these teams surely fancying their chances of promotion. Bethel ‘C’ are also fancied to do well and came home from Gorran with a 4-1 win as Leigh Rosevear’s debut ended in defeat to Lee McKinstry, who claimed the home side’s only point. Treggy ‘B’ got top after beating their ‘C’ team 5-0 but it was harsh on the girls who were well in three frames on the night when luck deserted them. Meva ‘C’ also are capable of beating anyone and it was only Darren Biggin who stopped the full hand over St Stephen ‘B’. It has been an interesting start to both leagues and there will be a lot of twists and turns. Snooker League shirts priced at £12.95 each are available at St Austell Trophies with your club name on, check it out.

FULL RESULTS

Victory League: Bugle ‘A’ 5 (P Sturtridge, G Spencer, I Ball, J Moore, A Best) Bugle ‘B’ 0, St Stephen ‘A’ 1 (D Allen) Mevagissey ‘A’ 4 (L Varcoe, C Kendall, J Popperwell (39), P Chambers), Tregonissey ‘A’ 1 (B McIntosh (32)) Bethel ‘A’ 4 (G Stephens, A Peers, M Green, G Hawken), Pelynt 0 St Blazey ‘B’ 5 (R Tonkin, M Meares (31), P Baron, G Taylor, M Hancock (31), Mevagissey ‘B’ 3 (D Kendall, B Rothwell, M Gregory) St Neot 2 (A Ridgement, D Lock). Rees Memorial League: Gorran 1 (L McKinstry) Bethel ‘C’ 4 (H Brett, R Smithson, B Stunnell, C Crockford), Bethel ‘B’ 3 (R Bolt, G Buckle, C Stuthridge) Mevagissey ‘D’ 2 (R Lakeman, I Latham), Tregonissey ‘C’ 0 Tregonissey ‘B’ 5 (C Robins, P Hooley, J Hooley, M Hooley, R Thomas), Mevagissey ‘C’ 4 (D Tregale, J Chesterfield, C Prynn, B Prynn) St Stephen ‘B’ 1 (D Biggin). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: M Hancock 31, J Popperwell 39 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle rise to the summit', 'bugle-rise-to-the-summit', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ jumped to equal top of the St Blazey and District Snooker League Victory League following their 5-0 whitewash of Lostwithiel ‘B’.', null, '"Mevagissey ‘B’ head the Rees League following a 4-1 home win over Gorran Haven – Lee McKinstry in fine form for the away side."', 'Bugle ‘A’ jumped to equal top of the St Blazey and District Snooker League Victory League following their 5-0 whitewash of Lostwithiel ‘B’.

more As despite breaks of 39 by Mike Hancock and 31 by Graham Taylor St Blazey ‘B’ dropped two points to their ‘A’ side as Matt Woodward and Chris Brown netted frames. Tregonissey picked up three points at home to Bethel ‘A’ as Barrie Mac’s 47 and 39 breaks saw off Leon Collard but Bob Stephens and Geoff Hawken secured two valuable points for the away side. Jake Moore and Ian Ball picked up goof wins as Bugle ‘B’ lost 3-2 at Lostwithiel ‘A’ and Bethel ‘D’ will rue missed chances to pick up their first win of the season as they lost by the odd frame at home to St Neot. Mevagissey ‘B’ head the Rees League following a 4-1 home win over Gorran Haven – Lee McKinstry in fine form for the away side. Five teams are locked on eight points in what is looking to be really tight league. Bugle ‘C’ despatched Mevagissey ‘D’ 5-0 and are right in the mix. Bodmin Sparks jumped into a 3-0 lead at home to Bethel ‘B’ but Guy Buckle and Matt Green put some respectability into the score. Lerryn produced a great performance to come away from Mevagissey ‘C’ with a 3-2 victory – Dave Phipps, Gordon Brimincombe and Graham Hoskin the victors. And newcomers St Stephen continue to impress as Stacey Hancock, Anthony Harrison and Gary Clark secured the victory at Bethel ‘C’.

FULL RESULTS

Victory League: Bethel ‘D’ 2 (R Allen, A Spearman) St Neot 3 (M Courts, I Hancocks, S Courts), Bugle ‘A’ 5 (P Sturtridge, G Spencer, I Powell, A Best, A Peers) Lostwithiel ‘B’ 0, Lostwithiel ‘A’ 3 (D Lock, C Perring, D Courts) Bugle ‘B’ 2 (J Moore, I Ball), St Blazey ‘A’ 2 (M Woodward, C Brown) St Blazey ‘B’ 3 (M Hancock (39), G Taylor (31), A Gooch), Tregonissey 3 (R Bilson, M McIntosh (47 + 39), J Cocks) Bethel ‘A’ 2 (B Stephens, G Hawken). Rees Memorial League: Bugle ‘C’ 5 (M Pascoe, J Conroy, N Couchman, S Wingrave, K Spencer) Mevagissey ‘D’ 0, Mevagissey ‘B’ 4 (B Rothwell, N Shaw, M Gregory, P Kendall) Gorran Haven 1 (L McKinstry), Sparks 3 (S Bampton, C Stuthridge, N Ahearn) Bethel ‘B’ 2 (G Buckle, M Green), Mevagissey ‘C’ 2 (C Prynn, P Harford) Lerryn 3 (D Phipps, G Brimicombe, G Hoskin), Bethel ‘C’ 2 (P Thomas, M Powell) St Stephen 3 (S Hancock, A Harrison, C Clark). Top breaks of the week: M Hancock 39, G Taylor 31, B McIntosh 47, 39 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle secure title despite defeat', 'bugle-secure-title-despite-defeat', 'Match Reports', '[]'::jsonb, 'In an extraordinary two nights of snooker surprises, the St Blazey and District Snooker Victory League has been retained by Bugle ‘A’ despite losing their final match on Monday to visiting Bethel ‘A’.', null, '"In the semi-finals of the doubles competition on Thursday an amazing match saw Darren Kirwan and Mike Hancock lose 3-0 to Ryan Bilson and Barry McIntosh as Barry had breaks of 79 and 62 ad a magnificent clearance of 137 – a fantastic achievement."', 'In an extraordinary two nights of snooker surprises, the St Blazey and District Snooker Victory League has been retained by Bugle ‘A’ despite losing their final match on Monday to visiting Bethel ‘A’.

more The night had started well as Andrew Best and Paul Sturtridge forged a 2-0 lead but Geoff Hawken’s 36 and also victories for Neil Rowe and Leon Collard left the Bugle boys speechless. This defeat seemed to open the door for St Blazey ‘B’ who needed nine points in their remaining two matches to snatch the league but it went badly wrong at St Neot on Tuesday as the three Courts – Michael, Steve and Aaron pulled off great victories to leave Blazey gobsmacked after their opportunity. Mike Hancock’s customary 46 break was little consolation. Bethel ‘D’ moved off the bottom as Martin Knight and Jason Pascoe secured framed but they went down to Bugle ‘B’ whilst three very tight frames all went the way of Mevagissey ‘A’ as they saw off Lostwithiel ‘A’ at the seaside. Darren Lock and Chris Perring were on target for the visitors. Tregonissey secured a great 4-1 victory at St Blazey ‘A’ with only Liam Reynolds’ victory over Mike Fox of note for the home side. Mevagissey ‘B’ only required a point from their last game at home to Bugle ‘C’ as they saw off their ‘D’ side 3-2 with Dave Kendall posting an excellent victory over James Tomlinson for the champions elect. Nearest rivals Bethel ‘C’ could only sneak a 3-2 victory at home to Lerryn as Charles McMriam and John Hancock surprised their hosts and Bethel ‘B’ joined their ‘C’ team on 56 points with a comprehensive 5-0 drubbing of basement boys Bugle ‘C’ with Mike Sweet’s 81-74 victory over Jordan Conroy the standout result of the evening. But the standout result of the evening has to be Gorran Haven’s stunning 4-1 win over neighbours Mevagissey ‘C’ as Lee McKinstry, Andy Reddall, Rob Bunney and Paul Grimmett gave Gorran their best result since rejoining the league and moved them above Lerryn in the table. In the semi-finals of the doubles competition on Thursday an amazing match saw Darren Kirwan and Mike Hancock lose 3-0 to Ryan Bilson and Barry McIntosh as Barry had breaks of 79 and 62 ad a magnificent clearance of 137 – a fantastic achievement.

FULL RESULTS

Victory League: Bugle ‘A’ 2 (A Best, P Sturtridge) Bethel ‘A’ 3 (G Hawken (36), N Rowe, L Collard) Bethel ‘D’ 2 (M Knight, J Pascoe) Bugle ‘B’ 3 (J Moore, I Ball, D Rundle), Mevagissey ‘A’ 3 (C Kendall, M Mills, L Varcoe) Lostwithiel ‘A’ 2 (D Lock, C Perring), St Neot 3 (M Courts, S Courts, A Courts) St Blazey ‘B’ 2 (M Hancock (46), D Kirwan), St Blazey ‘A’ 1 (L Reynolds) Tregonissey 4 (R Bilson, R Pearson, J Cocks, B McIntosh). Rees Memorial League: Bugle ‘C’ 0 Bethel ‘B’ 5 (G Buckle, M Green, M Sweet, J Tamblyn, S Hicks), Mevagissey ‘D’ 2 (S Mills, R Blamey) Mevagissey ‘B’ 3 (M Gregory, D Kendall, N Shaw), Bethel ‘C’ 3 (R Smithson, P Thomas, H Brett) Lerryn 2 (C McMiram, J Hancock), Gorran Haven 4 (L McKinstry, R Holmes, R Bunney, P Grimmett) Mevagissey ‘C’ 1 (J Chesterfield). Top breaks of the week: G Hawken 36, M Hancock 46 Additional Information League Tables Rankings Competitions Breaks The league will be holding their league finals over the next couple of weeks. Tuesday will see the team pairs final between Bugle ‘A’ and St Blazey ‘B’ at Lostwithiel Social Club. Next Wednesday, sees the doubles final where Ryan Bilson and Barry McIntosh, from Tregonissey taking on G Spencer and A Best or P Sturtridge and J Moore, who are all from Bugle. The seniors final will follow next Thursday with Len Flower, Lostwithiel taking on Mike Fox, from Tregonissey. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle still favourites despite defeat', 'bugle-still-favourites-despite-defeat', 'Match Reports', '[]'::jsonb, 'Despite tasting defeat by the odd frame at Tregonissey Bugle ‘A’ remain firm favourites to retain their title after nearest rivals St Blazey ‘B’ could only muster three points at home to Mevagissey ‘A’. The result…', null, '"With leaders Mevagissey ‘B’ on a bye week Bethel ‘C’ joined them at the summit albeit played a game more by beating Mevagissey ‘C’ 4-1 as messers Crockford, Thomas, Smithson and Howard Brett who had a 30 kept the pressure up on the favourites."', 'Despite tasting defeat by the odd frame at Tregonissey Bugle ‘A’ remain firm favourites to retain their title after nearest rivals St Blazey ‘B’ could only muster three points at home to Mevagissey ‘A’. The result really blew the chance to close the gap going into the last two weeks of the season.

more Barry McIntosh, Ryan Bilson and Chris Stephenson saw Treggy home with Spencer and Besty replying. Leighton Varcoe and Chris Kendall sealed Mevagissey’s points at St Blazey where Darren Kirwan’s 35 and Mile Hancock’s 30 were the highlights with Andrew Gooch just seeing off Matt Mills in the decider. Bugle ‘B’ scored a second 5-0 victory on the trot by seeing off St Neot, Mark Sturtridge and Jake Moore winning two close early frames to set them on their way. Jason Hill was the only bright note for Lostwithiel ‘B’ as they lost 4-1 at Bethel ‘A’ as Gary Stephens, Neil Roe, Geoff Hawken and Leon Collard responded and Bethel ‘D’ picked up two points at Lostwithiel ‘A’ through Andy Spearman and Richie Allen, Darren Lock recorded a 43 for the hosts. With leaders Mevagissey ‘B’ on a bye week Bethel ‘C’ joined them at the summit albeit played a game more by beating Mevagissey ‘C’ 4-1 as messers Crockford, Thomas, Smithson and Howard Brett who had a 30 kept the pressure up on the favourites. Lerryn scored an excellent victory over St Stephen as Terry Middleton, John Hancock and stalwart Graham Hoskin secured the points in Lerryn’s best season in living memory. Bodmin Sparks dumped Bugle ‘C’ back to the bottom of the league with a 5-0 whitewash whilst Bethel ‘B’ courtesy of Jim Tamblyn, Matt Green and Dave Morshead and Mike Sweet saw off Mevagissey ‘C’ whose Scott Mills picked up their solitary point.

FULL RESULTS

Victory League: Lostwithiel ‘A’ 3 (D Lock (43), C Dickinson, A Maddams) Bethel ‘D’ 2 (A Spearman, R Allen), Tregonissey 3 (B McIntosh, R Bilson, C Stephenson) Bugle ‘A’ 2 (A Best, G Spencer) Bethel ‘A’ 4 (G Stephens, N Rowe, G Hawken, L Collard) Lostwithiel ‘B’ 1 (J Hill), St Blazey ‘B’ 3 (M Hancock (30), D Kirwan (35), A Gooch) Mevagissey ‘A’ 2 (L Varcoe, C Kendall), Bugle ‘B’ 5 (M Sturtridge, J Moore, K Moore, I Ball, D Rundle) St Neot 0. Rees Memorial League: Sparks 5 (R Bolt, M Williams, S Bampton, C Stuthridge, M Bolt) Bugle ‘C’ 0, Bethel ‘B’ 4 (J Tamblyn, M Green, D Morshead, M Sweet) Mevagissey ‘D’ 1 (S Mills), Lerryn 3 (T Middleton, J Hancock, G Hoskin) St Stephen 2 (A Garside, C Clark), Mevagissey ‘C’ 1 (B Prynn) Bethel ‘C’ 4 (H Brett (30), C Crockford, R Smithson, P Thomas). Top breaks of the week: D Lock 43, M Hancock 30, D Kirwan 35, H Brett 30 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Bugle win derby to close in on leaders', 'bugle-win-derby-to-close-in-on-leaders', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ closed the gap on leaders St Blazey ‘B’ as they triumphed 4-1 in the Bugle derby Jake Moore continued his good season when beating Paul Sturtridge but Poweller, Spencer, Peersy and Besty with a 36-break…', null, '"Lostwithiel ‘B’ also came back from 2-0 to record a rare victory at St Blazey ‘A’ as Bryan Warne, Jason Hill and Len Flower turned the form book on its head while St Net pulled off a notable victory over Tregonissey with Aaron and Steve Courts along with Nigel Collins winning for the home side."', 'Bugle ‘A’ closed the gap on leaders St Blazey ‘B’ as they triumphed 4-1 in the Bugle derby Jake Moore continued his good season when beating Paul Sturtridge but Poweller, Spencer, Peersy and Besty with a 36-break showed they don’t mean to give their title away easily.

more Dan Courts and Darren Northcott notched Lostwithiel ‘A’s points agains the leaders but the reliable Paul Baron, Andrew Gooch and Mike Hancock pocketed the spoils for the Blazey boys. Bethel ‘D’ remain adrift at the bottom despite racing into a 2-0 lead over Mevagissey ‘A’ through Andy Spearman and Ryan Tonkin but messes Kendall, Mills and Towsey addressed the situation for the seasiders. Lostwithiel ‘B’ also came back from 2-0 to record a rare victory at St Blazey ‘A’ as Bryan Warne, Jason Hill and Len Flower turned the form book on its head while St Net pulled off a notable victory over Tregonissey with Aaron and Steve Courts along with Nigel Collins winning for the home side. Bugle ‘C’ won for the first time since October 8 with an emphatic 4-1 success at Lerryn which saw them jump two places in the table as Pascoe, Conroy, Couchman and Spencer were victorious with only Charles McMiram getting any joy for the home side. An excellent performance by Gorran Haven reaped little reward at league leaders Bethel ‘C’ – Lee McKinstry going in off the black against Roger Smithson summed up their luck for the evening. Paul Grimmett registering for the Haven, but that results along with Mevagissey ‘B’ dropping two points to Bethel ‘B’ means Smithson’s side are a point clear at the top. Mevagissey ‘B’ picked up a useful win at home to Bethel ‘B’ to consolidate second place and are looking strong as we enter the last few weeks of the season – Rothwell, Rowe and Shaw were the winners to keep their good run going. St Stephen jumped into fourth place as a result of beating their visitors Bodmin Sparks 3-2, Mike Williams and Clive Stuthridge claiming the last two frames for the visitors. The Gordon Boynton trophy will be played for at Bugle Working Mens Club on Saturday, March 29 with the league presentation night at Bethel Social Club on Saturday, April 12 with buffet and raffle and music by Citizen Smith.

FULL RESULTS

Victory League: Bugle ‘B’ 1 (J Moore) Bugle ‘A’ 4 (A Best (36), A Peers, G Spencer, I Powell), St Blazey ‘A’ 2 (S Dewings, M Woodward) Lostwithiel ‘B’ 3 (L Flower, B Warne, J Hill), Bethel ‘D’ 2 (A Spearman, R Tonkin), Mevagissey ‘A’ 3 (C Kendall, M Mills, M Towsey), Lostwithiel ‘A’ 2 (D Courtis, D Northcott) St Blazey ‘B’ 3 (P Baron, M Hancock, A Gooch), St Neot 3 (A Courts, N Collins (41), S Courts (54)) Tregonissey 2 (C Stephenson, R Pearson (45)). Rees Memorial League: Bethel ‘C’ 4 (H Brett, R Smithson, S Jones, P Thomas) Gorran Haven 1 (P Grimmett), Lerryn 1 (C McMiram) Bugle ‘C’ 4 (M Pascoe, J Conroy, N Couchman, K Spencer), Mevagissey ‘B’ 3 (B Rothwell, M Rowe, N Shaw), Bethel ‘B’ 2 (M Green, M Sweet), St Stephen 3 (C Clark, A Harrison, A Garside) Sparks 2 (M Williams, C Stuthridge). Top breaks of the week: S Courts 54, R Pearson 50, N Collins 41, A Best 36 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Alain Robidoux Exclusive', 'cueview-alain-robidoux-exclusive', 'Cue View', '[]'::jsonb, 'We have been lucky enough today to catch up and receive a CueView from the legend that is Canada''s Alain Robidoux', null, '"I had a good Amateur career and turned professional at 28 years old and had a pretty good year on my first one reaching the Semi of the Rothmans Grand Prix in Reading getting beat by Alex Higgins. I''ve stayed in England and Scotland for 15 years until I retired from the game in 2003. "', 'We have been lucky enough today to catch up and receive a CueView from the legend that is Canada''s Alain Robidoux

more STBS - What is your full name please AR - Alain Robidoux STBS - Your Current Club/base AR - The 147 snooker club in Montreal Canada STBS - Your Highest Break AR - I have made over 100 times 147 break STBS - Are you Left/Right Handed or both AR - I am right handed STBS - Bio about yourself (in no more than 200 words) AR - I started playing at 12 and played pool at the start till someone told me about snooker and as soon I''ve seen the table i knew snooker was the game i would play. I had a good Amateur career and turned professional at 28 years old and had a pretty good year on my first one reaching the Semi of the Rothmans Grand Prix in Reading getting beat by Alex Higgins. I''ve stayed in England and Scotland for 15 years until I retired from the game in 2003. I had a cue problem in 1997 when I was provisionally 3rd in the World but unfortunately I couldn''t get used to a cue fast enough to keep my ranking. I had a tough road afterwards and that s why I had to leave the circuit because it was hard to take considering how well i was playing before the cue incident. Now I''m back home, still playing and working as a commentator and in a club as well. The only thing i can say about snooker, it s the best game in the world when you are playing at your best! STBS - What was your first ever memory of snooker? AR - My first memory of snooker it s watching Cliff Thorburn playing Big Bill Werbeniuk on TV back home and find it so quiet that i fell in love with the game right there! STBS - At what age did you start playing snooker and why? AR - I started playing at 12 because I liked seeing balls disappeared in the pockets!!! STBS - What has been your greatest achievement in snooker? AR - It''s the Semi in the 97 World Championship and the final of the German Open in 96. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) AR - I''ve played them all!! But Steve Davis was my idol when i turned Pro and i had the chance to play him on my first year!!! STBS - Who is your favourite TV commentator? AR - My favourite commentators are Dennis Taylor and John Virgo because they have got a lot of knowledge about the game. STBS - What is your Favourite professional player and why? AR - Ronnie O''Sullivan is my favourite player to watch but Stephen Hendry is my favourite player of all time. STBS - What has been the most memorable snooker match you have ever seen? AR - It''s the Royal Liverpool Victoria in Birmingham in 98 when Hendry made a maximum on the last game of the tournament against Ronnie. STBS -Who is the most under-rated player in professional snooker? AR - The most under rated player has to be Stuart Bingham. He is very talented and I wouldn''t be surprised if he wins something big soon!!! STBS - Funniest moment in your snooker experience? AR - The funniest thing it''s my first trip over as a Pro when i had to fly over and forgetting my passport at home. I think i was a bit excited about everything!!! STBS - Who is your bogey player? AR - My bogey player was Hendry but he was the bogey player of a lot of players i guess! STBS - Do you have any snooker ambitions you still have not achieved? AR - My snooker ambitions are to keep playing the game till i die at a good standard and keep enjoying it as much as i do now!!! Images Courtesy of: Actin Images', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Alfie Burden Exclusive', 'cueview-alfie-burden-exclusive', 'Cue View', '[]'::jsonb, 'We managed to catch up with Alfie Burden whilst he was online on twitter, Alfie Kindly agreed to do a quick CueView for us - enjoy everyone', null, '"Professional for 19 years played at crucible in 1998 best ranking event performances 6 last 16s won the world ibsf title in 2009 currently ranked 53 in the world and hoping to move forward. Have two great kids aged 10&7 my son is following in my footsteps he currently plays for Arsenal."', 'We managed to catch up with Alfie Burden whilst he was online on twitter, Alfie Kindly agreed to do a quick CueView for us - enjoy everyone

more STBS - What is your full name please AB - Alfie Burden STBS - Your Current Club/base AB - Varied STBS - Your Highest Break AB - 147 STBS - Are you Left/Right Handed or both AB - Left STBS - Bio about yourself (in no more than 200 words) AB - Professional for 19 years played at crucible in 1998 best ranking event performances 6 last 16s won the world ibsf title in 2009 currently ranked 53 in the world and hoping to move forward. Have two great kids aged 10&7 my son is following in my footsteps he currently plays for Arsenal. STBS - What was your first ever memory of snooker? AB - Taylor Davis 1985 watching it with my dad STBS - At what age did you start playing snooker and why? AB - 9 STBS - What has been your greatest achievement in snooker? AB - 2009 world AM champ STBS - Who is the most famous professional player you have played or met? (can be modern or older era) AB - Hendry & white played them all STBS - Who is your favourite TV commentator? AB - Foulds and also my good friend STBS - What is your Favourite professional player and why? AB - Jimmy great friend respect him a great deal and helped me an awful lot in snooker and life over the years STBS - What has been the most memorable snooker match you have ever seen? AB - Made 3 tons in a pro match and lost 5-3 always remember that one STBS -Who is the most under-rated player in professional snooker? AB - Me STBS -Who is the best professional player in your view to have ever picked up a cue? AB - O Sullivan for me STBS - Funniest moment in your snooker experience? AB - Practicing with Q Hann for 5 years STBS - Who is your bogey player? AB - Dave Gilbert STBS - Do you have any snooker ambitions you still have not achieved? AB - Plenty Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Andy Hicks Exclusive', 'cueview-andy-hicks-exclusive', 'Cue View', '[]'::jsonb, 'Andy Hicks is the only professional snooker player to reside in our beautiful county of Cornwall so it is therefore with pleasure that Andy has agreed to do a CueView interview with us.', null, '"Started playing at 10 years old. My mum was a hair dresser and i was off school ill one day and my mum took me with her to cut one of her friends hair. so to keep me occupied the lady let me have a go on her sons 6x3 snooker table in the back living room. ( and the rest is history )"', 'Andy Hicks is the only professional snooker player to reside in our beautiful county of Cornwall so it is therefore with pleasure that Andy has agreed to do a CueView interview with us.

more Andy is not only a professional snooker player but he is now also an acredited Qualified World Snooker coach more details on this can be found later in the article. STBS - What is your full name please AH - Andy Hicks STBS - Your Current Club/base AH - Crackington Haven Cornwall STBS - Your Highest Break AH - 147 285 maximums in total STBS - Are you Left/Right Handed or both AH - Left Handed except for golf and cricket right handed STBS - Bio about yourself (in no more than 200 words) AH - I was born in 1973 grew up in Tavistock where i went to Tavistock college. I played all sports at school to quite a good standard. Started playing snooker on a full size table at the age of 12. Then started playing league snooker in Plymouth where i became Plymouth And District individual champion 5 years in a row until the age of 17. Then won the British under 19s tournament when i then decided to turn Professional. I was managed by an ex pro called Bill Oliver who became a great manager and mentor of mine for the next 10 years. We then parted on good terms when i moved to London to try and better my career. Lived there for 18 months when moving back to the westcountry where i felt i belonged. I then got to know who has now become a great friend of mine Paul Williams who did use to run a snooker club in Falmouth where i spent around 10 years of practicing at his club. I now practice locally to where i live. Now married with two children so dont practice anything like as much as i should do. STBS - What was your first ever memory of snooker? AH - Watching Alex Higgins when sat on my dads lap. Which i think was the one frame pot black comp. STBS - At what age did you start playing snooker and why? AH - Started playing at 10 years old. My mum was a hair dresser and i was off school ill one day and my mum took me with her to cut one of her friends hair. so to keep me occupied the lady let me have a go on her sons 6x3 snooker table in the back living room. ( and the rest is history ) STBS - What has been your greatest achievement in snooker? AH - Personally dont feel like i have acheived as i have never won a major tournament. But probably the semi final of the world championship in 1995 STBS - Who is the most famous professional player you have played or met? (can be modern or older era) AH - Practiced with Ray Reardon what a legend that guy is. And still playing a great game i hear. STBS - Who is your favourite TV commentator? AH - Dont have one as i always turn the sound off if im watching. STBS - What is your Favourite professional player and why? AH - Dave Harold. why because he is the most acheived player with the type of cueing action that he has. And a great person too. STBS - What has been the most memorable snooker match you have ever seen? AH - Sat watching the 1985 final with Dennis Taylor and Steve Davis at 1am in the morning. STBS -Who is the most under-rated player in professional snooker? AH - Dave Harold again. For the simple reason that if he had a BETTER cueing action he would be a world champion at some point in his career. STBS - Funniest moment in your snooker experience? AH - Getting my own back on Quinten Hann when beating him in the World Championship. That was funny to me,and me only. Bless him:) STBS - Who is your bogey player? AH - Dont feel like i have one really. STBS - Do you have any snooker ambitions you still have not achieved? AH - To win a ranking event. Images Courtesy of: Nigel Yeo

BUSINESS CARD

Andy Hicks Professional Snooker Player Qualified World Snooker Coach Tuition Of All Ages One To One Or Group Bookings CRB Checked Also available for exhibitions and personal appearances email: andyhickssnooker@gmail.com Tel 07758 323815', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Barrie McIntosh', 'cueview-barrie-mcintosh', 'Cue View', '[]'::jsonb, 'THIS EDITION OF CUEVIEW FEATURES MR BARRIE MCINTOSH', null, '"Playing a best of 9 frames county final finishing at 1am the next morning"', 'THIS EDITION OF CUEVIEW FEATURES MR BARRIE MCINTOSH

more STBS - What is your full name please BM - Barrie McIntosh STBS - Your Current Club/base BM - Tregonissey A STBS - Your Highest Break BM - 143 STBS - Are you Left/Right Handed or both BM - I''m right handed. STBS - Bio about yourself (in no more than 200 words) BM - The baby faced assassin haha STBS - What was your first ever memory of snooker? BM - Watching the world championships on telly with my grandparents STBS - At what age did you start playing snooker and why? BM - Because I was crap at everything else STBS - What has been your greatest achievement in snooker? BM - Getting to the England under 21''s finals at 15 STBS - Who is the most famous professional player you have played or met? (can be modern or older era) BM - Len Flower followed by Ronnie STBS - Who is your favourite TV commentator? BM - Dennis Taylor - funny guy! STBS - What is your Favourite professional player and why? BM - Hendry - ugly as hell but can control a cue STBS - What has been the most memorable snooker match you have ever seen? BM - Steve Davis vs Ronnie O''Sullivan, UK champs Davis 8-4 down, won 10-8 STBS - Who is the best player in the league? BM - Aaron Gill, followed by Leighton Varcoe STBS -Who is the most under-rated player in the league? BM - Mike Fox, a living legend STBS - Funniest moment in your snooker experience? BM - Playing a best of 9 frames county final finishing at 1am the next morning STBS - Who is your bogey player? BM - Darren Lock recently - will get my singles trophy back though! STBS - Do you have any snooker ambitions you still have not achieved? BM - County title Cheers Barrie some interesting answers in there Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Ben Harrison Exclusive', 'cueview-ben-harrison-exclusive', 'Cue View', '[]'::jsonb, 'We caught up with up and coming professional Ben Harrison whilst he was preparing for the UK qualifiers, Ben is one to watch out for in the future we hope you enjoy this CueView.', null, '"I did a 24 hour snooker marathon for charity in 2010 so my girlfriend said she would give me a frame out of everyone there , I let her break and then i had a 147 against her. I felt so bad! She''s never played me since! "', 'We caught up with up and coming professional Ben Harrison whilst he was preparing for the UK qualifiers, Ben is one to watch out for in the future we hope you enjoy this CueView.

more STBS - What is your full name please BH - Ben Harrison STBS - Your Current Club/base BH - Players club, Westbury Wiltshire. STBS - Your Highest Break BH - 147 x19 highest tournament break is 144. STBS - Are you Left/Right Handed or both BH - I''m right handed but my highest left handed break is 108. So I trust my left hand over the rest! STBS - Bio about yourself (in no more than 200 words) BH - Basically I''m just easy going, talkative and dedicate my whole life to snooker. I work really hard and I''m quite a perfectionist which isn''t always a good thing! STBS - What was your first ever memory of snooker? BH - I think My first memory was the Williams / Hendry decider in the masters in 1999. Amazing. STBS - At what age did you start playing snooker and why? BH - I started playing when I was 8. I used to go to Spain a lot and play pool and my parents thought I was a real natural, then when we got home one time they took me to the local club and I went from there. STBS - What has been your greatest achievement in snooker? BH - Greatest achievement: not really sure. Star of the future finalist in 2009 losing to Michael white. English Under 19 runner up against adam Duffy and last 32 of PTC 7 last year. Also I was senior champion of cuestars in 2007 at just 15. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) BH - Most famous professional I have met: probably jimmy white or Steve Davis, both massive legends. Although I''m really good friends with Judd trump so it will probably be him in a few years!. The most famous player I have played is John Higgins, he beat me 4-2. I was proud of that. STBS - Who is your favourite TV commentator? BH - Stephen Hendry by a mile. Spots shots immediately and calls it right everytime. STBS - What is your Favourite professional player and why? BH - Ronnie O''Sullivan, the guy is just a genius. He is my idol. STBS - What has been the most memorable snooker match you have ever seen? BH - Watching Judd beat ronnie at the uk last year. He was awesome. STBS -Who is the most under-rated player in professional snooker? BH - I think the most underrated player at the moment is Tom ford. Incredible break builder, should be in the top 16, he is starting to get there now though. STBS - Funniest moment in your snooker experience? BH - Not sure about this one either but I did a 24 hour snooker marathon for charity in 2010 so my girlfriend said she would give me a frame out of everyone there, I let her break and then i had a 147 against her. I felt so bad! She''s never played me since! STBS - Who is your bogey player? BH - I don''t really have a bogey player yet. STBS - Do you have any snooker ambitions you still have not achieved? BH - Biggest ambition is to get on the tour and into the 16. I feel I should be on the tour already but I have quite a few chances this year so hopefully this is my time. I''m only 21 but I feel ready now. Images Courtesy of: Ben Harrison', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - CJ de Mooi Exclusive', 'cueview-cj-de-mooi-exclusive', 'Cue View', '[]'::jsonb, 'CJ de Mooi, Egghead, Quiz genius, Snooker fan and general nice guy has kindly, exclusively talked with us and filled in one of our ever increasingly popular CUEVIEW interviews, we hope you enjoy it. it''s a good read…', null, '"Appearing on Pointless Celebrities with Shaun Murphy. The show has been transmitted yet so I can’t tell you the result but it was very enjoyable and hilarious!"', 'CJ de Mooi, Egghead, Quiz genius, Snooker fan and general nice guy has kindly, exclusively talked with us and filled in one of our ever increasingly popular CUEVIEW interviews, we hope you enjoy it. it''s a good read - and thank you CJ your a star

more STBS - What is your full name please CJ - CJ de Mooi STBS - Your Current Club/base CJ - None STBS - Your Highest Break CJ - 17 (I''m not a good player - I barely know which way round to hold the bat) STBS - Are you Left/Right Handed or both CJ - I''m right handed. STBS - Bio about yourself CJ - At the age of 8 CJ was chosen as the lead in a school musical production called Rooster Rag. His love of entertaining was born at that moment. He joined and became an active member of the Crucible and National Youth Theatres appearing in several plays over the next few years. Courses at the Rotherham College of Arts and Technology confirmed acting as the path he wanted his life to take and his school and extra curricular studies were all geared towards this. However, just after his 17th birthday, CJ was suddenly forced to become homeless and 3 years of sleeping rough began. Naturally his career ambitions came to a very abrupt and distressing stop. In his last teenage weeks, and as German was the only foreign language he could speak at the time, CJ found himself in Cologne. His very first weekend resulted in a totally unexpected offer of a modelling contract with a local agency and he remained in the city for 5 years. A further 18 months in Amsterdam was sufficient time to become fluent in Dutch too (and fall in love with the city!) before a return to the UK. In 2000, after feeling a little restless, CJ decided to apply to a few television game and quiz shows as a contestant. His first appearance on Pass the Buck was spectacularly short of mediocrity but his next was a lucky win on Fifteen to One. This was followed by what he thought would be his last show, The Weakest Link. Despite consistently being the strongest player he was the third voted off and launched into his now infamous rant in his post game interview. This immediately attracted national attention and the programme asked him back for a Bad Losers'' Special which he won! A further 12 programmes invited him to take part giving him free rein to exercise his general knowledge and, as one executive described it, his refreshing forthrightness of opinion. The first week of 2003 brought CJ a phone call about a new concept quiz show called Eggheads. Intrigued by the idea of 5 quiz champions competing against different daily challengers, he went along to the read through and happily agreed to take part. However, realising that only a tiny percentage of shows even reach the pilot stage, never mind the rarified heights of commissioning, he expected nothing further would develop. He was a little more than stunned by a second call in July advising him that not only had the new show been accepted, filming actually started in 3 weeks and he''d better get learning! Eggheads went on to become a phenomenon with over 1100 shows, 2 spin off series and a sell out book and board game. Despite enjoying himself immensely for 8 years and being so grateful for the opportunities he had undeservedly received, all good things must come to an end and in December 2011, CJ announced he had left the show to pursue his acting career. Such a long running and highly successful programme gave CJ a popular public profile and he naturally wanted to expand his horizons and explore other fields of interest to him. He was honoured to be elected as the President of the English Chess Federation in 2009 as he''d previously been the most active player in the country, winning the title of Mensa Chess Champion in 2001. CJ also competes regularly in longer distance running events, taking part in several half and full marathons each year. He also publicly supports several charities especially those involved with the HIV sector where CJ has volunteered for many years. However, his overwhelming desire was always acting and participating in some live events reignited his fire. His lead role performance in the 2011 short film The Renata Road gained good reviews and persuaded CJ to follow his dream and pursue this career path full time. Despite enjoying and appearing in all performing media, musical theatre remains his one true passion. CJ freely admits to having been incredibly lucky over the last decade and is delighted to enjoy and work for the wonderful opportunities he''s been given. Acting has now of course become the major part of his professional life although he''ll no doubt be associated with, and in demand for, high level quizzing for quite some time yet. He is looking forward to the surprises and challenges of the future and hopes you enjoy looking around his site and learning about him - after all, learning new things got CJ his career! STBS - What was your first ever memory of snooker? CJ - I watched Eddie Charlton paying on television when I was about 3 - surprisingly this didn''t put me off snooker forever STBS - At what age did you start playing snooker and why? CJ - played a little when I was 20 in Germany but was much better at Pool (even won a couple of tournaments) STBS - What has been your greatest achievement in snooker? CJ - Playing a frame at the Crucible accompanying Kirk Stevens against Cliff Thorburn STBS - Who is the most famous professional player you have played or met? (can be modern or older era) CJ - I''ve met all the modern era players and most of those from the 70s onwards but for sheer awe inspiring quality, it has to be Ray Reardon. STBS - Who is your favourite TV commentator? CJ - I really like Dominic Dale although we don''t get to hear too much of him as he''s usually playing. I never really cared for Ted Lowe but Clive Everton has a skill and knowledge that will never be surpassed. STBS - What is your Favourite professional player and why? CJ - Steve Davis can do no wrong as far as I''m concerned but Shaun Murphy is a friend and the nicest chap I''ve ever met. STBS - What has been the most memorable snooker match you have ever seen? CJ - The 2002 World final. Hendry played awfully but when it tied at 17-17, I thought he was finally going to become Hendry the Eighth (I''m sure all the headline writers were poised with the headline) but hats off to Ebdon for coming through. STBS - Funniest moment in your snooker experience? CJ - Appearing on Pointless Celebrities with Shaun Murphy. The show has been transmitted yet so I can''t tell you the result but it was very enjoyable and hilarious! STBS - Who is your bogey player? CJ - Well, I''ve never beaten Jimmy White... STBS - Do you have any snooker ambitions you still have not achieved? CJ - Yes. To see a 147 live! STBS - Who is the most under-rated player in professional snooker? CJ - Sounds surprising to say it about a World Champion, but Graeme Dott is massively under-rated. His personal issues no doubt impacted on his career but to achieve what he has (3 World finals to date!) is superb. Images Courtesy of: CJ de Mooi', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Chris Kendall', 'cueview-chris-kendall', 'Cue View', '[]'::jsonb, 'This edition of CUEVIEW features Mr Chris Kendall of Tregonissey', null, '"In the last world snooker champs final John Higgins v Judd Trump, Higgins was 12-9 behind and then came back to win 18-15"', 'This edition of CUEVIEW features Mr Chris Kendall of Tregonissey

more STBS - What is your full name please CK - Chris Kendall STBS - Your Current Club/base CK - Tregonissey A STBS - Your Highest Break CK - 100 STBS - Are you Left/Right Handed or both CK - I''m right handed. STBS - Bio about yourself (in no more than 200 words) CK - Trainee fitness instructor love playing my cricket and snooker STBS - What was your first ever memory of snooker? CK - Ronnie O''Sullivan making a world record 147 maximum in just 5 mins 20 secs amazing! STBS - At what age did you start playing snooker and why? CK - 11 years old, ever since I started watching the world championships on TV, I just then fell in love with the game STBS - What has been your greatest achievement in snooker? CK - Reaching the Cornwall under 21''s individual final STBS - Who is the most famous professional player you have played or met? (can be modern or older era) CK - Judd Trump STBS - Who is your favourite TV commentator? CK - Willie Thorne STBS - What is your Favourite professional player and why? CK - Ronnie O''Sullivan because he just makes the game so easy and he''s just awesome to watch STBS - What has been the most memorable snooker match you have ever seen? CK - In the last world snooker champs final John Higgins v Judd Trump, Higgins was 12-9 behind and then came back to win 18-15 STBS - Who is the best player in the league? CK - Barrie McIntosh STBS -Who is the most under-rated player in the league? CK - Ian Ball STBS - Funniest moment in your snooker experience? CK - I really don''t have one STBS - Who is your bogey player? CK - Mike Towsey STBS - Do you have any snooker ambitions you still have not achieved? CK - 147 maximum break and the St Blazey individual trophy Cheers Chrissy Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Craig Steadman Exclusive', 'cueview-craig-steadman-exclusive', 'Cue View', '[]'::jsonb, 'It was a real pleasure to speak with Craig and get his Cue View really nice guy and very candid with his answers', null, '"Played in the masters quals a few years ago and my opponent took of his arm and attached a 12 ft extension to his shoulder!! Thinks his name was graemme Francis??"', 'It was a real pleasure to speak with Craig and get his Cue View really nice guy and very candid with his answers

more STBS - What is your full name please CS - Craig Steadman STBS - Your Current Club/base CS - 147 club….. Manchester STBS - Your Highest Break CS - 147 STBS - Are you Left/Right Handed or both CS - Right STBS - Bio about yourself (in no more than 200 words) CS - Easy going guy who likes most things men like. STBS - What was your first ever memory of snooker? CS - Playing in a labour club whilst my grandad brushed the tables. STBS - At what age did you start playing snooker and why? CS - 11 for the reason above. STBS - What has been your greatest achievement in snooker? CS - Won a few good Amatuer events but as a pro making venues is what it’s all about after a small taste of it. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) CS - Played most pro’s so it’s down to personal opinion who’s most famous. STBS - Who is your favourite TV commentator? CS - Stephen hendry is class in and out the commentary box. STBS - What is your Favourite professional player and why? CS - Graemme dott…. Not sure why just always rooted for him. (Not when I’ve played him of course) STBS - What has been the most memorable snooker match you have ever seen? CS - Hendry v white world final that went the distance and Paul hunters comebacks in masters finals. STBS -Who is the most under-rated player in professional snooker? CS - Graemme Dott. STBS -Who is the best professional player in your view to have ever picked up a cue? CS - Ronnie O''Sullivan STBS - Funniest moment in your snooker experience? CS - Played in the masters quals a few years ago and my opponent took of his arm and attached a 12 ft extension to his shoulder!! Thinks his name was graemme Francis?? STBS - Who is your bogey player? CS - Don’t like that term but I’ve never beaten Ryan day if my memory is correct. STBS - Do you have any snooker ambitions you still have not achieved? CS - To many to write!! Ha Images Courtesy of: Günter Leitenbauer', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Daniel Wells Exclusive', 'cueview-daniel-wells-exclusive', 'Cue View', '[]'::jsonb, 'In the latest edition of CueView we caught up with Welsh Professional Daniel Wells, Daniel shares his thoughts, memories and views on snooker', null, '"My phone going off in a amateur final my ringtone at the time was the Thomas the tank theme! Luckily it was on my shot!"', 'In the latest edition of CueView we caught up with Welsh Professional Daniel Wells, Daniel shares his thoughts, memories and views on snooker

more STBS - What is your full name please DW - Daniel Wells STBS - Your Current Club/base DW - South west snooker academy Gloucester STBS - Your Highest Break DW - 147 x 2 STBS - Are you Left/Right Handed or both DW - I am left handed STBS - Bio about yourself (in no more than 200 words) DW - Former welsh and european amateur champion. Was one frame away from reaching the crucible aged 20. STBS - What was your first ever memory of snooker? DW - Hendry v Williams masters final. STBS - At what age did you start playing snooker and why? DW - Aged 10, because my best mate was beating me at pool all the time and my dad said if I can play snooker I can play pool, never looked back. STBS - What has been your greatest achievement in snooker? DW - Either winning the European snooker championships of getting to the last 48 of the world championship. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) DW - Hendry, Davis & O''Sullivan STBS - Who is your favourite TV commentator? DW - Dennis Taylor STBS - What has been the most memorable snooker match you have ever seen? DW - John Higgins v O''sullivan in the masters when Higgins cleared to win the decider, unbelievable! STBS -Who is the most under-rated player in professional snooker? DW - Dominic Dale STBS - Funniest moment in your snooker experience? DW - My phone going off in a amateur final my ringtone at the time was the Thomas the tank theme! Luckily it was on my shot! STBS - Who is your bogey player? DW - Don''t really have one STBS - Do you have any snooker ambitions you still have not achieved? DW - To become world champion Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Darren Kirwan', 'cueview-darren-kirwan', 'Cue View', '[]'::jsonb, 'Our first CUEVIEW features our league secretary Mr Darren Kirwan', null, '"Anthony Garside breaking with the rest against Bob Noble, playing 10 or more consecutive rest shots, under the influence of speckled hen and still winning"', 'Our first CUEVIEW features our league secretary Mr Darren Kirwan

more STBS - What is your full name please DK - Darren Kirwan STBS - Your Current Club/base DK - Tywardreath RBL STBS - Your Highest Break DK - 82 STBS - Are you Left/Right Handed or both DK - I''m right handed. STBS - Bio about yourself (in no more than 200 words) DK - Sales manager for Travis Perkins and league secretary for my sins. Heavily involved with St Blazey cricket club, oh yeah and I love Kebabs. STBS - What was your first ever memory of snooker? DK - Watching a game at St Blazey in the mid 90''s and wondering why such a good player had such a strange hairstyle STBS - At what age did you start playing snooker and why? DK - 13 or 14 - Gordon used to hold 3 reds competition at St Blazey for the under 21''s STBS - What has been your greatest achievement in snooker? DK - Beating Clive Stuthridge in a black ball thriller after 18 pints on my 21st birthday in grants, Clive has never recovered. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) DK - Jimmy Whites & Andy Giles haha STBS - Who is your favourite TV commentator? DK - The late Sid Waddell STBS - What is your Favourite professional player and why? DK - Ronnie O''Sullivan, mega talented and speaks his mind STBS - What has been the most memorable snooker match you have ever seen? DK - Anthony Garside breaking with the rest against Bob Noble, playing 10 or more consecutive rest shots, under the influence of speckled hen and still winning STBS - Who is the best player in the league? DK - Andrew Best, no-one comes close until they have done it over a long period STBS -Who is the most under-rated player in the league? DK - John Wilson bangs in breaks over 50 on a regular basis in practice STBS - Funniest moment in your snooker experience? DK - St Austell Con club away with the St Blazey lads, in fact - most weeks back in the old days were a laugh! STBS - Who is your bogey player? DK - Lost 3 under 21 finals to Nathan Rickard back in the day - No current ones though STBS - Do you have any snooker ambitions you still have not achieved? DK - 100 break, highly unlikely. Thanks Darren good answers and funny as ever Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Gary Spencer', 'cueview-gary-spencer', 'Cue View', '[]'::jsonb, 'Gary Spencer of Bugle A talks to us via our new CueView feature.', null, '"Playing players like Ronnie O’Sullivan, Judd Trump, Jimmy White, Andy Hicks all in exhibitions and to win one of those against Andy knocking in a 40 in the process was rather memorable."', 'Gary Spencer of Bugle A talks to us via our new CueView feature.

more STBS - What is your full name please GS - Gary Spencer STBS - Your Current Club/base GS - Bugle WMC STBS - Your Highest Break GS - 122 Total Clearance STBS - Are you Left/Right Handed or both GS - I''m right handed. STBS - Bio about yourself (in no more than 200 words) GS - I’m a keen sportsman who likes to keep fit and play a variety of sports such as cricket, football, pool (occasionally) & of course snooker is my number one hobby in my spare time. STBS - What was your first ever memory of snooker? GS - Playing on a miniature table at home in the living room before going to school. STBS - At what age did you start playing snooker and why? GS - I started playing at 15, simply because I wasn’t allowed to play until that age due to club rules! STBS - What has been your greatest achievement in snooker? GS - I’ve had some good achievements so far so to pick one out in particular is difficult, but those that spring to mind are as follows:

• Knocking in a 102 break at Bugle to win the highest break prize!
• Playing players like Ronnie O’Sullivan, Judd Trump, Jimmy White, Andy Hicks all in exhibitions and to win one of those against Andy knocking in a 40 in the process was rather memorable.
• Representing the County Youth & now Seniors on various occasions.

Winning all the Team titles & Youth with Bugle in the 2008/2009 season… detailed as follows:

• Victory League winners, Team Handicap winners, Team Pairs winners, County Team Winners, County Under 21’s runner up, League under 21’s winner
• Having the chance to compete at Gloucester Snooker Academy in a Amatuer event on the Pro Tables against some very tough opponents – a worth while experience!
• Winning the County Doubles with Andrew Best in 2011/2012 Season

STBS - Who is the most famous professional player you have played or met? (can be modern or older era) GS - Ronnie Osullivan, Judd Trump & Jimmy White (Played) & Met Steve Davies, John Vergo, Mark Selby STBS - Who is your favourite TV commentator? GS - I don’t have one really. STBS - What is your Favourite professional player and why? GS - Ronnie O’Sullivan – his talent speaks for it’self! STBS - What has been the most memorable snooker match you have ever seen? GS - Higgins v Ronnie when Ronnie lost playing faultless snooker! STBS - Who is the best player in the league? GS - Andy Best over a period of time. STBS -Who is the most under-rated player in the league? GS - Don’t know STBS - Funniest moment in your snooker experience? GS - Henry playing from the cushion when he had the ball in hand. STBS - Who is your bogey player? GS - I don’t have one really. STBS - Do you have any snooker ambitions you still have not achieved? GS - County Singles Title & League Singles Titles Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - George Lory', 'cueview-george-lory', 'Cue View', '[]'::jsonb, 'This edition of CUEVIEW features our illustrious chairman and Lostwithiel B player Mr George Lory', null, '"Playing county doubles v Liskeard con club in one frame I did not get a shot as my opponent hit a 136 break in"', 'This edition of CUEVIEW features our illustrious chairman and Lostwithiel B player Mr George Lory

more STBS - What is your full name please GL - George Lory STBS - Your Current Club/base GL - Lostwithiel B STBS - Your Highest Break GL - 86 STBS - Are you Left/Right Handed or both GL - I''m right handed. STBS - Bio about yourself (in no more than 200 words) GL - Started playing Newquay league at 16, enjoyed always even now that I can no long compete, but many good memories STBS - What was your first ever memory of snooker? GL - Watching Pot Black on a black and white TV STBS - At what age did you start playing snooker and why? GL - Started at 14 to do something other than football in bad weather STBS - What has been your greatest achievement in snooker? GL - A win over Jonathan Barron and winning the Bill Toms STBS - Who is the most famous professional player you have played or met? (can be modern or older era) GL - Doug Mountjoy and Judd Trump STBS - Who is your favourite TV commentator? GL - Willie Thorne, full of knowledge STBS - What is your Favourite professional player and why? GL - Ronnie O''Sullivan on form out of this world STBS - What has been the most memorable snooker match you have ever seen? GL - Alex Higgins v Jimmy White world semi final STBS - Who is the best player in the league? GL - Jonathan Barron a true gent who treated all with respect STBS -Who is the most under-rated player in the league? GL - Sorry can''t choose STBS - Funniest moment in your snooker experience? GL - Playing county doubles v Liskeard con club in one frame I did not get a shot as my opponent hit a 136 break in STBS - Who is your bogey player? GL - Anthony Maddams STBS - Do you have any snooker ambitions you still have not achieved? GL - Unable to play well now so will try to be as good a chairman as possible Thank you George for your candid answers Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Graham Taylor', 'cueview-graham-taylor', 'Cue View', '[]'::jsonb, 'It''s been a while since we have had any new CueViews from the players of St Blazey Victory League but today Graham Taylor of Bugle B gives his thoughts and views for us all to read.', null, '"Dave Rundle dribbling a mouthful of beer down the back of a young lads trousers. They were halfway down his backside like how most of today’s youth where them and suffice to say Dave’s aim was spot on – cold beer right down the crack! The surprised victim jumped up with an ooh and cries of laughter and spent the rest of the frame hitching his trousers up and looking around for his attacker lol”"', 'It''s been a while since we have had any new CueViews from the players of St Blazey Victory League but today Graham Taylor of Bugle B gives his thoughts and views for us all to read.

more STBS - What is your full name please GT - Graham John Taylor STBS - Your Current Club/base GT - Bugle WMC STBS - Your Highest Break GT - 100 STBS - Are you Left/Right Handed or both GT - Right handed STBS - Bio about yourself (in no more than 200 words) GT - Born in Reading and been living in Cornwall for about 11 years. Engaged to Louise and we have 6 children between us. Life is very busy!! I am currently a member of the Cornwall County A Pool Team and qualified for England trials last year. I can also play snooker quite well at times. I also like Speedway and Football. I also have a love for punk and new wave music much to the disgust of most of my team mates! STBS - What was your first ever memory of snooker? GT - My dad took me to the Reading Hexagon to see the World Team Classic or pairs event in the late seventies and early eighties with Steve Davis, Tony Meo, Doug Mountjoy, Higgins, Taylor, Thorburn etc etc. Saw most of the top names in this era as the Hexagon held many events in the following years. STBS - At what age did you start playing snooker and why? GT - Probably had my first knock when I was about 10 at what was the British Telecom club in Reading. My Dad again was responsible because he was a BT engineer and was a member. STBS - What has been your greatest achievement in snooker? GT - I joined a group of Pool players to play snooker in the league, probably about 15 years ago? I think we were Reading Snooker Club C Team. We won promotion to the top division and won the Ecott Cup (handicap cup) which had been running for many years and the trophy was huge. Apparently was a prestigious event to win. We also knocked out our A team on the way. This was in my first season playing in proper matches. Also as a Bugle player we were County Champions a couple of years ago and l won the winning frame. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) GT - Andy Hicks. Had him worried for a couple of minutes in an exhibition when I knocked in 19 before he cleared the table!! STBS - Who is your favourite TV commentator? GT - The late Whispering Ted Lowe. STBS - What is your Favourite professional player and why? GT - Jimmy White. Very quick with so much flair. STBS - What has been the most memorable snooker match you have ever seen? GT - Probably the Taylor / Davis final everyone mentions but also feeling Jimmy’s pain in the numerous world finals (think it was 6) he lost!! STBS - Who is the best player in the league? GT - Barry McIntosh, Andrew Best or Darren Lock. STBS -Who is the most under-rated player in the league? GT - Dave Rundle or Matt Fox STBS - Funniest moment in your snooker experience? GT - Dave Rundle dribbling a mouthful of beer down the back of a young lads trousers. They were halfway down his backside like how most of today’s youth where them and suffice to say Dave’s aim was spot on – cold beer right down the crack! The surprised victim jumped up with an ooh and cries of laughter and spent the rest of the frame hitching his trousers up and looking around for his attacker lol STBS - Who is your bogey player? GT - There are a couple. Jeff Hawken and I once had a 51 break against John Wilson and still lost. STBS - Do you have any snooker ambitions you still have not achieved? GT - 100 break in a match would be nice and because I don’t practice much these days it would be nice to reach a league singles final again. Lost in the final of the Bill Toms a few year ago. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Ian Ball', 'cueview-ian-ball', 'Cue View', '[]'::jsonb, 'Today marks the return of more CueViews, this time it''s the turn of Bugle B marksman Ian Ball', null, '"At St. Blazey playing the brown I couldn’t quite reach so had to put my leg up. As I did I broke wind in front of league secretary Gordon Boynton. The report in the guardian read ”Ian Ball played an explosive frame”"', 'Today marks the return of more CueViews, this time it''s the turn of Bugle B marksman Ian Ball

more STBS - What is your full name please IB - Ian Ball STBS - Your Current Club/base IB - Always played for Bugle club STBS - Your Highest Break IB - 135 practicing on my own but 83 is my highest against someone also in practice STBS - Are you Left/Right Handed or both IB - Right but have been known to play pool one handed using only my right hand my STBS - Bio about yourself (in no more than 200 words) IB - Been playing in the league for 29 years and have only missed 2 games. Entered twice and won the under 21s twice. Won 2 county team titles and numerous league team titles. Runner up twice in the singles and 4 times in the Bill Toms (3 in a row) STBS - What was your first ever memory of snooker? IB - Around 35 years ago at Polzeath caravan park. The table is huge when you’re 8 or 9. STBS - At what age did you start playing snooker and why? IB - My dad made me a table when I was 13. STBS - What has been your greatest achievement in snooker? IB - Stuffing Alan Wills 2-0 or beating Richard Opie 3-1 on his own, Tregonissey, table to reach the singles final. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) IB - Met and got Steve Davis’ autograph. Only pro I’ve played is Andy Hicks STBS - Who is your favourite TV commentator? IB - The late great whispering Ted Lowe STBS - What is your Favourite professional player and why? IB - Ronnie O’Sullivan or Judd Trump most of the others bore me STBS - What has been the most memorable snooker match you have ever seen? IB - Taylor v Davis. World final 1985 STBS - Who is the best player in the league? IB - Andrew Best. Been at the top for a good 25 years STBS -Who is the most under-rated player in the league? IB - Bugle C player Jake Moore STBS - Funniest moment in your snooker experience? IB - At St. Blazey playing the brown I couldn’t quite reach so had to put my leg up. As I did I broke wind in front of league secretary Gordon Boynton. The report in the guardian read ”Ian Ball played an explosive frame” STBS - Who is your bogey player? IB - Paul Baron and I always seem to draw him STBS - Do you have any snooker ambitions you still have not achieved? IB - I WANT THAT BILL TOMS CUP Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
